--
-- Table structure for table `hs_math_train_items`
--

DROP TABLE IF EXISTS `hs_math_train_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hs_math_train_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(64) NOT NULL,
  `pool` varchar(16) NOT NULL DEFAULT 'formal' COMMENT 'formal|test',
  `qtype` varchar(16) NOT NULL COMMENT 'single|multi|judge|numeric',
  `stem` text NOT NULL,
  `options_json` json DEFAULT NULL,
  `answer_payload_json` json NOT NULL COMMENT '???????',
  `analysis` text,
  `source_type` varchar(16) NOT NULL DEFAULT 'original' COMMENT 'original|adapted|past_exam',
  `source_year` smallint unsigned DEFAULT NULL COMMENT '考试年份，可空',
  `source_exam_name` varchar(128) DEFAULT NULL COMMENT '试卷名称',
  `source_question_no` varchar(32) DEFAULT NULL COMMENT '题号',
  `source_reference` varchar(512) DEFAULT NULL COMMENT '出处/出版信息/链接，管理员可见',
  `source_adaptation_note` varchar(512) DEFAULT NULL COMMENT '改编说明',
  `source_verification_status` varchar(16) NOT NULL DEFAULT 'unverified' COMMENT 'unverified|verified|rejected',
  `source_license_status` varchar(16) NOT NULL DEFAULT 'unknown' COMMENT 'unknown|permitted|restricted|forbidden',
  `difficulty` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '1?? 2?? 3??',
  `specialty_id` bigint unsigned NOT NULL,
  `category_id` bigint unsigned NOT NULL,
  `knowledge_point_id` bigint unsigned DEFAULT NULL COMMENT 'P0????FK',
  `status` varchar(32) NOT NULL DEFAULT 'draft' COMMENT 'draft|approved|disabled',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `grade_rule_version` varchar(16) NOT NULL DEFAULT 'v1',
  `content_version` int NOT NULL DEFAULT '1',
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `reviewed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hs_math_train_item_code` (`code`),
  KEY `idx_hs_math_train_item_pool` (`pool`,`status`,`is_active`),
  KEY `idx_hs_math_train_item_spec_cat` (`specialty_id`,`category_id`,`difficulty`),
  KEY `fk_hs_math_train_item_cat` (`category_id`),
  KEY `idx_hs_math_item_source_type` (`source_type`,`source_verification_status`,`source_license_status`),
  CONSTRAINT `fk_hs_math_train_item_cat` FOREIGN KEY (`category_id`) REFERENCES `hs_math_categories` (`id`),
  CONSTRAINT `fk_hs_math_train_item_sp` FOREIGN KEY (`specialty_id`) REFERENCES `hs_math_specialties` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=375 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
