INSERT INTO `hs_math_train_items` VALUES (1,'HS_MATH_P0_E2E_TEST_single','formal','single','HS_MATH_P0_E2E_TEST single 题干','{\"options\": [{\"id\": \"A\", \"text\": \"选项A-E2E\"}, {\"id\": \"B\", \"text\": \"选项B-E2E\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:41.935','2026-10-24 09:30:41.433','2026-10-24 10:39:14.916'),(2,'HS_MATH_P0_E2E_TEST_multi','formal','multi','HS_MATH_P0_E2E_TEST multi 题干','{\"options\": [{\"id\": \"A\", \"text\": \"A\"}, {\"id\": \"B\", \"text\": \"B\"}, {\"id\": \"C\", \"text\": \"C\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\"]}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:42.208','2026-10-24 09:30:41.507','2026-10-24 10:39:14.916'),(3,'HS_MATH_P0_E2E_TEST_judge','formal','judge','HS_MATH_P0_E2E_TEST judge 题干',NULL,'{\"kind\": \"judge\", \"value\": true}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:42.457','2026-10-24 09:30:41.605','2026-10-24 10:39:14.916'),(4,'HS_MATH_P0_E2E_TEST_numeric','formal','numeric','HS_MATH_P0_E2E_TEST numeric 题干',NULL,'{\"kind\": \"numeric\", \"value\": \"1.5\", \"toleranceAbs\": 0.01, \"toleranceRel\": 0}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:42.573','2026-10-24 09:30:41.697','2026-10-24 10:39:14.916'),(5,'HS_MATH_P0_E2E_TEST_single2','formal','single','HS_MATH_P0_E2E_TEST single2 填充','{\"options\": [{\"id\": \"A\", \"text\": \"选项A-E2E\"}, {\"id\": \"B\", \"text\": \"选项B-E2E\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:42.636','2026-10-24 09:30:41.798','2026-10-24 10:39:14.916'),(26,'HSMA-RJA-CH01-0001','formal','single','下列对象中，能构成集合的是','{\"options\": [{\"id\": \"A\", \"text\": \"某班成绩很好的同学\"}, {\"id\": \"B\", \"text\": \"接近 $1$ 的实数\"}, {\"id\": \"C\", \"text\": \"方程 $x^{2}-1=0$ 的实数根\"}, {\"id\": \"D\", \"text\": \"个子较高的人\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','集合的元素必须具有确定性。方程 $x^{2}-1=0$ 的实数根是 $-1$ 与 $1$，对象明确。A、B、D 中“很好”“接近”“较高”含义不唯一，不能构成集合。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.078','2026-10-24 17:00:31.078'),(27,'HSMA-RJA-CH01-0002','formal','single','设 $A=\\{1,2,3\\}$，则下列正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$1\\\\subset A$\"}, {\"id\": \"B\", \"text\": \"$1\\\\in A$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1\\\\}\\\\in A$\"}, {\"id\": \"D\", \"text\": \"$\\\\{1,2\\\\}\\\\in A$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','元素与集合用 $\\in$；集合与集合用 $\\subseteq$ 或 $\\subset$。$1$ 是 $A$ 的元素，故 $1\\in A$。$\\{1\\}$ 是集合，应写作 $\\{1\\}\\subseteq A$，不能写成 $\\{1\\}\\in A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.084','2026-10-24 17:00:31.084'),(28,'HSMA-RJA-CH01-0003','formal','single','用列举法表示集合 $\\{x\\in\\mathbb{Z}\\mid -2\\le x<2\\}$，正确的是（$\\mathbb{Z}$ 表示整数集）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{-2,-1,0,1,2\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{-2,-1,0,1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{-1,0,1\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{-2,-1,0\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','条件为 $-2\\le x<2$ 且 $x$ 为整数，故 $x=-2,-1,0,1$，写作 $\\{-2,-1,0,1\\}$。不含 $2$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.088','2026-10-24 17:00:31.088'),(29,'HSMA-RJA-CH01-0004','formal','single','下列用描述法表示集合正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{x\\\\mid x^{2}=1\\\\}$（未指明数集时默认在实数范围内讨论）\"}, {\"id\": \"B\", \"text\": \"$\\\\{x\\\\mid x$ 是较大的正整数$\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{x\\\\mid x$ 接近 $0\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{x\\\\mid x$ 是好看的图形$\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','高中默认在实数集讨论时，$x^{2}=1$ 的解为 $\\pm 1$，属性确定。其余选项含模糊用语，不能作为集合的描述条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.093','2026-10-24 17:00:31.093'),(30,'HSMA-RJA-CH01-0005','formal','single','关于空集 $\\varnothing$，正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing$ 不含任何元素\"}, {\"id\": \"B\", \"text\": \"$\\\\varnothing=\\\\{0\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\varnothing=\\\\{\\\\varnothing\\\\}$\"}, {\"id\": \"D\", \"text\": \"$0\\\\in\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','空集是不含任何元素的集合。$\\{0\\}$ 含元素 $0$；$\\{\\varnothing\\}$ 含元素 $\\varnothing$，都不是空集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,3,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.097','2026-10-24 17:00:31.097'),(31,'HSMA-RJA-CH01-0006','formal','single','设 $A=\\{a,b\\}$，且 $a\\ne b$。下列说法正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$A$ 有 $2$ 个元素\"}, {\"id\": \"B\", \"text\": \"若再写入 $a$，则 $A$ 有 $3$ 个元素\"}, {\"id\": \"C\", \"text\": \"集合中元素可以重复计数\"}, {\"id\": \"D\", \"text\": \"$\\\\{a,a,b\\\\}$ 与 $A$ 元素个数不同\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','集合元素具有互异性：$\\{a,a,b\\}=\\{a,b\\}$，仍是 $2$ 个元素。不能因书写重复而增加元素个数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.102','2026-10-24 17:00:31.102'),(32,'HSMA-RJA-CH01-0007','formal','single','常用数集中，$\\mathbb{N}$、$\\mathbb{Z}$、$\\mathbb{Q}$、$\\mathbb{R}$ 分别表示自然数集、整数集、有理数集、实数集。下列正确的是（本题约定 $\\mathbb{N}$ 含 $0$）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\mathbb{N}\\\\subseteq\\\\mathbb{Z}\\\\subseteq\\\\mathbb{Q}\\\\subseteq\\\\mathbb{R}$\"}, {\"id\": \"B\", \"text\": \"$\\\\mathbb{R}\\\\subseteq\\\\mathbb{Q}$\"}, {\"id\": \"C\", \"text\": \"$\\\\sqrt{2}\\\\in\\\\mathbb{Q}$\"}, {\"id\": \"D\", \"text\": \"$-3\\\\in\\\\mathbb{N}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','在含 $0$ 的约定下，自然数都是整数，整数都是有理数，有理数都是实数，故包含链成立。$\\sqrt{2}$ 不是有理数；$-3$ 不是自然数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.105','2026-10-24 17:00:31.105'),(33,'HSMA-RJA-CH01-0008','formal','single','设集合 $A=\\{x\\mid x=2k+1,\\,k\\in\\mathbb{Z}\\}$（奇数集）。则 $-5\\in A$ 的判断是','{\"options\": [{\"id\": \"A\", \"text\": \"正确\"}, {\"id\": \"B\", \"text\": \"错误\"}, {\"id\": \"C\", \"text\": \"无法判断\"}, {\"id\": \"D\", \"text\": \"仅当 $k>0$ 时正确\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','取 $k=-3$，则 $2k+1=-5$，故 $-5\\in A$。奇数集包含负奇数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.110','2026-10-24 17:00:31.110'),(34,'HSMA-RJA-CH01-0009','formal','multi','下列可以作为集合的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"小于 $10$ 的正整数\"}, {\"id\": \"B\", \"text\": \"方程 $x^{2}+1=0$ 的实数根\"}, {\"id\": \"C\", \"text\": \"著名的数学家\"}, {\"id\": \"D\", \"text\": \"平面内到定点距离等于定长的点\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','A：正整数 $1$ 到 $9$，确定。B：实数范围内无解，为空集，仍是集合。D：圆上的点，几何属性确定。C：“著名”不唯一，不能构成集合。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.114','2026-10-24 17:00:31.114'),(35,'HSMA-RJA-CH01-0010','formal','multi','关于集合表示法，正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"列举法适合元素不多的集合\"}, {\"id\": \"B\", \"text\": \"描述法用元素的共同属性刻画集合\"}, {\"id\": \"C\", \"text\": \"无限集一定不能用列举法表示\"}, {\"id\": \"D\", \"text\": \"$\\\\{1,2,3\\\\}$ 是列举法\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','列举法与描述法是基本表示法。无限集有时可写省略号列举（如正偶数），故 C 过绝对。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.119','2026-10-24 17:00:31.119'),(36,'HSMA-RJA-CH01-0011','formal','multi','设 $A=\\{\\varnothing\\}$。下列正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing\\\\in A$\"}, {\"id\": \"B\", \"text\": \"$\\\\varnothing\\\\subseteq A$\"}, {\"id\": \"C\", \"text\": \"$A=\\\\varnothing$\"}, {\"id\": \"D\", \"text\": \"$A$ 含有 $1$ 个元素\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','$A=\\{\\varnothing\\}$ 的唯一元素是空集，故 $\\varnothing\\in A$，且 $|A|=1$。空集是任何集合的子集，故 $\\varnothing\\subseteq A$。但 $A$ 不是空集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,3,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.122','2026-10-24 17:00:31.122'),(37,'HSMA-RJA-CH01-0012','formal','judge','集合 $\\{1,2,3\\}$ 与集合 $\\{3,2,1\\}$ 是同一个集合。',NULL,'{\"kind\": \"judge\", \"value\": true}','集合元素具有无序性：只要元素完全相同，书写顺序不同仍表示同一个集合，因此两者相等。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.126','2026-10-24 17:00:31.126'),(38,'HSMA-RJA-CH01-0013','formal','judge','空集是任何一个集合的元素。',NULL,'{\"kind\": \"judge\", \"value\": false}','空集是任何一个集合的子集（$\\varnothing\\subseteq A$），但不一定是元素。例如 $1\\notin\\{1,2\\}$ 同理，$\\varnothing\\notin\\{1,2\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,3,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.130','2026-10-24 17:00:31.130'),(39,'HSMA-RJA-CH01-0014','formal','judge','用描述法表示集合时，必须写清代表元素所属的范围（或约定默认范围）。',NULL,'{\"kind\": \"judge\", \"value\": true}','描述法依赖属性与论域；论域不清会导致集合不明确。教材书写常写 $x\\in\\mathbb{R}$ 等。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.133','2026-10-24 17:00:31.133'),(40,'HSMA-RJA-CH01-0015','formal','numeric','集合 $\\{2,4,6,8\\}$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','该集合含 $2,4,6,8$ 四个互不相同的元素，由元素互异性知其元素个数为 $4$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.137','2026-10-24 17:00:31.137'),(41,'HSMA-RJA-CH01-0016','formal','numeric','集合 $\\{x\\in\\mathbb{Z}\\mid 0<x\\le 5\\}$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','正整数（本题由 $0<x$ 且整数得到）$1,2,3,4,5$，共 $5$ 个。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.141','2026-10-24 17:00:31.141'),(42,'HSMA-RJA-CH01-0017','formal','single','若 $A\\subseteq B$，则下列一定正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$A$ 的任意元素都属于 $B$\"}, {\"id\": \"B\", \"text\": \"$A$ 一定是 $B$ 的真子集\"}, {\"id\": \"C\", \"text\": \"$B\\\\subseteq A$\"}, {\"id\": \"D\", \"text\": \"$A$ 与 $B$ 元素个数一定相等\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A\\subseteq B$ 的定义是：$A$ 中任一元素都属于 $B$。真子集还需 $A\\ne B$，故不一定是真子集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.145','2026-10-24 17:00:31.145'),(43,'HSMA-RJA-CH01-0018','formal','single','设 $A=\\{1,2\\}$，$B=\\{1,2,3\\}$，则','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\subsetneq B$（$A$ 是 $B$ 的真子集）\"}, {\"id\": \"B\", \"text\": \"$B\\\\subseteq A$\"}, {\"id\": \"C\", \"text\": \"$A=B$\"}, {\"id\": \"D\", \"text\": \"$3\\\\in A$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A$ 的元素都属于 $B$，且 $3\\in B$ 但 $3\\notin A$，故 $A$ 是 $B$ 的真子集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.148','2026-10-24 17:00:31.148'),(44,'HSMA-RJA-CH01-0019','formal','single','集合 $A=B$ 的充要条件是','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\subseteq B$ 且 $B\\\\subseteq A$\"}, {\"id\": \"B\", \"text\": \"仅 $A\\\\subseteq B$\"}, {\"id\": \"C\", \"text\": \"仅 $A$ 与 $B$ 元素个数相等\"}, {\"id\": \"D\", \"text\": \"$A\\\\cap B=\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','两集合相等的充要条件是互相包含。仅有 $A\\subseteq B$ 不够；元素个数相等也不能保证元素相同。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,5,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.151','2026-10-24 17:00:31.151'),(45,'HSMA-RJA-CH01-0020','formal','single','下列说法正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing\\\\subseteq\\\\{1\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\varnothing\\\\in\\\\{1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{\\\\varnothing\\\\}=\\\\varnothing$\"}, {\"id\": \"D\", \"text\": \"$1\\\\subseteq\\\\{1\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','空集是任何集合的子集。$\\varnothing$ 不是 $\\{1\\}$ 的元素；$\\{\\varnothing\\}$ 非空；$1$ 是元素不是集合，不能写 $1\\subseteq\\{1\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.155','2026-10-24 17:00:31.155'),(46,'HSMA-RJA-CH01-0021','formal','single','设集合 $A$ 含有 $3$ 个元素，则 $A$ 的子集个数是','{\"options\": [{\"id\": \"A\", \"text\": \"$3$\"}, {\"id\": \"B\", \"text\": \"$6$\"}, {\"id\": \"C\", \"text\": \"$8$\"}, {\"id\": \"D\", \"text\": \"$9$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','含 $n$ 个元素的集合有 $2^{n}$ 个子集。$n=3$ 时为 $2^{3}=8$（含空集与自身）。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.159','2026-10-24 17:00:31.159'),(47,'HSMA-RJA-CH01-0022','formal','single','设集合 $A$ 含有 $3$ 个元素，则 $A$ 的真子集个数是','{\"options\": [{\"id\": \"A\", \"text\": \"$7$\"}, {\"id\": \"B\", \"text\": \"$8$\"}, {\"id\": \"C\", \"text\": \"$6$\"}, {\"id\": \"D\", \"text\": \"$3$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','真子集是不等于自身的子集，个数为 $2^{n}-1$。$n=3$ 时为 $7$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.162','2026-10-24 17:00:31.162'),(48,'HSMA-RJA-CH01-0023','formal','single','若 $\\{1,2\\}\\subseteq A\\subseteq\\{1,2,3\\}$，则集合 $A$ 的可能情况种数是','{\"options\": [{\"id\": \"A\", \"text\": \"$1$\"}, {\"id\": \"B\", \"text\": \"$2$\"}, {\"id\": \"C\", \"text\": \"$3$\"}, {\"id\": \"D\", \"text\": \"$4$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','$A$ 必须含 $1,2$，对 $3$ 可取可不取，故 $A=\\{1,2\\}$ 或 $\\{1,2,3\\}$，共 $2$ 种。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.165','2026-10-24 17:00:31.165'),(49,'HSMA-RJA-CH01-0024','formal','single','设 $A=\\{x\\mid x^{2}-3x+2=0\\}$，$B=\\{1,2\\}$，则','{\"options\": [{\"id\": \"A\", \"text\": \"$A=B$\"}, {\"id\": \"B\", \"text\": \"$A\\\\subsetneq B$\"}, {\"id\": \"C\", \"text\": \"$B\\\\subsetneq A$\"}, {\"id\": \"D\", \"text\": \"$A\\\\cap B=\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$x^{2}-3x+2=(x-1)(x-2)=0$，得 $x=1$ 或 $2$，故 $A=\\{1,2\\}=B$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,32,5,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.169','2026-10-24 17:00:31.169'),(50,'HSMA-RJA-CH01-0025','formal','multi','设 $A=\\{a\\}$。下列正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing\\\\subseteq A$\"}, {\"id\": \"B\", \"text\": \"$A\\\\subseteq A$\"}, {\"id\": \"C\", \"text\": \"$\\\\{a\\\\}\\\\subseteq A$\"}, {\"id\": \"D\", \"text\": \"$a\\\\subseteq A$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','任何集合是自身的子集；空集是子集；$\\{a\\}=A$ 故也成立。$a$ 是元素，不能写 $a\\subseteq A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.173','2026-10-24 17:00:31.173'),(51,'HSMA-RJA-CH01-0026','formal','multi','下列关系正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{1\\\\}\\\\subseteq\\\\{1,2\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{1,2\\\\}=\\\\{2,1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1\\\\}\\\\in\\\\{1,2\\\\}$\"}, {\"id\": \"D\", \"text\": \"$1\\\\in\\\\{1,2\\\\}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','子集与相等成立；$1$ 属于该集合。但 $\\{1\\}$ 不是 $\\{1,2\\}$ 的元素，C 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,5,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.450','2026-10-24 17:00:31.450'),(52,'HSMA-RJA-CH01-0027','formal','multi','设 $A=\\{1,2,3\\}$。下列是 $A$ 的真子集的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing$\"}, {\"id\": \"B\", \"text\": \"$\\\\{1,2\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1,2,3\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{2\\\\}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','真子集不能等于自身，故排除 C。空集与真子集 $\\{1,2\\}$、$\\{2\\}$ 均正确。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.454','2026-10-24 17:00:31.454'),(53,'HSMA-RJA-CH01-0028','formal','judge','若 $A\\subseteq B$ 且 $B\\subseteq A$，则 $A=B$。',NULL,'{\"kind\": \"judge\", \"value\": true}','互相包含正是集合相等的定义：一边包含保证元素关系，两边同时成立则两集合相同。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,5,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.456','2026-10-24 17:00:31.456'),(54,'HSMA-RJA-CH01-0029','formal','judge','空集没有真子集。',NULL,'{\"kind\": \"judge\", \"value\": true}','空集的子集只有它自身，真子集个数为 $2^{0}-1=0$，因此空集没有真子集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.459','2026-10-24 17:00:31.459'),(55,'HSMA-RJA-CH01-0030','formal','numeric','集合 $\\{a,b\\}$（$a\\ne b$）的子集个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','元素个数 $n=2$，子集个数为 $2^{2}=4$，分别是 $\\varnothing,\\{a\\},\\{b\\},\\{a,b\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.462','2026-10-24 17:00:31.462'),(56,'HSMA-RJA-CH01-0031','formal','numeric','集合 $\\{1,2,3,4\\}$ 的真子集个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"15\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','元素个数 $n=4$，真子集个数为 $2^{4}-1=15$（去掉集合自身）。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.465','2026-10-24 17:00:31.465'),(57,'HSMA-RJA-CH01-0032','formal','numeric','若集合 $A$ 的子集共有 $16$ 个，则 $A$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','由子集个数公式 $2^{n}=16$，解得元素个数 $n=4$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.468','2026-10-24 17:00:31.468'),(58,'HSMA-RJA-CH01-0033','formal','single','设 $A=\\{1,2,3\\}$，$B=\\{2,3,4\\}$，则 $A\\cup B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{2,3\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{1,2,3,4\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1,4\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','并集由属于 $A$ 或属于 $B$ 的全部元素组成，枚举得 $\\{1,2,3,4\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.471','2026-10-24 17:00:31.471'),(59,'HSMA-RJA-CH01-0034','formal','single','设 $A=\\{1,2,3\\}$，$B=\\{2,3,4\\}$，则 $A\\cap B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{1,2,3,4\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{2,3\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1,4\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{1,2,3\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','交集由同时属于 $A$ 与 $B$ 的元素组成，公共元素为 $2,3$，故为 $\\{2,3\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.474','2026-10-24 17:00:31.474'),(60,'HSMA-RJA-CH01-0035','formal','single','设全集 $U=\\{1,2,3,4,5\\}$，$A=\\{1,2,3\\}$，则 $\\complement_{U}A=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{1,2,3\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{4,5\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{3,4,5\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','在给定全集 $U$ 下，补集是 $U$ 中不属于 $A$ 的元素，因此为 $\\{4,5\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.477','2026-10-24 17:00:31.477'),(61,'HSMA-RJA-CH01-0036','formal','single','设 $A=\\{x\\mid x>1\\}$，$B=\\{x\\mid x\\le 3\\}$（$x\\in\\mathbb{R}$），则 $A\\cap B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{x\\\\mid 1<x\\\\le 3\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{x\\\\mid x>1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{x\\\\mid x\\\\le 3\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{x\\\\mid x>3\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','交集需同时满足 $x>1$ 与 $x\\le 3$，合取后得到 $1<x\\le 3$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.480','2026-10-24 17:00:31.480'),(62,'HSMA-RJA-CH01-0037','formal','single','设 $A=\\{x\\mid x<2\\}$，$B=\\{x\\mid x\\ge 0\\}$（$x\\in\\mathbb{R}$），则 $A\\cup B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\mathbb{R}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{x\\\\mid 0\\\\le x<2\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{x\\\\mid x<0\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','小于 $2$ 的实数与不小于 $0$ 的实数并起来覆盖全体实数，故为 $\\mathbb{R}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.483','2026-10-24 17:00:31.483'),(63,'HSMA-RJA-CH01-0038','formal','single','设全集 $U=\\mathbb{R}$，$A=\\{x\\mid x\\le 1\\}$，则 $\\complement_{U}A=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{x\\\\mid x>1\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{x\\\\mid x\\\\ge 1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{x\\\\mid x<1\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{x\\\\mid x\\\\le 1\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','补集为不满足 $x\\le 1$ 的实数，即 $x>1$。注意端点：$1\\in A$，故 $1$ 不在补集中。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.487','2026-10-24 17:00:31.487'),(64,'HSMA-RJA-CH01-0039','formal','single','设 $A\\cap B=A$，则一定有','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\subseteq B$\"}, {\"id\": \"B\", \"text\": \"$B\\\\subseteq A$\"}, {\"id\": \"C\", \"text\": \"$A=B$\"}, {\"id\": \"D\", \"text\": \"$A\\\\cup B=A$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A\\cap B=A$ 等价于 $A$ 的元素都属于 $B$，即 $A\\subseteq B$。由该式不能推出 $A=B$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.491','2026-10-24 17:00:31.491'),(65,'HSMA-RJA-CH01-0040','formal','single','设 $A\\cup B=A$，则一定有','{\"options\": [{\"id\": \"A\", \"text\": \"$B\\\\subseteq A$\"}, {\"id\": \"B\", \"text\": \"$A\\\\subseteq B$\"}, {\"id\": \"C\", \"text\": \"$A\\\\cap B=\\\\varnothing$\"}, {\"id\": \"D\", \"text\": \"$A=B$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A\\cup B=A$ 等价于 $B$ 的元素都属于 $A$，即 $B\\subseteq A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.496','2026-10-24 17:00:31.496'),(66,'HSMA-RJA-CH01-0041','formal','single','设全集 $U=\\{1,2,3,4,5,6\\}$，$A=\\{1,3,5\\}$，$B=\\{1,2,3\\}$，则 $\\complement_{U}(A\\cup B)=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{4,6\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{2,4,6\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{4,5,6\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{6\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A\\cup B=\\{1,2,3,5\\}$，在 $U$ 中的补集为 $\\{4,6\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,33,9,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.499','2026-10-24 17:00:31.499'),(67,'HSMA-RJA-CH01-0042','formal','single','设全集 $U=\\{a,b,c,d\\}$，$A=\\{a,b\\}$，$B=\\{b,c\\}$，则 $(\\complement_{U}A)\\cap B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{c\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{b,c\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{a\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$\\complement_{U}A=\\{c,d\\}$，与 $B=\\{b,c\\}$ 交得 $\\{c\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,33,9,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.606','2026-10-24 17:00:31.606'),(68,'HSMA-RJA-CH01-0043','formal','multi','设 $A=\\{1,2\\}$，$B=\\{2,3\\}$。正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$2\\\\in A\\\\cup B$\"}, {\"id\": \"B\", \"text\": \"$2\\\\in A\\\\cap B$\"}, {\"id\": \"C\", \"text\": \"$1\\\\in A\\\\cap B$\"}, {\"id\": \"D\", \"text\": \"$3\\\\in A\\\\cup B$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','$A\\cup B=\\{1,2,3\\}$，$A\\cap B=\\{2\\}$。故 $1$ 不在交集中。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.611','2026-10-24 17:00:31.611'),(69,'HSMA-RJA-CH01-0044','formal','multi','设全集 $U=\\{1,2,3,4\\}$，$A=\\{1,2\\}$。正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$3\\\\in\\\\complement_{U}A$\"}, {\"id\": \"B\", \"text\": \"$1\\\\notin\\\\complement_{U}A$\"}, {\"id\": \"C\", \"text\": \"$\\\\complement_{U}A=\\\\{3,4\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\complement_{U}A=\\\\{2,3,4\\\\}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','$\\complement_{U}A=\\{3,4\\}$，$1\\in A$ 故不属于补集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.614','2026-10-24 17:00:31.614'),(70,'HSMA-RJA-CH01-0045','formal','multi','下列运算恒成立的是（多选；对任意集合 $A,B$）','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\cap B=B\\\\cap A$\"}, {\"id\": \"B\", \"text\": \"$A\\\\cup B=B\\\\cup A$\"}, {\"id\": \"C\", \"text\": \"$A\\\\cap\\\\varnothing=\\\\varnothing$\"}, {\"id\": \"D\", \"text\": \"$A\\\\cup\\\\varnothing=\\\\varnothing$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','交、并满足交换律；任意集合与空集的交仍为空集。并上空集应得到原集合 $A$，故 D 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.617','2026-10-24 17:00:31.617'),(71,'HSMA-RJA-CH01-0046','formal','multi','设 $A=\\{1,2,3,4\\}$，$B=\\{3,4,5\\}$。正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\cup B=\\\\{1,2,3,4,5\\\\}$\"}, {\"id\": \"B\", \"text\": \"$A\\\\cap B=\\\\{3,4\\\\}$\"}, {\"id\": \"C\", \"text\": \"$(A\\\\cup B)\\\\cap A=A$\"}, {\"id\": \"D\", \"text\": \"$A\\\\cap B=A$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','并、交直接计算得 A、B。$(A\\cup B)\\cap A=A$ 恒成立。$A\\cap B\\ne A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,33,9,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.622','2026-10-24 17:00:31.622'),(72,'HSMA-RJA-CH01-0047','formal','judge','对任意集合 $A$，都有 $A\\cup A=A$ 且 $A\\cap A=A$。',NULL,'{\"kind\": \"judge\", \"value\": true}','并、交满足幂等律：集合与自身取并或取交，结果仍是原来的集合 $A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.626','2026-10-24 17:00:31.626'),(73,'HSMA-RJA-CH01-0048','formal','judge','若全集为 $U$，则 $\\complement_{U}(\\complement_{U}A)=A$。',NULL,'{\"kind\": \"judge\", \"value\": true}','在同一全集下，补集运算具有对合性：对补集再取补，回到原集合 $A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.629','2026-10-24 17:00:31.629'),(74,'HSMA-RJA-CH01-0049','formal','numeric','设 $A=\\{1,2,3\\}$，$B=\\{3,4\\}$，则 $A\\cup B$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','先求并集 $A\\cup B=\\{1,2,3,4\\}$，其中互异元素共 $4$ 个。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.632','2026-10-24 17:00:31.632'),(75,'HSMA-RJA-CH01-0050','formal','numeric','设 $A=\\{1,2,3,4\\}$，$B=\\{2,4,6\\}$，则 $A\\cap B$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"2\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','先求交集 $A\\cap B=\\{2,4\\}$，公共元素共 $2$ 个。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.635','2026-10-24 17:00:31.635'),(76,'HSMA-RJA-CH01-0051','formal','numeric','设全集 $U=\\{1,2,3,4,5,6,7,8\\}$，$A=\\{2,4,6,8\\}$，则 $\\complement_{U}A$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$U$ 中去掉 $A$ 的偶数后剩奇数 $\\{1,3,5,7\\}$，元素个数为 $4$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.638','2026-10-24 17:00:31.638'),(77,'HSMA-RJA-CH01-0052','formal','numeric','设 $A=\\{1,2,3,4,5\\}$，$B=\\{4,5,6,7\\}$，则属于 $A\\cup B$ 但不属于 $A\\cap B$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$A\\cup B=\\{1,2,3,4,5,6,7\\}$（$7$ 个），$A\\cap B=\\{4,5\\}$（$2$ 个），对称差元素个数为 $7-2=5$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,33,9,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.640','2026-10-24 17:00:31.640'),(78,'HSMA-RJA-CH01-0053','formal','single','已知 $p\\Rightarrow q$。就“充分条件”而言，正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$p$ 是 $q$ 的充分条件\"}, {\"id\": \"B\", \"text\": \"$p$ 是 $q$ 的必要条件\"}, {\"id\": \"C\", \"text\": \"$q$ 是 $p$ 的充分条件\"}, {\"id\": \"D\", \"text\": \"$p$ 与 $q$ 互为充要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','由定义：若 $p\\Rightarrow q$，则称 $p$ 是 $q$ 的充分条件；同时 $q$ 是 $p$ 的必要条件，但本题问充分条件对应项。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.644','2026-10-24 17:00:31.644'),(79,'HSMA-RJA-CH01-0054','formal','single','已知 $p\\Rightarrow q$。就“必要条件”而言，正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$q$ 是 $p$ 的必要条件\"}, {\"id\": \"B\", \"text\": \"$q$ 是 $p$ 的充分条件\"}, {\"id\": \"C\", \"text\": \"$p$ 是 $q$ 的必要条件\"}, {\"id\": \"D\", \"text\": \"$p\\\\Leftrightarrow q$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','由 $p\\Rightarrow q$ 的定义可知：$q$ 是 $p$ 成立的必要条件，不能把充分与必要的方向弄反。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,11,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.647','2026-10-24 17:00:31.647'),(80,'HSMA-RJA-CH01-0055','formal','single','“$x=1$”是“$x^{2}=1$”的','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要条件\"}, {\"id\": \"B\", \"text\": \"必要不充分条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','若 $x=1$，则 $x^{2}=1$，充分。但 $x^{2}=1$ 时还可能 $x=-1$，故不必要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.650','2026-10-24 17:00:31.650'),(81,'HSMA-RJA-CH01-0056','formal','single','“$x>2$”是“$x>1$”的（$x\\in\\mathbb{R}$）','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要条件\"}, {\"id\": \"B\", \"text\": \"必要不充分条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','由 $x>2$ 可推出 $x>1$，充分。但 $x=1.5$ 满足 $x>1$ 却不满足 $x>2$，故不必要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.654','2026-10-24 17:00:31.654'),(82,'HSMA-RJA-CH01-0057','formal','single','“$x>1$”是“$x>2$”的（$x\\in\\mathbb{R}$）','{\"options\": [{\"id\": \"A\", \"text\": \"必要不充分条件\"}, {\"id\": \"B\", \"text\": \"充分不必要条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','若 $x>2$ 则必有 $x>1$，故“$x>1$”是必要的；但 $x>1$ 推不出 $x>2$，故不充分。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,11,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.657','2026-10-24 17:00:31.657'),(83,'HSMA-RJA-CH01-0058','formal','single','“四边形是正方形”是“四边形是矩形”的','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要条件\"}, {\"id\": \"B\", \"text\": \"必要不充分条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','正方形一定是矩形，故充分；矩形未必是正方形，故不必要。因此是充分不必要条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.660','2026-10-24 17:00:31.660'),(84,'HSMA-RJA-CH01-0059','formal','single','设 $x\\in\\mathbb{R}$。“$x^{2}=0$”是“$x=0$”的','{\"options\": [{\"id\": \"A\", \"text\": \"充要条件\"}, {\"id\": \"B\", \"text\": \"充分不必要条件\"}, {\"id\": \"C\", \"text\": \"必要不充分条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','在实数范围内，$x^{2}=0\\Leftrightarrow x=0$，互为充要条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,12,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.663','2026-10-24 17:00:31.663'),(85,'HSMA-RJA-CH01-0060','formal','single','“$a>0$ 且 $b>0$”是“$ab>0$”的（$a,b\\in\\mathbb{R}$）','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要条件\"}, {\"id\": \"B\", \"text\": \"必要不充分条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','两正数乘积为正，充分。但 $a=-1,b=-2$ 时 $ab>0$ 却不满足同为正，故不必要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.666','2026-10-24 17:00:31.666'),(86,'HSMA-RJA-CH01-0061','formal','multi','下列说法正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"若 $p\\\\Rightarrow q$，则 $p$ 是 $q$ 的充分条件\"}, {\"id\": \"B\", \"text\": \"若 $p\\\\Rightarrow q$，则 $q$ 是 $p$ 的必要条件\"}, {\"id\": \"C\", \"text\": \"若 $p\\\\Leftrightarrow q$，则 $p$ 是 $q$ 的充要条件\"}, {\"id\": \"D\", \"text\": \"充分条件一定是必要条件\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A、B、C 均符合充分、必要、充要的定义。充分条件不必同时是必要条件，故 D 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,12,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.671','2026-10-24 17:00:31.671'),(87,'HSMA-RJA-CH01-0062','formal','multi','设 $x\\in\\mathbb{R}$。下列中，“$x>0$”是“$x\\ge 0$”的（多选表述正确项）','{\"options\": [{\"id\": \"A\", \"text\": \"充分条件\"}, {\"id\": \"B\", \"text\": \"必要条件\"}, {\"id\": \"C\", \"text\": \"充分不必要条件\"}, {\"id\": \"D\", \"text\": \"充要条件\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\"]}','$x>0\\Rightarrow x\\ge 0$，故充分；但 $x=0$ 使后者真前者假，故不必要。因此也是充分不必要。B、D 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.676','2026-10-24 17:00:31.676'),(88,'HSMA-RJA-CH01-0063','formal','multi','下列各组中，$p$ 是 $q$ 的必要条件的是（多选；设 $x\\in\\mathbb{R}$）','{\"options\": [{\"id\": \"A\", \"text\": \"$p:x>1$；$q:x>2$\"}, {\"id\": \"B\", \"text\": \"$p:x=1$；$q:x^{2}=1$\"}, {\"id\": \"C\", \"text\": \"$p:x\\\\ge 2$；$q:x>2$\"}, {\"id\": \"D\", \"text\": \"$p:x^{2}\\\\ge 0$；$q:x=1$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','若 $q\\Rightarrow p$，则 $p$ 是 $q$ 的必要条件。A：$x>2\\Rightarrow x>1$。C：$x>2\\Rightarrow x\\ge 2$。D：$x=1\\Rightarrow x^{2}\\ge 0$。B：$x^{2}=1$ 推不出 $x=1$，故不是必要条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,11,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.679','2026-10-24 17:00:31.679'),(89,'HSMA-RJA-CH01-0064','formal','multi','设 $x\\in\\mathbb{R}$。下列中 $p$ 是 $q$ 的充要条件的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$p:x=2$；$q:|x|=2$\"}, {\"id\": \"B\", \"text\": \"$p:x-1=0$；$q:x=1$\"}, {\"id\": \"C\", \"text\": \"$p:x^{2}=4$；$q:|x|=2$\"}, {\"id\": \"D\", \"text\": \"$p:x>1$；$q:x\\\\ge 1$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"B\", \"C\"]}','B：显然等价。C：在实数内 $x^{2}=4\\Leftrightarrow |x|=2$。A：$|x|=2$ 含 $x=-2$，不等价。D：一方更强，非充要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,34,12,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.682','2026-10-24 17:00:31.682'),(90,'HSMA-RJA-CH01-0065','formal','judge','若 $p$ 是 $q$ 的充分条件，则 $q$ 一定是 $p$ 的必要条件。',NULL,'{\"kind\": \"judge\", \"value\": true}','“$p$ 是 $q$ 的充分条件”即 $p\\Rightarrow q$，这同时意味着“$q$ 是 $p$ 的必要条件”。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,11,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.685','2026-10-24 17:00:31.685'),(91,'HSMA-RJA-CH01-0066','formal','judge','“$a=b$”是“$a^{2}=b^{2}$”的充要条件（$a,b\\in\\mathbb{R}$）。',NULL,'{\"kind\": \"judge\", \"value\": false}','由 $a=b$ 可得 $a^{2}=b^{2}$（充分），但由 $a^{2}=b^{2}$ 可能 $a=-b\\ne b$，故不必要，不是充要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,12,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.689','2026-10-24 17:00:31.689'),(92,'HSMA-RJA-CH01-0067','formal','judge','“两个三角形全等”是“两个三角形面积相等”的充分不必要条件。',NULL,'{\"kind\": \"judge\", \"value\": true}','全等的三角形面积一定相等，故充分；面积相等未必全等，故不必要。结论成立。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.691','2026-10-24 17:00:31.691'),(93,'HSMA-RJA-CH01-0068','formal','numeric','在实数范围内，使命题“若 $x>a$，则 $x>3$”对一切实数 $x$ 恒成立。满足条件的实数 $a$ 的最小值是',NULL,'{\"kind\": \"numeric\", \"value\": \"3\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','“$x>a\\Rightarrow x>3$”对一切 $x$ 成立，当且仅当 $a\\ge 3$。若 $a<3$，取 $x$ 满足 $a<x\\le 3$，则前提真结论假。故最小值为 $3$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.694','2026-10-24 17:00:31.694'),(94,'HSMA-RJA-CH01-0069','formal','single','命题“$\\forall x\\in\\mathbb{R},\\,x^{2}\\ge 0$”是','{\"options\": [{\"id\": \"A\", \"text\": \"真命题\"}, {\"id\": \"B\", \"text\": \"假命题\"}, {\"id\": \"C\", \"text\": \"无法判断\"}, {\"id\": \"D\", \"text\": \"条件命题\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','任意实数的平方都大于或等于 $0$，因此该全称量词命题为真命题。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.698','2026-10-24 17:00:31.698'),(95,'HSMA-RJA-CH01-0070','formal','single','命题“$\\exists x\\in\\mathbb{R},\\,x^{2}+1=0$”是','{\"options\": [{\"id\": \"A\", \"text\": \"假命题\"}, {\"id\": \"B\", \"text\": \"真命题\"}, {\"id\": \"C\", \"text\": \"无法判断\"}, {\"id\": \"D\", \"text\": \"与量词无关\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','在实数集上 $x^{2}+1\\ge 1>0$，方程无实根，故存在量词命题为假。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,35,14,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.702','2026-10-24 17:00:31.702'),(96,'HSMA-RJA-CH01-0071','formal','single','命题“$\\forall x\\in\\mathbb{R},\\,x>0$”的否定是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x\\\\le 0$\"}, {\"id\": \"B\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{R},\\\\,x\\\\le 0$\"}, {\"id\": \"C\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x>0$\"}, {\"id\": \"D\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{R},\\\\,x<0$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','否定全称命题时，把 $\\forall$ 改为 $\\exists$，并把结论 $x>0$ 否定为 $x\\le 0$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,15,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.704','2026-10-24 17:00:31.704'),(97,'HSMA-RJA-CH01-0072','formal','single','命题“$\\exists x\\in\\mathbb{Z},\\,x^{2}=2$”的否定是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{Z},\\\\,x^{2}\\\\ne 2$\"}, {\"id\": \"B\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{Z},\\\\,x^{2}\\\\ne 2$\"}, {\"id\": \"C\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{Z},\\\\,x^{2}=2$\"}, {\"id\": \"D\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x^{2}=2$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','否定存在命题时，把 $\\exists$ 改为 $\\forall$，并否定结论，得到任意整数都满足 $x^{2}\\ne 2$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,15,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.872','2026-10-24 17:00:31.872'),(98,'HSMA-RJA-CH01-0073','formal','single','下列为真命题的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x^{2}-2x+1=0$\"}, {\"id\": \"B\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{R},\\\\,x^{2}-2x+1=0$\"}, {\"id\": \"C\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x^{2}+1=0$\"}, {\"id\": \"D\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{N},\\\\,x<0$（$\\\\mathbb{N}$ 含 $0$）\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$x^{2}-2x+1=(x-1)^{2}=0$ 有实根 $x=1$，存在性为真。其余全称或存在命题均假。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,14,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.876','2026-10-24 17:00:31.876'),(99,'HSMA-RJA-CH01-0074','formal','single','命题“$\\forall x\\in\\{1,2,3\\},\\,x\\le 3$”是','{\"options\": [{\"id\": \"A\", \"text\": \"真命题\"}, {\"id\": \"B\", \"text\": \"假命题\"}, {\"id\": \"C\", \"text\": \"无法判断\"}, {\"id\": \"D\", \"text\": \"否定后仍真\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','论域只有 $1,2,3$，逐个检验均有 $x\\le 3$，故全称命题为真。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.879','2026-10-24 17:00:31.879'),(100,'HSMA-RJA-CH01-0075','formal','multi','下列命题为真的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{R},\\\\,|x|\\\\ge 0$\"}, {\"id\": \"B\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{Z},\\\\,2x=5$\"}, {\"id\": \"C\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x^{2}<0$\"}, {\"id\": \"D\", \"text\": \"$\\\\exists n\\\\in\\\\mathbb{Z}^{+},\\\\,n^{2}=9$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"D\"]}','A 真。B：不存在整数使 $2x=5$。C：平方非负。D：取 $n=3$ 即可。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.883','2026-10-24 17:00:31.883'),(101,'HSMA-RJA-CH01-0076','formal','multi','关于命题否定，正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"“$\\\\forall x\\\\in M,\\\\,p(x)$”的否定是“$\\\\exists x\\\\in M,\\\\,\\\\neg p(x)$”\"}, {\"id\": \"B\", \"text\": \"“$\\\\exists x\\\\in M,\\\\,p(x)$”的否定是“$\\\\forall x\\\\in M,\\\\,\\\\neg p(x)$”\"}, {\"id\": \"C\", \"text\": \"否定时只需否定结论，量词不变\"}, {\"id\": \"D\", \"text\": \"否定全称命题时，全称与存在互换\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','含量词命题的否定规则是：全称与存在互换，并且否定结论。只改结论不改量词是错误的，故 C 不选。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,35,15,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.886','2026-10-24 17:00:31.886'),(102,'HSMA-RJA-CH01-0077','formal','judge','命题“$\\exists x\\in\\mathbb{R},\\,x^{2}=0$”是真命题。',NULL,'{\"kind\": \"judge\", \"value\": true}','取 $x=0$ 时 $x^{2}=0$ 成立，说明存在这样的实数，故命题为真。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,35,14,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.889','2026-10-24 17:00:31.889'),(103,'HSMA-RJA-CH01-0078','formal','judge','命题“$\\forall x\\in\\mathbb{R},\\,x^{2}>0$”是真命题。',NULL,'{\"kind\": \"judge\", \"value\": false}','取反例 $x=0$，此时 $x^{2}=0$ 并不大于 $0$，故全称命题为假。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.892','2026-10-24 17:00:31.892'),(104,'HSMA-RJA-CH01-0079','formal','numeric','在集合 $\\{1,2,3,4\\}$ 中，满足 $x>2$ 的元素个数是（可用于判断存在量词命题）',NULL,'{\"kind\": \"numeric\", \"value\": \"2\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','逐个检验：$3,4$ 满足 $x>2$，共 $2$ 个；因此“存在 $x$ 使 $x>2$”为真。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,35,14,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.894','2026-10-24 17:00:31.894'),(105,'HSMA-RJA-CH01-0080','formal','numeric','命题“$\\forall x\\in\\{2,4,6\\},\\,x$ 为偶数”为真。若从该集合中任取一个元素作为反例候选，可能推翻全称命题的反例个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"0\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$2,4,6$ 均为偶数，找不到使结论失败的元素，故可作反例的个数为 $0$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.897','2026-10-24 17:00:31.897'),(109,'HSMA-RJA-CH03-PARITY-0001','formal','single','设函数 $f$ 的定义域关于原点对称。若对定义域内任意 $x$ 都有 $f(-x)=f(x)$，则称 $f$ 为','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶的函数\"}, {\"id\": \"D\", \"text\": \"非奇非偶函数\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','定义域关于原点对称是讨论奇偶性的前提。对任意 $x$ 有 $f(-x)=f(x)$ 时，$f$ 为偶函数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.453','2026-10-24 20:15:07.568','2026-10-25 12:16:33.000'),(110,'HSMA-RJA-CH03-PARITY-0002','formal','judge','判断：若函数 $f$ 满足对定义域内任意 $x$ 都有 $f(-x)=-f(x)$，则 $f$ 一定是奇函数（无需再检查定义域）。',NULL,'{\"kind\": \"judge\", \"value\": false}','讨论奇偶性必须先检验定义域关于原点对称。仅有代数关系 $f(-x)=-f(x)$ 而定义域不对称时，不能称为奇函数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.580','2026-10-24 20:15:07.575','2026-10-25 12:16:33.000'),(111,'HSMA-RJA-CH03-PARITY-0003','formal','single','下列关于函数奇偶性定义的叙述，正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"只要 $f(-x)=-f(x)$ 成立，$f$ 就是奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数必满足 $f(-x)=-f(x)$\"}, {\"id\": \"C\", \"text\": \"奇函数要求定义域关于原点对称，且 $f(-x)=-f(x)$\"}, {\"id\": \"D\", \"text\": \"奇偶性与定义域是否对称无关\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','奇函数定义：定义域关于原点对称，且对定义域内任意 $x$ 有 $f(-x)=-f(x)$。缺一不可。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.579','2026-10-24 20:15:07.579'),(112,'HSMA-RJA-CH03-PARITY-0004','formal','multi','设函数 $f$ 定义域关于原点对称。下列说法正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"若 $f$ 为偶函数，则 $f(-x)=f(x)$\"}, {\"id\": \"B\", \"text\": \"若 $f$ 为奇函数，则 $f(-x)=-f(x)$\"}, {\"id\": \"C\", \"text\": \"若 $f(0)$ 有定义且 $f$ 为奇函数，则必有 $f(0)=0$\"}, {\"id\": \"D\", \"text\": \"若存在某 $a$ 使 $f(-a)\\\\neq f(a)$ 且 $f(-a)\\\\neq -f(a)$，则 $f$ 非奇非偶\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\", \"D\"]}','在定义域已对称的前提下：偶/奇分别对应 $f(-x)=f(x)$ / $f(-x)=-f(x)$。奇函数若 $0$ 在定义域，则 $f(0)=-f(0)\\Rightarrow f(0)=0$。若既不满足偶又不满足奇的恒等式，则为非奇非偶。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,34,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.583','2026-10-24 20:15:07.583'),(113,'HSMA-RJA-CH03-PARITY-0005','formal','single','已知 $f(x)=x^{3}$ 的定义域为 $\\mathbb{R}$。判断其奇偶性时，下列步骤正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"直接看次数为奇数，故为奇函数，无需验证定义域\"}, {\"id\": \"B\", \"text\": \"先确认定义域关于原点对称，再验证 $f(-x)=-f(x)$\"}, {\"id\": \"C\", \"text\": \"只需验证 $f(-1)=-f(1)$ 即可断定为奇函数\"}, {\"id\": \"D\", \"text\": \"因为过原点，所以一定是偶函数\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','正确流程：先确认定义域对称（此处 $\\mathbb{R}$ 对称），再验证对任意 $x$，$f(-x)=(-x)^{3}=-x^{3}=-f(x)$，故为奇函数。仅验证个别点或只看次数不够严谨。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,35,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.699','2026-10-24 20:15:07.588','2026-10-25 12:16:33.000'),(114,'HSMA-RJA-CH03-PARITY-0006','formal','single','函数 $f(x)=\\sqrt{x-1}+\\sqrt{1-x}$ 的定义域','{\"options\": [{\"id\": \"A\", \"text\": \"关于原点对称，可讨论奇偶性\"}, {\"id\": \"B\", \"text\": \"为 $\\\\{1\\\\}$，关于原点不对称，故非奇非偶\"}, {\"id\": \"C\", \"text\": \"为 $[0,+\\\\infty)$，可讨论奇偶性\"}, {\"id\": \"D\", \"text\": \"为空集，规定为偶函数\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','由 $x-1\\ge 0$ 且 $1-x\\ge 0$ 得 $x=1$，定义域 $\\{1\\}$。关于原点的对称点 $-1\\notin\\{1\\}$，定义域不对称，故非奇非偶。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.820','2026-10-24 20:15:07.594','2026-10-25 12:16:33.000'),(115,'HSMA-RJA-CH03-PARITY-0007','formal','judge','判断：函数 $f(x)=\\dfrac{1}{x}$ 的定义域为 $(-\\infty,0)\\cup(0,+\\infty)$，关于原点对称，因此可以进一步用定义讨论其奇偶性。',NULL,'{\"kind\": \"judge\", \"value\": true}','定义域 $\\mathbb{R}\\setminus\\{0\\}$ 关于原点对称，具备讨论奇偶性的前提；再验证 $f(-x)=-1/x=-f(x)$ 可知其为奇函数。本题只考前提是否成立。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.920','2026-10-24 20:15:07.598','2026-10-25 12:16:33.000'),(116,'HSMA-RJA-CH03-PARITY-0008','formal','single','函数 $f(x)=\\sqrt{x^{2}-1}$ 的定义域为','{\"options\": [{\"id\": \"A\", \"text\": \"$[-1,1]$，关于原点对称\"}, {\"id\": \"B\", \"text\": \"$(-\\\\infty,-1]\\\\cup[1,+\\\\infty)$，关于原点对称\"}, {\"id\": \"C\", \"text\": \"$(1,+\\\\infty)$，关于原点不对称\"}, {\"id\": \"D\", \"text\": \"$[0,+\\\\infty)$，关于原点对称\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','由 $x^{2}-1\\ge 0$ 得 $x\\le -1$ 或 $x\\ge 1$，即 $(-\\infty,-1]\\cup[1,+\\infty)$。若 $x$ 属于该集合，则 $-x$ 也属于，故关于原点对称，可继续讨论奇偶性。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,35,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.601','2026-10-24 20:15:07.601'),(117,'HSMA-RJA-CH03-PARITY-0009','formal','multi','下列函数中，定义域关于原点对称的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$f(x)=\\\\sqrt{4-x^{2}}$\"}, {\"id\": \"B\", \"text\": \"$g(x)=\\\\ln(x+2)$\"}, {\"id\": \"C\", \"text\": \"$h(x)=\\\\dfrac{1}{x^{2}-1}$\"}, {\"id\": \"D\", \"text\": \"$p(x)=\\\\sqrt{x}+\\\\sqrt{-x}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','A：定义域 $[-2,2]$，对称。B：$x>-2$，不对称。C：$x\\neq\\pm 1$，仍关于原点对称。D：仅 $x=0$，对称。故选 A、C、D。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,35,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.605','2026-10-24 20:15:07.605'),(118,'HSMA-RJA-CH03-PARITY-0010','formal','single','函数 $f(x)=x^{2}+1$（定义域 $\\mathbb{R}$）是','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶\"}, {\"id\": \"D\", \"text\": \"非奇非偶\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','定义域 $\\mathbb{R}$ 对称。$f(-x)=(-x)^{2}+1=x^{2}+1=f(x)$，故为偶函数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,35,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.048','2026-10-24 20:15:07.609','2026-10-25 12:16:34.000'),(119,'HSMA-RJA-CH03-PARITY-0011','formal','single','函数 $f(x)=x^{3}-x$（定义域 $\\mathbb{R}$）是','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶\"}, {\"id\": \"D\", \"text\": \"非奇非偶\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','定义域对称。$f(-x)=(-x)^{3}-(-x)=-x^{3}+x=-(x^{3}-x)=-f(x)$，故为奇函数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,35,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.270','2026-10-24 20:15:07.613','2026-10-25 12:16:34.000'),(120,'HSMA-RJA-CH03-PARITY-0012','formal','multi','设 $f(x)=0$（定义域 $\\mathbb{R}$）。下列说法正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$f$ 是奇函数\"}, {\"id\": \"B\", \"text\": \"$f$ 是偶函数\"}, {\"id\": \"C\", \"text\": \"$f$ 既是奇函数又是偶函数\"}, {\"id\": \"D\", \"text\": \"$f$ 非奇非偶\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','零函数在关于原点对称的定义域上：$f(-x)=0=f(x)$ 且 $f(-x)=0=-f(x)$，故既奇又偶。A、B、C 均正确，D 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,36,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.549','2026-10-24 20:15:07.617','2026-10-25 12:16:34.000'),(121,'HSMA-RJA-CH03-PARITY-0013','formal','single','函数 $f(x)=x+|x|$（定义域 $\\mathbb{R}$）的奇偶性是','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶\"}, {\"id\": \"D\", \"text\": \"非奇非偶\"}]}','{\"kind\": \"single\", \"optionId\": \"D\"}','定义域对称。$f(-x)=-x+|-x|=-x+|x|$。一般地 $f(-x)\\neq f(x)$（如 $x=1$：$f(1)=2$，$f(-1)=0$），且 $f(-x)\\neq -f(x)$（$-f(1)=-2\\neq 0$），故非奇非偶。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,36,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.622','2026-10-24 20:15:07.622'),(122,'HSMA-RJA-CH03-PARITY-0014','formal','judge','判断：函数 $f(x)=x^{2}+x$（定义域 $\\mathbb{R}$）是偶函数。',NULL,'{\"kind\": \"judge\", \"value\": false}','$f(-x)=x^{2}-x$。取 $x=1$，$f(-1)=0\\neq f(1)=2$，故不是偶函数；也不是奇函数（$f(-1)=0\\neq -2$），为非奇非偶。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,36,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.626','2026-10-24 20:15:07.626'),(123,'HSMA-RJA-CH03-PARITY-0015','formal','numeric','已知奇函数 $f$ 的定义域关于原点对称，且 $f(3)=5$。求 $f(-3)$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"-5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','奇函数满足 $f(-x)=-f(x)$，故 $f(-3)=-f(3)=-5$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,37,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.709','2026-10-24 20:15:07.631','2026-10-25 12:16:34.000'),(124,'HSMA-RJA-CH03-PARITY-0016','formal','numeric','已知偶函数 $f$ 的定义域关于原点对称，且 $f(-2)=7$。求 $f(2)$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"7\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','偶函数满足 $f(-x)=f(x)$，故 $f(2)=f(-2)=7$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,37,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.635','2026-10-24 20:15:07.635'),(125,'HSMA-RJA-CH03-PARITY-0017','formal','numeric','已知奇函数 $f$ 定义在 $\\mathbb{R}$ 上，$f(1)=2$，$f(2)=5$。求 $f(-1)+f(-2)$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"-7\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$f(-1)=-f(1)=-2$，$f(-2)=-f(2)=-5$，故和为 $-7$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,37,'draft',1,'v1',2,2,2,NULL,NULL,'2026-10-24 20:15:07.638','2026-10-24 22:00:56.000'),(126,'HSMA-RJA-CH03-PARITY-0018','formal','numeric','已知偶函数 $f$ 定义在 $\\mathbb{R}$ 上，$f(4)=3$，且 $f(x)=ax^{2}+b$（$a,b$ 为常数）。若还已知 $f(0)=1$，求 $f(-4)$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"3\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','偶函数有 $f(-4)=f(4)=3$。由 $f(0)=1$ 可知常数项，但不影响 $f(\\pm 4)$ 的相等关系；本题所求仅为 $f(-4)$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,37,'draft',1,'v1',2,2,2,NULL,NULL,'2026-10-24 20:15:07.641','2026-10-24 22:00:56.000'),(127,'HSMA-RJA-CH03-PARITY-0019','formal','single','若函数 $y=f(x)$ 是偶函数，则其图象','{\"options\": [{\"id\": \"A\", \"text\": \"关于原点对称\"}, {\"id\": \"B\", \"text\": \"关于 $y$ 轴对称\"}, {\"id\": \"C\", \"text\": \"关于 $x$ 轴对称\"}, {\"id\": \"D\", \"text\": \"关于直线 $y=x$ 对称\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','由偶函数定义，$f(-x)=f(x)$，图象上点 $(x,y)$ 与 $(-x,y)$ 同时出现，故图象关于 $y$ 轴对称。奇函数则关于原点对称，二者不可混淆。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,36,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.809','2026-10-24 20:15:07.645','2026-10-25 12:16:34.000'),(128,'HSMA-RJA-CH03-PARITY-0020','formal','single','已知点 $(2,5)$ 在奇函数 $y=f(x)$ 的图象上，则下列点也在该图象上的是','{\"options\": [{\"id\": \"A\", \"text\": \"$(-2,5)$\"}, {\"id\": \"B\", \"text\": \"$(-2,-5)$\"}, {\"id\": \"C\", \"text\": \"$(2,-5)$\"}, {\"id\": \"D\", \"text\": \"$(5,2)$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','奇函数图象关于原点对称：点 $(a,b)$ 在图象上则 $(-a,-b)$ 也在图象上。故 $(2,5)$ 对应 $(-2,-5)$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,36,'approved',1,'v1',3,2,2,2,'2026-10-25 12:16:34.900','2026-10-24 20:15:07.648','2026-10-25 12:16:34.000'),(129,'HSMA-RJA-CH03-PARITY-0021','formal','multi','已知偶函数 $y=f(x)$ 的图象过点 $(3,-1)$。下列说法正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"图象也过点 $(-3,-1)$\"}, {\"id\": \"B\", \"text\": \"图象也过点 $(-3,1)$\"}, {\"id\": \"C\", \"text\": \"图象关于 $y$ 轴对称\"}, {\"id\": \"D\", \"text\": \"必有 $f(-3)=f(3)$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','偶函数关于 $y$ 轴对称，故过 $(3,-1)$ 必过 $(-3,-1)$，且 $f(-3)=f(3)=-1$。B 的纵坐标符号错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,37,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.651','2026-10-24 20:15:07.651'),(130,'HSMA-RJA-CH03-PARITY-0022','formal','single','设 $f$ 是定义在 $\\mathbb{R}$ 上的奇函数，且 $f$ 在 $[0,+\\infty)$ 上单调递增。则 $f$ 在 $(-\\infty,0]$ 上','{\"options\": [{\"id\": \"A\", \"text\": \"单调递增\"}, {\"id\": \"B\", \"text\": \"单调递减\"}, {\"id\": \"C\", \"text\": \"先增后减\"}, {\"id\": \"D\", \"text\": \"无法判断\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','取 $x_{1}<x_{2}\\le 0$，则 $0\\le -x_{2}<-x_{1}$。由正半轴递增得 $f(-x_{2})<f(-x_{1})$。又奇函数 $f(-x)=-f(x)$，故 $-f(x_{2})<-f(x_{1})$，即 $f(x_{1})<f(x_{2})$，从而在 $(-\\infty,0]$ 上也单调递增。必须明确所论区间与奇偶性。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,18,42,37,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.654','2026-10-24 20:15:07.654'),(131,'HSMA-RJA-CH03-PARITY-0023','formal','multi','设 $f$ 是定义在 $\\mathbb{R}$ 上的偶函数，且 $f$ 在 $[0,+\\infty)$ 上单调递减。下列正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$f$ 在 $(-\\\\infty,0]$ 上单调递增\"}, {\"id\": \"B\", \"text\": \"$f$ 在 $(-\\\\infty,0]$ 上单调递减\"}, {\"id\": \"C\", \"text\": \"对任意 $x$，有 $f(|x|)=f(x)$\"}, {\"id\": \"D\", \"text\": \"仅由偶函数不能推出其在正半轴单调\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','偶函数关于 $y$ 轴对称：正半轴递减对应负半轴递增（可类似用对称点证明）。$f(|x|)=f(x)$ 对偶函数成立。偶函数本身不蕴含单调性，D 正确。B 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,18,42,37,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.659','2026-10-24 20:15:07.659'),(132,'HSMA-RJA-CH03-PARITY-0024','formal','judge','判断：任意奇函数在其整个定义域上都一定是单调函数。',NULL,'{\"kind\": \"judge\", \"value\": false}','反例：$f(x)=x^{3}-x$ 是奇函数，但在 $\\mathbb{R}$ 上不单调（局部有增减）。奇偶性与单调性相互独立，综合题必须另行给出单调区间条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,35,'draft',1,'v1',2,2,2,NULL,NULL,'2026-10-24 20:15:07.662','2026-10-24 22:00:57.000'),(133,'HSMA-RJA-CH03-PARITY-0025','formal','single','设 $f$ 是定义在 $[-2,2]$ 上的偶函数，且当 $x\\in[0,2]$ 时 $f(x)=x+1$。则 $f(-1)$ 等于','{\"options\": [{\"id\": \"A\", \"text\": \"$0$\"}, {\"id\": \"B\", \"text\": \"$1$\"}, {\"id\": \"C\", \"text\": \"$2$\"}, {\"id\": \"D\", \"text\": \"$-1$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','偶函数有 $f(-1)=f(1)$。又 $1\\in[0,2]$，故 $f(1)=1+1=2$，从而 $f(-1)=2$。定义域 $[-2,2]$ 关于原点对称，条件充分。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,35,'approved',1,'v1',3,2,2,2,'2026-10-25 12:16:34.999','2026-10-24 20:15:07.666','2026-10-25 12:16:35.000'),(151,'HSMA-RJA-CH03-APP-0001','formal','application','某社区游泳馆暑假期间调整日票价格。\n调查表明：当票价定为 $x$ 元（$x$ 为正整数，且 $30\\le x\\le 60$）时，预计日接待人数为 $2400-30x$ 人。\n设该馆日票务收入为 $y$ 元。\n\n（1）写出 $y$ 关于 $x$ 的函数解析式，并写出定义域；\n（2）求使日票务收入最大的票价，以及相应的最大日票务收入。\n\n（要求写出必要的建模与求解过程。）',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"model\", \"title\": \"建立收入函数模型\", \"criteria\": \"写出 y=x(2400-30x) 或 2400x-30x²。仅列式缺说明可扣 1；模型结构错误本项 0～1。\", \"maxScore\": 3}, {\"key\": \"domain\", \"title\": \"定义域与实际约束\", \"criteria\": \"给出 30≤x≤60 的整数定义域（或等价表述）。仅写区间未提整数可给 1。\", \"maxScore\": 2}, {\"key\": \"solve\", \"title\": \"最值推导过程\", \"criteria\": \"用配方/顶点/单调性正确求得 x=40。方法对计算错可给 1～2；无过程猜答案 0～1。\", \"maxScore\": 3}, {\"key\": \"conclusion\", \"title\": \"实际结论与单位\", \"criteria\": \"明确票价 40 元、最大收入 48000 元。缺单位或结论孤立给 1；答案错 0。\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"（1）$y=x(2400-30x)=2400x-30x^{2}$，定义域 $x\\\\in\\\\{30,31,\\\\ldots,60\\\\}$。\\n（2）当 $x=40$ 元时日票务收入最大，最大日收入为 $48000$ 元。\"}','收入等于票价乘以人数：\n$y=x(2400-30x)$。\n整理得 $y=2400x-30x^{2}$。\n因为票价为正整数且 $30\\le x\\le 60$，所以定义域为 $\\{30,31,\\ldots,60\\}$。\n配方：$y=-30(x-40)^{2}+48000$。\n因为 $-30(x-40)^{2}\\le 0$，且 $x=40$ 属于定义域，所以 $x=40$ 时收入最大。\n最大收入为 $48000$ 元。','original',NULL,NULL,NULL,'原创设计建议：人教A版必修第三章「函数的应用（一）」情境下的票价—人数—收入建模题；尚未人工核实是否与公开题雷同。',NULL,'unverified','unknown',2,18,44,31,'approved',1,'v1',3,2,2,2,'2026-10-25 14:01:36.684','2026-10-25 13:49:09.540','2026-10-25 14:01:36.000'),(152,'CAND-G1B-001','formal','judge','判断：$A=\\{x\\in\\mathbb{Z}\\mid -2<x<3\\}$ 时，$0\\in A$ 且 $3\\notin A$。',NULL,'{\"kind\": \"judge\", \"value\": true}','条件：$A=\\{x\\in\\mathbb{Z}\\mid -2<x<3\\}$。整数满足 $-2<x<3$ 的有 $-1,0,1,2$，故 $A=\\{-1,0,1,2\\}$。由此 $0\\in A$，而 $3$ 不满足 $x<3$，故 $3\\notin A$。判断正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,16,31,1,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.013','2026-10-26 16:43:22.779','2026-10-26 17:17:16.000'),(153,'CAND-G1B-002','formal','single','集合 $\\{a,b,c\\}$ 的真子集个数为','{\"options\": [{\"id\": \"A\", \"text\": \"$6$\"}, {\"id\": \"B\", \"text\": \"$7$\"}, {\"id\": \"C\", \"text\": \"$8$\"}, {\"id\": \"D\", \"text\": \"$9$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','三元集合有 $2^3=8$ 个子集（含空集与自身）。真子集不含集合本身，故个数为 $8-1=7$。选 B。可列举：空集、$\\{a\\}$、$\\{b\\}$、$\\{c\\}$、$\\{a,b\\}$、$\\{a,c\\}$、$\\{b,c\\}$ 共 7 个验证。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,16,32,4,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.104','2026-10-26 16:43:22.858','2026-10-26 17:17:16.000'),(154,'CAND-G1B-003','formal','numeric','$A=\\{1,2,4,6\\}$，$B=\\{2,3,5\\}$，则 $|A\\cup B|=$',NULL,'{\"kind\": \"numeric\", \"value\": \"6\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','并集取两集合全部元素：$A\\cup B=\\{1,2,3,4,5,6\\}$（重复元素 $2$ 只计一次），故 $|A\\cup B|=6$。也可用容斥公式复核：$|A|+|B|-|A\\cap B|=4+3-1=6$，其中 $A\\cap B=\\{2\\}$。边界核对：并集不含新元素，也不应漏掉 $1,3,4,5,6$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,16,33,6,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.205','2026-10-26 16:43:22.862','2026-10-26 17:17:16.000'),(155,'CAND-G1B-004','formal','single','“$x^2=9$”是“$x=3$”的','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要\"}, {\"id\": \"B\", \"text\": \"必要不充分\"}, {\"id\": \"C\", \"text\": \"充要\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','充分性：由 $x^2=9$ 得 $x=\\pm3$，其中 $x=-3$ 也满足前件但不满足“$x=3$”，故“$x^2=9$”推不出必有“$x=3$”，不充分。必要性：若 $x=3$，则显然 $x^2=9$，故必要。综上为必要不充分条件，选 B。可用反例 $x=-3$ 作边界检验。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,16,34,12,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.286','2026-10-26 16:43:22.868','2026-10-26 17:17:16.000'),(156,'CAND-G1B-005','formal','multi','命题否定写法正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"“$\\\\forall x,\\\\,x^2+1>0$”否定为“$\\\\exists x,\\\\,x^2+1\\\\le0$”\"}, {\"id\": \"B\", \"text\": \"“$\\\\exists x\\\\in\\\\mathbb{Z},\\\\,x^2=10$”否定为“$\\\\forall x\\\\in\\\\mathbb{Z},\\\\,x^2\\\\ne10$”\"}, {\"id\": \"C\", \"text\": \"“$\\\\forall x,\\\\,x>0$”否定为“$\\\\exists x,\\\\,x\\\\le0$”\"}, {\"id\": \"D\", \"text\": \"“$\\\\exists x,\\\\,x^2<0$”否定为“$\\\\forall x,\\\\,x^2>0$”\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','量词否定规则：$\\forall$ 与 $\\exists$ 互换，并把结论取否定。A、B、C 均符合。D 中“$\\exists x,\\,x^2<0$”的否定应为“$\\forall x,\\,x^2\\ge0$”，原选项写成 $x^2>0$，漏掉等号，故 D 错。正确为 A、B、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,16,35,15,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.421','2026-10-26 16:43:22.914','2026-10-26 17:17:16.000'),(157,'CAND-G1B-006','formal','judge','若 $a>b$，$c<0$，则 $ac<bc$。',NULL,'{\"kind\": \"judge\", \"value\": true}','不等式两边同乘负数 $c<0$ 时不等号必须变向：由 $a>b$ 得 $ac<bc$。例如取 $a=3,b=1,c=-2$，则 $ac=-6$、$bc=-2$，确实 $-6<-2$。故命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,17,38,43,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.596','2026-10-26 16:43:22.921','2026-10-26 17:17:16.000'),(158,'CAND-G1B-007','formal','single','$M=x^2+1$，$N=2x$，则对 $\\forall x\\in\\mathbb{R}$ 有','{\"options\": [{\"id\": \"A\", \"text\": \"$M>N$\"}, {\"id\": \"B\", \"text\": \"$M\\\\ge N$\"}, {\"id\": \"C\", \"text\": \"$M<N$\"}, {\"id\": \"D\", \"text\": \"不确定\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','作差比较：$M-N=x^2+1-2x=(x-1)^2$。完全平方对一切实数非负，且仅当 $x=1$ 时取 $0$。因此恒有 $M\\ge N$，不能写成严格大于，选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,17,38,44,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.762','2026-10-26 16:43:22.925','2026-10-26 17:17:16.000'),(159,'CAND-G1B-008','formal','numeric','$x>0$ 且 $x+\\dfrac{16}{x}=8$，则 $x=$',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','由 $x>0$ 及 $x+\\dfrac{16}{x}=8$，两边乘 $x$ 得 $x^2-8x+16=0$，即 $(x-4)^2=0$，故 $x=4$。亦可用基本不等式：等号当且仅当 $x=\\dfrac{16}{x}$，即 $x=4$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,17,39,47,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.845','2026-10-26 16:43:22.929','2026-10-26 17:17:16.000'),(160,'CAND-G1B-009','formal','single','$x>2$ 时 $x+\\dfrac{4}{x-2}$ 的最小值为','{\"options\": [{\"id\": \"A\", \"text\": \"$4$\"}, {\"id\": \"B\", \"text\": \"$5$\"}, {\"id\": \"C\", \"text\": \"$6$\"}, {\"id\": \"D\", \"text\": \"$8$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','令 $t=x-2>0$，则原式 $=t+2+\\dfrac{4}{t}$。由基本不等式 $t+\\dfrac{4}{t}\\ge2\\sqrt{t\\cdot\\dfrac{4}{t}}=4$，等号当 $t=2$。故最小值为 $4+2=6$（$x=4$）。选 C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,17,39,48,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:16.945','2026-10-26 16:43:22.933','2026-10-26 17:17:16.000'),(161,'CAND-G1B-010','formal','single','$x^2-5x+6<0$ 的解集为','{\"options\": [{\"id\": \"A\", \"text\": \"$(-\\\\infty,2)\\\\cup(3,+\\\\infty)$\"}, {\"id\": \"B\", \"text\": \"$(2,3)$\"}, {\"id\": \"C\", \"text\": \"$[2,3]$\"}, {\"id\": \"D\", \"text\": \"$(-\\\\infty,2]\\\\cup[3,+\\\\infty)$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','先因式分解：$x^2-5x+6=(x-2)(x-3)$。二次项系数为正，抛物线开口向上，函数值仅在两根之间为负，因此不等式 $<0$ 的解集为开区间 $(2,3)$。端点 $x=2$ 或 $3$ 使式子等于 $0$，不满足严格小于，故不取闭区间。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,17,40,51,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.029','2026-10-26 16:43:22.940','2026-10-26 17:17:17.000'),(162,'CAND-G1B-011','formal','multi','使 $x^2+px+9>0$ 对 $\\forall x\\in\\mathbb{R}$ 恒成立的 $p$ 可以是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$0$\"}, {\"id\": \"B\", \"text\": \"$5$\"}, {\"id\": \"C\", \"text\": \"$-5$\"}, {\"id\": \"D\", \"text\": \"$6$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','开口向上，要 $x^2+px+9>0$ 对一切 $x$ 成立，需判别式 $\\Delta=p^2-36<0$，即 $|p|<6$。故 $p=0,\\pm5$ 可，$p=6$ 时 $\\Delta=0$ 有重根使式子可取 $0$，不满足严格大于。选 A、B、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,17,40,52,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.154','2026-10-26 16:43:22.944','2026-10-26 17:17:17.000'),(163,'CAND-G1B-012','formal','application','固定成本 $150$ 元，可变成本 $6$ 元/件，售价 $18$ 元/件，销量 $x\\in\\mathbb{N}^+$。\n（1）利润 $L(x)$；\n（2）至少几件不亏本？',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"L\", \"title\": \"利润函数\", \"criteria\": \"$12x-150$\", \"maxScore\": 4}, {\"key\": \"s\", \"title\": \"解不等式\", \"criteria\": \"$x\\\\ge13$\", \"maxScore\": 4}, {\"key\": \"w\", \"title\": \"结论\", \"criteria\": \"至少13件\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"（1）$L(x)=12x-150$；（2）$x\\\\ge13$。\"}','利润＝售价收入－成本：$L(x)=18x-(150+6x)=12x-150$。不亏本即 $L(x)\\ge0\\Rightarrow x\\ge12.5$。销量为正整数，故至少 $13$ 件。代入 $x=12$ 得 $L=-6<0$，$x=13$ 得 $L=6>0$，可验证。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,17,38,45,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.228','2026-10-26 16:43:22.948','2026-10-26 17:17:17.000'),(164,'CAND-G1B-013','formal','single','$x^2+ax+1\\ge0$ 恒成立，则 $a\\in$','{\"options\": [{\"id\": \"A\", \"text\": \"$[-2,2]$\"}, {\"id\": \"B\", \"text\": \"$(-2,2)$\"}, {\"id\": \"C\", \"text\": \"$[-1,1]$\"}, {\"id\": \"D\", \"text\": \"$a\\\\ge2$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','开口向上，$x^2+ax+1\\ge0$ 恒成立 $\\Leftrightarrow\\Delta=a^2-4\\le0\\Leftrightarrow a\\in[-2,2]$。选 A。边界 $a=\\pm2$ 时有重根、最小值恰为 $0$，仍满足 $\\ge0$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,17,40,53,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.320','2026-10-26 16:43:22.956','2026-10-26 17:17:17.000'),(165,'CAND-G1B-014','formal','numeric','$x,y>0$，$xy=25$，则 $x+y$ 最小值为',NULL,'{\"kind\": \"numeric\", \"value\": \"10\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','条件 $x,y>0$ 且 $xy=25$ 固定。由基本不等式 $x+y\\ge2\\sqrt{xy}=2\\sqrt{25}=10$，等号成立当且仅当 $x=y$。此时 $x=y=5$，故最小值为 $10$。也可用 $y=25/x$ 化为 $f(x)=x+25/x$（$x>0$），求导 $f\'(x)=1-25/x^2=0\\Rightarrow x=5$，二阶或端点趋势可确认最小值。代入 $x=5,y=5$ 得 $10$ 复核。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,17,39,49,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.421','2026-10-26 16:43:22.999','2026-10-26 17:17:17.000'),(166,'CAND-G1B-015','formal','judge','$f(x)=-2(x-1)^2+5$ 在 $[0,3]$ 上最大值为 $5$。',NULL,'{\"kind\": \"judge\", \"value\": true}','顶点式 $f(x)=-2(x-1)^2+5$ 开口向下，顶点为 $(1,5)$。闭区间 $[0,3]$ 包含顶点横坐标 $x=1$，因此区间上最大值即为顶点纵坐标 $5$。端点对照：$f(0)=-2(0-1)^2+5=3$，$f(3)=-2(3-1)^2+5=-3$，均小于 $5$。故命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,17,40,54,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.528','2026-10-26 16:43:23.006','2026-10-26 17:17:17.000'),(167,'CAND-G1B-016','formal','single','$f(x)=\\dfrac{\\sqrt{x-1}}{x-3}$ 的定义域为','{\"options\": [{\"id\": \"A\", \"text\": \"$[1,3)\\\\cup(3,+\\\\infty)$\"}, {\"id\": \"B\", \"text\": \"$[1,+\\\\infty)$\"}, {\"id\": \"C\", \"text\": \"$(1,3)\\\\cup(3,+\\\\infty)$\"}, {\"id\": \"D\", \"text\": \"$[1,3)$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','分子根式要求 $x-1\\ge0\\Rightarrow x\\ge1$；分母不为零要求 $x\\ne3$。两条件联立得定义域 $[1,3)\\cup(3,+\\infty)$。注意 $x=1$ 可使根式为 $0$，属于定义域。选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,41,17,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.637','2026-10-26 16:43:23.011','2026-10-26 17:17:17.000'),(168,'CAND-G1B-017','formal','judge','$f(x)=x$ 与 $g(t)=t$ 是同一函数。',NULL,'{\"kind\": \"judge\", \"value\": true}','函数是否相同取决于定义域与对应法则，与用 $x$ 还是 $t$ 作自变量字母无关。二者定义域均为 $\\mathbb{R}$，对应关系均为恒等映射，故为同一函数。命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,41,20,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.745','2026-10-26 16:43:23.015','2026-10-26 17:17:17.000'),(169,'CAND-G1B-018','formal','application','出租车：$3\\text{km}$ 内 $10$ 元；超出每 km $2.5$ 元（$x$ 为整数 km）。\n（1）车费 $F(x)$；\n（2）$8\\text{km}$ 费用？',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"p\", \"title\": \"分段表达式\", \"criteria\": \"两段正确\", \"maxScore\": 5}, {\"key\": \"c\", \"title\": \"计算\", \"criteria\": \"22.5\", \"maxScore\": 3}, {\"key\": \"u\", \"title\": \"单位\", \"criteria\": \"元\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"（1）$F(x)=\\\\begin{cases}10,&0<x\\\\le3\\\\\\\\10+2.5(x-3),&x>3\\\\end{cases}$；（2）$22.5$ 元。\"}','按里程分段建模：当 $0<x\\le3$ 时只收起步价，故 $F(x)=10$；当 $x>3$ 时超出里程为 $x-3$，按每公里 $2.5$ 元加收，故 $F(x)=10+2.5(x-3)$。求 $x=8$：超出 $5$ km，得 $F(8)=10+2.5\\times5=22.5$ 元。边界核验：在 $x=3$ 处两段都得 $10$，分段连续；若误把全程按 $2.5x$ 计会偏大。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,41,24,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:17.912','2026-10-26 16:43:23.020','2026-10-26 17:17:17.000'),(170,'CAND-G1B-019','formal','single','$f(x+1)=x^2-2x$，则 $f(3)=$','{\"options\": [{\"id\": \"A\", \"text\": \"$0$\"}, {\"id\": \"B\", \"text\": \"$1$\"}, {\"id\": \"C\", \"text\": \"$2$\"}, {\"id\": \"D\", \"text\": \"$3$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','已知复合表达式 $f(x+1)=x^2-2x$，要求 $f(3)$。令自变量满足 $x+1=3$，即 $x=2$，代入右端得 $f(3)=2^2-2\\cdot2=4-4=0$，选 A。换元法：令 $u=x+1$，则 $x=u-1$，$f(u)=(u-1)^2-2(u-1)=u^2-4u+3$，再代入 $u=3$ 得 $9-12+3=0$，两种途径一致。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,41,25,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:18.061','2026-10-26 16:43:23.025','2026-10-26 17:17:18.000'),(171,'CAND-G1B-020','formal','single','$f(x)=3x-7$ 在 $\\mathbb{R}$ 上','{\"options\": [{\"id\": \"A\", \"text\": \"单调递增\"}, {\"id\": \"B\", \"text\": \"单调递减\"}, {\"id\": \"C\", \"text\": \"先增后减\"}, {\"id\": \"D\", \"text\": \"无单调性\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','一次函数 $f(x)=kx+b$ 的单调性完全由斜率 $k$ 决定。本题 $f(x)=3x-7$，一次项系数 $k=3>0$，图象从左到右上升，因此在整个实数集上单调递增。也可用定义：任意 $x_1<x_2$ 时 $f(x_1)-f(x_2)=3(x_1-x_2)<0$，即 $f(x_1)<f(x_2)$。选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,42,26,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:18.189','2026-10-26 16:43:23.029','2026-10-26 17:17:18.000'),(172,'CAND-G1B-021','formal','judge','$f(x)=x^2$ 在 $(-\\infty,0)$ 上单调递减。',NULL,'{\"kind\": \"judge\", \"value\": true}','抛物线 $y=x^2$ 对称轴为 $y$ 轴，在对称轴左侧（$-\\infty,0)$ 上：若 $x_1<x_2<0$，则 $|x_1|>|x_2|$，从而 $x_1^2>x_2^2$，即 $f(x_1)>f(x_2)$，故单调递减。命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,42,29,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:18.289','2026-10-26 16:43:23.034','2026-10-26 17:17:18.000'),(173,'CAND-G1B-022','formal','application','矩形周长 $20$，一边长 $x$，面积 $S(x)=x(10-x)$，$0<x<10$。\n（1）求 $S(x)$ 最大值及对应 $x$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"proc\", \"title\": \"求最值过程\", \"criteria\": \"开口向下且对称轴 $x=5$，或配方 $S=25-(x-5)^2$，或等价均值/导数途径得到最值点 $x=5$（禁止仅抄题干 $S(x)=x(10-x)$）\", \"maxScore\": 3}, {\"key\": \"m\", \"title\": \"最大值结果\", \"criteria\": \"$x=5$ 且 $S_{\\\\max}=25$\", \"maxScore\": 5}], \"maxScore\": 8, \"standardAnswer\": \"$x=5$ 时 $S_{\\\\max}=25$。\"}','周长 $20$ 时半周长为 $10$，故邻边为 $10-x$，面积 $S(x)=x(10-x)=10x-x^2$。这是开口向下的二次函数，对称轴 $x=5$ 落在定义域 $(0,10)$ 内，最大值为 $S(5)=25$。几何上此时矩形为正方形。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,42,33,'approved',1,'v1',2,2,2,2,'2026-10-26 21:49:35.419','2026-10-26 16:43:23.040','2026-10-26 21:49:35.000'),(174,'CAND-G1B-023','formal','single','奇函数 $f$，$f(2)=5$，则 $f(-2)=$','{\"options\": [{\"id\": \"A\", \"text\": \"$5$\"}, {\"id\": \"B\", \"text\": \"$-5$\"}, {\"id\": \"C\", \"text\": \"$0$\"}, {\"id\": \"D\", \"text\": \"不确定\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','奇函数定义：$f(-x)=-f(x)$（定义域关于原点对称）。把 $x=2$ 代入得 $f(-2)=-f(2)$。已知 $f(2)=5$，因此 $f(-2)=-5$，选 B。对照：若是偶函数则有 $f(-2)=f(2)=5$。本题未给出其它点的信息，不能选“不确定”；奇偶性已唯一确定对称点的函数值。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,18,42,37,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:18.511','2026-10-26 16:43:23.045','2026-10-26 17:17:18.000'),(175,'CAND-G1B-024','formal','single','$f$ 在 $\\mathbb{R}$ 递增，$f(a)<f(b)$ 等价于','{\"options\": [{\"id\": \"A\", \"text\": \"$a<b$\"}, {\"id\": \"B\", \"text\": \"$a>b$\"}, {\"id\": \"C\", \"text\": \"$a=b$\"}, {\"id\": \"D\", \"text\": \"不确定\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','函数在 $\\mathbb{R}$ 上严格递增意味着：对任意实数，$x_1<x_2\\Leftrightarrow f(x_1)<f(x_2)$（同向保持）。因此 $f(a)<f(b)$ 等价于 $a<b$，选 A。若改为严格递减，则应变成 $a>b$。这是用单调性解不等式、比较大小的常用依据；等号情形对应 $a=b$，本题是严格不等式故不选 C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,18,42,30,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:18.607','2026-10-26 16:43:23.050','2026-10-26 17:17:18.000'),(176,'CAND-G1B-025','formal','multi','第一象限递增的幂函数有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$y=x^2$\"}, {\"id\": \"B\", \"text\": \"$y=x^{1/2}$\"}, {\"id\": \"C\", \"text\": \"$y=x^{-1}$\"}, {\"id\": \"D\", \"text\": \"$y=x^3$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','在第一象限 $(0,+\\infty)$ 上，幂函数 $y=x^{\\alpha}$ 的单调性由指数 $\\alpha$ 决定：$\\alpha>0$ 时递增，$\\alpha<0$ 时递减。于是 $x^2$（$\\alpha=2$）、$x^{1/2}$（$\\alpha=1/2$）、$x^3$（$\\alpha=3$）均递增；而 $x^{-1}$（$\\alpha=-1$）递减。故选 A、B、D，不选 C。可取 $0<x_1<x_2$ 比较函数值作直观检验。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,43,39,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:18.715','2026-10-26 16:43:23.056','2026-10-26 17:17:18.000'),(177,'CAND-G1B-026','formal','single','$y=x^{1/3}$ 在 $\\mathbb{R}$ 上','{\"options\": [{\"id\": \"A\", \"text\": \"递增\"}, {\"id\": \"B\", \"text\": \"递减\"}, {\"id\": \"C\", \"text\": \"先增后减\"}, {\"id\": \"D\", \"text\": \"无单调性\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','函数 $y=x^{1/3}$ 即立方根函数。设 $x_1<x_2$，两边同时立方（严格增函数）仍保持不等号，得 $x_1<x_2\\Rightarrow x_1^{1/3}<x_2^{1/3}$，故在整个 $\\mathbb{R}$ 上单调递增。选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,18,43,41,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:18.821','2026-10-26 16:43:23.061','2026-10-26 17:17:18.000'),(178,'CAND-G1B-027','formal','application','炮弹高度 $h(t)=-5t^2+30t$（$t$ 秒，$0\\le t\\le6$）。\n（1）求 $h$ 的最大值；\n（2）何时落地？',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"max\", \"title\": \"最大高度\", \"criteria\": \"45m,t=3\", \"maxScore\": 5}, {\"key\": \"zero\", \"title\": \"落地时刻\", \"criteria\": \"t=6\", \"maxScore\": 3}, {\"key\": \"u\", \"title\": \"单位\", \"criteria\": \"m,s\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"（1）$45\\\\text{m}$（$t=3$）；（2）$t=6$ 时 $h=0$。\"}','二次函数 $h(t)=-5t^2+30t$（$0\\le t\\le6$）开口向下，对称轴 $t=-b/(2a)=30/(10)=3$，且 $3$ 落在定义域内，故最大值为 $h(3)=-5\\cdot9+90=45$（米）。落地即 $h(t)=0$：$t(-5t+30)=0$，得 $t=0$ 或 $t=6$；在给定区间内起飞后落地时刻为 $t=6$。端点 $h(0)=h(6)=0$ 与题意一致。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,41,18,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:18.929','2026-10-26 16:43:23.065','2026-10-26 17:17:18.000'),(179,'CAND-G1B-028','formal','numeric','$f(x)=\\begin{cases}2x+1,&x<0\\\\x^2,&x\\ge0\\end{cases}$，求 $f(-2)+f(2)$',NULL,'{\"kind\": \"numeric\", \"value\": \"1\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','分段函数求值先判断自变量落在哪一段。因 $-2<0$，用左支 $f(x)=2x+1$，得 $f(-2)=2(-2)+1=-3$；因 $2\\ge0$，用右支 $f(x)=x^2$，得 $f(2)=4$。于是 $f(-2)+f(2)=-3+4=1$。边界注意：$x=0$ 属于右支；若把 $-2$ 误代入 $x^2$ 会得 $4$，和就会错成 $8$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,41,24,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:19.039','2026-10-26 16:43:23.073','2026-10-26 17:17:19.000'),(180,'CAND-G1B-029','formal','judge','$y=2x^2$ 是幂函数。',NULL,'{\"kind\": \"judge\", \"value\": false}','幂函数标准形式为 $y=x^{\\alpha}$（系数恒为 $1$）。$y=2x^2$ 可写成 $2\\cdot x^2$，前面多了系数 $2$，不符合定义，故不是幂函数。命题错误。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,43,38,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:19.188','2026-10-26 16:43:23.079','2026-10-26 17:17:19.000'),(181,'CAND-G1B-030','formal','numeric','$f(x)=-x^2+4x$ 在 $[0,5]$ 上最大值为',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','配方：$f(x)=-x^2+4x=-(x-2)^2+4$，开口向下，顶点为 $(2,4)$。闭区间 $[0,5]$ 含顶点横坐标 $2$，故区间最大值为顶点纵坐标 $4$。端点对照：$f(0)=0$，$f(5)=-25+20=-5$，都小于 $4$。也可用导数 $f\'(x)=-2x+4=0\\Rightarrow x=2$ 同一结论。答案 $4$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,18,42,31,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:19.356','2026-10-26 16:43:23.084','2026-10-26 17:17:19.000'),(182,'CAND-G1B-031','formal','single','$\\sqrt[3]{-27}=$','{\"options\": [{\"id\": \"A\", \"text\": \"$3$\"}, {\"id\": \"B\", \"text\": \"$-3$\"}, {\"id\": \"C\", \"text\": \"$9$\"}, {\"id\": \"D\", \"text\": \"不存在\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','求立方根 $\\sqrt[3]{-27}$，即找立方等于 $-27$ 的实数。因为 $(-3)^3=-27$，所以结果为 $-3$。奇次方根允许底数为负，不要误认为无实数解。选 B。可用 $(-3)^3=-27$ 回代验证。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,48,65,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:19.540','2026-10-26 16:43:23.090','2026-10-26 17:17:19.000'),(183,'CAND-G1B-032','formal','numeric','$8^{2/3}=$',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','分数指数幂：$8^{2/3}=(\\sqrt[3]{8})^2=2^2=4$。也可先平方再开立方：$(8^2)^{1/3}=64^{1/3}=4$。两种顺序结果一致。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,48,66,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:19.616','2026-10-26 16:43:23.095','2026-10-26 17:17:19.000'),(184,'CAND-G1B-033','formal','application','细菌数 $N(t)=N_0\\cdot2^{t/3}$（$t$ 小时）。$N_0=500$，求 $t=9$ 时 $N$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"sub\", \"title\": \"代入\", \"criteria\": \"t=9\", \"maxScore\": 3}, {\"key\": \"calc\", \"title\": \"计算\", \"criteria\": \"4000\", \"maxScore\": 5}], \"maxScore\": 8, \"standardAnswer\": \"$N=4000$。\"}','指数增长模型 $N(t)=500\\cdot2^{t/3}$。当 $t=9$ 时指数为 $9/3=3$，故 $N(9)=500\\cdot2^3=500\\cdot8=4000$。含义：每过 $3$ 小时数量翻一番，经 $9$ 小时共翻 $3$ 番。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,52,80,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:19.712','2026-10-26 16:43:23.099','2026-10-26 17:17:19.000'),(185,'CAND-G1B-034','formal','judge','$y=2^x$ 的定义域为 $\\mathbb{R}$。',NULL,'{\"kind\": \"judge\", \"value\": true}','指数函数 $y=a^x$（$a>0$ 且 $a\\ne1$）的定义域规定为全体实数 $\\mathbb{R}$。这里底数 $2$ 满足条件，故 $y=2^x$ 定义域为 $\\mathbb{R}$。命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,49,69,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:19.822','2026-10-26 16:43:23.105','2026-10-26 17:17:19.000'),(186,'CAND-G1B-035','formal','single','$a=0.3^{0.5}$，$b=0.3^{0.3}$，则','{\"options\": [{\"id\": \"A\", \"text\": \"$a>b$\"}, {\"id\": \"B\", \"text\": \"$a<b$\"}, {\"id\": \"C\", \"text\": \"$a=b$\"}, {\"id\": \"D\", \"text\": \"不确定\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','底数 $0.3\\in(0,1)$ 时，$y=0.3^x$ 单调递减：指数越大，函数值越小。比较指数 $0.5$ 与 $0.3$，因 $0.5>0.3$，故 $0.3^{0.5}<0.3^{0.3}$，即 $a<b$。选 B。若底数大于 $1$ 则结论相反。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,49,70,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:19.929','2026-10-26 16:43:23.109','2026-10-26 17:17:19.000'),(187,'CAND-G1B-036','formal','single','$\\log_2 32=$','{\"options\": [{\"id\": \"A\", \"text\": \"$4$\"}, {\"id\": \"B\", \"text\": \"$5$\"}, {\"id\": \"C\", \"text\": \"$6$\"}, {\"id\": \"D\", \"text\": \"$16$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','由对数定义：$\\log_2 32=k$ 等价于 $2^k=32$。把 $32$ 写成 $2$ 的幂：$32=2^5$，因此 $k=5$，选 B。相邻幂核对：$2^4=16$、$2^5=32$、$2^6=64$，可排除 A、C；D 的 $16$ 是真数而不是对数值。也可写 $\\log_2(2^5)=5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,50,73,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:20.037','2026-10-26 16:43:23.197','2026-10-26 17:17:20.000'),(188,'CAND-G1B-037','formal','multi','下列关于对数运算法则的说法，正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\log_a(MN)=\\\\log_aM+\\\\log_aN$\"}, {\"id\": \"B\", \"text\": \"$\\\\log_a\\\\dfrac MN=\\\\log_aM-\\\\log_aN$\"}, {\"id\": \"C\", \"text\": \"$\\\\log_aM^2=2\\\\log_aM$\"}, {\"id\": \"D\", \"text\": \"$\\\\log_a1=0$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','A、B 是常用对数运算法则（在真数、底数合法时成立）；D 为 $\\log_a1=0$。C 写成 $\\log_a M^2=2\\log_a M$：一般应先保证真数为正，严格形式常写 $2\\log_a|M|$（并讨论定义域）；题干未限定 $M>0$ 时不宜直接选 C。故正确选项为 A、B、D。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,50,74,'approved',1,'v1',2,2,2,2,'2026-10-26 17:17:20.187','2026-10-26 16:43:23.202','2026-10-26 17:17:20.000'),(189,'CAND-G1B-038','formal','application','地震能量 $E$ 与里氏级 $M$ 满足 $\\lg E=4.8+1.5M$。$M=6$ 时 $\\lg E$ 为多少？',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"f\", \"title\": \"公式代入\", \"criteria\": \"M=6\", \"maxScore\": 3}, {\"key\": \"r\", \"title\": \"结果\", \"criteria\": \"13.8\", \"maxScore\": 3}], \"maxScore\": 6, \"standardAnswer\": \"$\\\\lg E=13.8$。\"}','能量与里氏级满足 $\\lg E=4.8+1.5M$。将 $M=6$ 代入：先算 $1.5\\times6=9$，再得 $\\lg E=4.8+9=13.8$。题干只要求 $\\lg E$，不必再求 $E=10^{13.8}$。数量级核对：震级每增加 $2/3$ 约使能量增大 $10$ 倍，此处直接代入最稳妥。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,19,52,81,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:20.269','2026-10-26 16:43:23.207','2026-10-26 17:17:20.000'),(190,'CAND-G1B-039','formal','single','$y=\\log_{0.5}x$ 的定义域为','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\mathbb{R}$\"}, {\"id\": \"B\", \"text\": \"$(0,+\\\\infty)$\"}, {\"id\": \"C\", \"text\": \"$[0,+\\\\infty)$\"}, {\"id\": \"D\", \"text\": \"$(-\\\\infty,0)$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','对数函数 $y=\\log_a x$ 要求真数 $x>0$，且底数满足 $a>0$、$a\\ne1$。本题底数 $0.5\\in(0,1)$ 只决定函数单调递减，并不改变定义域，故定义域仍为 $(0,+\\infty)$，选 B。注意不能取 $x=0$ 或负数（对数无定义），故排除 A、C、D。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,19,51,77,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:20.404','2026-10-26 16:43:23.210','2026-10-26 17:17:20.000'),(191,'CAND-G1B-040','formal','numeric','$\\log_3 81=$',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','由对数定义：$\\log_3 81=k\\Leftrightarrow3^k=81$。因为 $81=3^4$，所以 $k=4$；也可直接写 $\\log_3(3^4)=4$。相邻幂核对：$3^3=27$、$3^4=81$、$3^5=243$，可确认答案为 $4$。代入回验：$3^4=81$ 成立。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,19,51,78,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:20.609','2026-10-26 16:43:23.214','2026-10-26 17:17:20.000'),(192,'CAND-G1B-041','formal','single','$2^{x+1}=16$ 的解为','{\"options\": [{\"id\": \"A\", \"text\": \"$2$\"}, {\"id\": \"B\", \"text\": \"$3$\"}, {\"id\": \"C\", \"text\": \"$4$\"}, {\"id\": \"D\", \"text\": \"$5$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','把右边写成同底：$16=2^4$，方程化为 $2^{x+1}=2^4$。指数函数 $y=2^x$ 一一对应，故指数相等：$x+1=4$，解得 $x=3$。选 B。回代：$2^{3+1}=2^4=16$ 成立。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,49,72,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:20.719','2026-10-26 16:43:23.219','2026-10-26 17:17:20.000'),(193,'CAND-G1B-042','formal','application','证明：方程 $2^x=5-x$ 在 $(1,2)$ 内有唯一实根（说明单调性与端点符号）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"f\", \"title\": \"构造函数\", \"criteria\": \"$f(x)=2^x+x-5$\", \"maxScore\": 3}, {\"key\": \"sign\", \"title\": \"端点符号\", \"criteria\": \"异号\", \"maxScore\": 4}, {\"key\": \"mono\", \"title\": \"单调唯一\", \"criteria\": \"递增\", \"maxScore\": 3}], \"maxScore\": 10, \"standardAnswer\": \"令 $f(x)=2^x+x-5$，$f(1)=-2<0$，$f(2)=1>0$，且 $f$ 递增，故唯一根在 $(1,2)$。\"}','要证方程 $2^x=5-x$ 在 $(1,2)$ 内有唯一实根。令 $f(x)=2^x+x-5$，则等价于 $f(x)=0$。因 $f\'(x)=2^x\\ln2+1>0$，故 $f$ 在 $\\mathbb{R}$ 严格递增，零点至多一个。又 $f(1)=2+1-5=-2<0$，$f(2)=4+2-5=1>0$，由零点存在定理，$(1,2)$ 内恰有一根。端点符号相反保证存在，单调性保证唯一。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,52,80,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:20.792','2026-10-26 16:43:23.224','2026-10-26 17:17:20.000'),(194,'CAND-G1B-043','formal','judge','$\\log_4 8=\\dfrac{\\log_2 8}{\\log_2 4}$。',NULL,'{\"kind\": \"judge\", \"value\": true}','换底公式 $\\log_b a=\\dfrac{\\log_c a}{\\log_c b}$（$c>0,c\\ne1$）。取 $c=2$ 即得 $\\log_4 8=\\dfrac{\\log_2 8}{\\log_2 4}$。命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,50,75,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:20.928','2026-10-26 16:43:23.228','2026-10-26 17:17:20.000'),(195,'CAND-G1B-044','formal','numeric','$(\\dfrac1{27})^{-2/3}=$',NULL,'{\"kind\": \"numeric\", \"value\": \"9\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','负分数指数先化为正指数：$(\\dfrac{1}{27})^{-2/3}=27^{2/3}$。再按“先根后幂”：$27^{2/3}=(\\sqrt[3]{27})^2=3^2=9$。也可先幂后根：$(27^2)^{1/3}=729^{1/3}=9$。两种顺序一致；注意负指数表示取倒数，分数指数分母为根指数。答案 $9$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,19,48,67,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.045','2026-10-26 16:43:23.231','2026-10-26 17:17:21.000'),(196,'CAND-G1B-045','formal','application','存款本金 $10000$ 元，年利率 $5\\%$ 复利，求 $3$ 年后本息和（精确到元）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"f\", \"title\": \"公式\", \"criteria\": \"$10000\\\\times1.05^3$\", \"maxScore\": 4}, {\"key\": \"c\", \"title\": \"计算\", \"criteria\": \"11576\", \"maxScore\": 4}, {\"key\": \"u\", \"title\": \"单位\", \"criteria\": \"元\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"$11576$\"}','复利本息和公式 $A=P(1+r)^n$。代入 $P=10000$、$r=0.05$、$n=3$，得 $A=10000\\times(1.05)^3$。先算 $(1.05)^2=1.1025$，再乘 $1.05$ 得 $1.157625$，故 $A=11576.25$。按“精确到元”通常四舍五入得 $11576$。可用 $(1.05)^3=1.157625$ 再核一次小数。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,52,81,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.118','2026-10-26 16:43:23.236','2026-10-26 17:17:21.000'),(197,'CAND-G1B-046','formal','judge','$-390^\\circ$ 是第四象限角。',NULL,'{\"kind\": \"judge\", \"value\": true}','终边相同角：$-390^\\circ=-360^\\circ+(-30^\\circ)$，与 $-30^\\circ$ 终边相同。$-30^\\circ$ 在第四象限，故 $-390^\\circ$ 也是第四象限角。命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,55,96,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.229','2026-10-26 16:43:23.241','2026-10-26 17:17:21.000'),(198,'CAND-G1B-047','formal','numeric','$\\dfrac{5\\pi}{6}$ 化为度数（整数）',NULL,'{\"kind\": \"numeric\", \"value\": \"150\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','换算关系：$\\pi$ 弧度 $=180^\\circ$。因此 $\\dfrac{5\\pi}{6}=\\dfrac{5}{6}\\times180^\\circ=150^\\circ$。答案填整数 $150$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,55,97,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.336','2026-10-26 16:43:23.245','2026-10-26 17:17:21.000'),(199,'CAND-G1B-048','formal','application','圆半径 $r=10\\text{cm}$，圆心角 $60^\\circ$，求弧长（$\\pi$ 形式）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"rad\", \"title\": \"化弧度\", \"criteria\": \"$\\\\pi/3$\", \"maxScore\": 3}, {\"key\": \"l\", \"title\": \"弧长\", \"criteria\": \"$10\\\\pi/3$\", \"maxScore\": 5}], \"maxScore\": 8, \"standardAnswer\": \"$l=\\\\dfrac{10\\\\pi}{3}\\\\text{cm}$。\"}','先把圆心角化为弧度：$60^\\circ=\\dfrac{\\pi}{3}$。弧长公式 $l=r\\theta$ 得 $l=10\\cdot\\dfrac{\\pi}{3}=\\dfrac{10\\pi}{3}\\text{cm}$。也可用 $l=\\dfrac{n\\pi r}{180}$ 得同一结果。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,55,98,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.445','2026-10-26 16:43:23.248','2026-10-26 17:17:21.000'),(200,'CAND-G1B-049','formal','single','$\\alpha$ 终边过 $P(-3,4)$，则 $\\sin\\alpha=$','{\"options\": [{\"id\": \"A\", \"text\": \"$3/5$\"}, {\"id\": \"B\", \"text\": \"$4/5$\"}, {\"id\": \"C\", \"text\": \"$-4/5$\"}, {\"id\": \"D\", \"text\": \"$-3/5$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','终边上点 $P(-3,4)$，半径 $r=\\sqrt{(-3)^2+4^2}=5$。按定义 $\\sin\\alpha=\\dfrac{y}{r}=\\dfrac{4}{5}$（纵坐标为正，正弦为正）。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,56,99,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.554','2026-10-26 16:43:23.254','2026-10-26 17:17:21.000'),(201,'CAND-G1B-050','formal','single','$\\sin\\theta=\\dfrac35$，$\\theta$ 在第二象限，则 $\\cos\\theta=$','{\"options\": [{\"id\": \"A\", \"text\": \"$4/5$\"}, {\"id\": \"B\", \"text\": \"$-4/5$\"}, {\"id\": \"C\", \"text\": \"$3/5$\"}, {\"id\": \"D\", \"text\": \"$-3/5$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','由 $\\sin^2+\\cos^2=1$，$\\cos^2=1-(\\dfrac{3}{5})^2=\\dfrac{16}{25}$。第二象限余弦为负，故 $\\cos\\theta=-\\dfrac{4}{5}$。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,56,100,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.668','2026-10-26 16:43:23.258','2026-10-26 17:17:21.000'),(202,'CAND-G1B-051','formal','numeric','$\\sin\\!\\left(\\dfrac{7\\pi}{6}\\right)=$',NULL,'{\"kind\": \"numeric\", \"value\": \"-0.5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$\\dfrac{7\\pi}{6}=\\pi+\\dfrac{\\pi}{6}$ 落在第三象限，正弦为负：$\\sin\\dfrac{7\\pi}{6}=-\\sin\\dfrac{\\pi}{6}=-\\dfrac12=-0.5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,57,102,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.771','2026-10-26 16:43:23.262','2026-10-26 17:17:21.000'),(203,'CAND-G1B-052','formal','application','化简：$\\sin(\\pi-\\theta)+\\sin(\\pi+\\theta)$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"s1\", \"title\": \"第一项\", \"criteria\": \"$\\\\sin\\\\theta$\", \"maxScore\": 4}, {\"key\": \"s2\", \"title\": \"第二项\", \"criteria\": \"$-\\\\sin\\\\theta$\", \"maxScore\": 4}, {\"key\": \"r\", \"title\": \"结果\", \"criteria\": \"0\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"$0$。\"}','用诱导公式分别化简：$\\sin(\\pi-\\theta)=\\sin\\theta$（诱导“奇变偶不变，符号看象限”中正弦在第二象限为正），$\\sin(\\pi+\\theta)=-\\sin\\theta$（第三象限正弦为负）。两式相加：$\\sin\\theta+(-\\sin\\theta)=0$。故原式恒等于 $0$（对使式子有定义的 $\\theta$）。可用特殊值 $\\theta=\\pi/6$ 代入检验。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,57,104,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.879','2026-10-26 16:43:23.265','2026-10-26 17:17:21.000'),(204,'CAND-G1B-053','formal','single','$y=\\sin x$ 的最小正周期为','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\pi$\"}, {\"id\": \"B\", \"text\": \"$2\\\\pi$\"}, {\"id\": \"C\", \"text\": \"$4\\\\pi$\"}, {\"id\": \"D\", \"text\": \"$\\\\pi/2$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','正弦函数 $y=\\sin x$ 的图象每隔 $2\\pi$ 重复一次，且 $2\\pi$ 是最小正周期（更小的正数如 $\\pi$ 不成立，因 $\\sin(x+\\pi)=-\\sin x$）。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,58,105,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:21.990','2026-10-26 16:43:23.271','2026-10-26 17:17:21.000'),(205,'CAND-G1B-054','formal','judge','$y=\\cos x$ 为偶函数。',NULL,'{\"kind\": \"judge\", \"value\": true}','偶函数定义要求 $f(-x)=f(x)$。对余弦：$\\cos(-x)=\\cos x$ 恒成立，故 $y=\\cos x$ 是偶函数（图象关于 $y$ 轴对称）。命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,58,106,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.081','2026-10-26 16:43:23.276','2026-10-26 17:17:22.000'),(206,'CAND-G1B-055','formal','single','$\\cos75^\\circ=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\frac{\\\\sqrt6+\\\\sqrt2}{4}$\"}, {\"id\": \"B\", \"text\": \"$\\\\frac{\\\\sqrt6-\\\\sqrt2}{4}$\"}, {\"id\": \"C\", \"text\": \"$\\\\frac{\\\\sqrt2-\\\\sqrt6}{4}$\"}, {\"id\": \"D\", \"text\": \"$-\\\\frac{\\\\sqrt6+\\\\sqrt2}{4}$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','$\\cos75^\\circ=\\cos(45^\\circ+30^\\circ)=\\cos45\\cos30-\\sin45\\sin30=\\dfrac{\\sqrt2}{2}\\cdot\\dfrac{\\sqrt3}{2}-\\dfrac{\\sqrt2}{2}\\cdot\\dfrac12=\\dfrac{\\sqrt6-\\sqrt2}{4}$。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,59,108,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.181','2026-10-26 16:43:23.279','2026-10-26 17:17:22.000'),(207,'CAND-G1B-056','formal','application','证明：$\\dfrac{1-\\cos2\\alpha}{\\sin2\\alpha}=\\tan\\alpha$（$\\alpha$ 使分母不为0）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"num\", \"title\": \"分子\", \"criteria\": \"$2\\\\sin^2\\\\alpha$\", \"maxScore\": 4}, {\"key\": \"den\", \"title\": \"分母\", \"criteria\": \"$2\\\\sin\\\\alpha\\\\cos\\\\alpha$\", \"maxScore\": 3}, {\"key\": \"r\", \"title\": \"结论\", \"criteria\": \"$\\\\tan\\\\alpha$\", \"maxScore\": 3}], \"maxScore\": 10, \"standardAnswer\": \"左式 $=\\\\dfrac{2\\\\sin^2\\\\alpha}{2\\\\sin\\\\alpha\\\\cos\\\\alpha}=\\\\tan\\\\alpha$。\"}','左式用倍角：$1-\\cos2\\alpha=2\\sin^2\\alpha$，$\\sin2\\alpha=2\\sin\\alpha\\cos\\alpha$，故 $\\dfrac{2\\sin^2\\alpha}{2\\sin\\alpha\\cos\\alpha}=\\tan\\alpha$（分母 $\\ne0$）。得证。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,59,111,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.272','2026-10-26 16:43:23.283','2026-10-26 17:17:22.000'),(208,'CAND-G1B-057','formal','numeric','$\\sin15^\\circ\\cos15^\\circ=$',NULL,'{\"kind\": \"numeric\", \"value\": \"0.25\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','二倍角：$\\sin2\\alpha=2\\sin\\alpha\\cos\\alpha$，故 $\\sin15^\\circ\\cos15^\\circ=\\dfrac12\\sin30^\\circ=\\dfrac12\\cdot\\dfrac12=\\dfrac14=0.25$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,59,109,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.373','2026-10-26 16:43:23.289','2026-10-26 17:17:22.000'),(209,'CAND-G1B-058','formal','single','$y=3\\sin(2x+\\pi/3)$ 的振幅为','{\"options\": [{\"id\": \"A\", \"text\": \"$2$\"}, {\"id\": \"B\", \"text\": \"$3$\"}, {\"id\": \"C\", \"text\": \"$\\\\pi/3$\"}, {\"id\": \"D\", \"text\": \"$2\\\\pi$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','形如 $y=A\\sin(\\omega x+\\varphi)$ 的函数，振幅是 $|A|$，周期由 $\\omega$ 决定，初相由 $\\varphi$ 决定。本题系数 $A=3$，因此振幅为 $3$，与 $2$、$\\pi/3$ 无关。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,60,112,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.473','2026-10-26 16:43:23.294','2026-10-26 17:17:22.000'),(210,'CAND-G1B-059','formal','multi','$y=\\sin x$ 经何种变换得 $y=\\sin(2x)$（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"横坐标缩短为原来1/2\"}, {\"id\": \"B\", \"text\": \"横坐标伸长为原来2倍\"}, {\"id\": \"C\", \"text\": \"纵坐标不变\"}, {\"id\": \"D\", \"text\": \"向右平移\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\"]}','比较 $y=\\sin x$ 与 $y=\\sin(2x)$：把角换成 $2x$ 后，周期由 $2\\pi$ 变为 $\\pi$，相当于横坐标（周期）缩短为原来的 $\\dfrac12$，即 A；纵坐标振幅仍为 $1$，尺度不变，即 C。题干没有 $\\varphi$ 平移项，故不向右平移（排除 D）；也不是伸长（排除 B）。因此选 A、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,60,113,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.589','2026-10-26 16:43:23.358','2026-10-26 17:17:22.000'),(211,'CAND-G1B-060','formal','application','潮高 $h(t)=2\\cos(\\dfrac{\\pi t}{6})+4$（$t$ 为小时）。求最高潮高与周期。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"max\", \"title\": \"最高\", \"criteria\": \"6m\", \"maxScore\": 4}, {\"key\": \"T\", \"title\": \"周期\", \"criteria\": \"12h\", \"maxScore\": 4}], \"maxScore\": 8, \"standardAnswer\": \"最高 $6\\\\text{m}$，周期 $12\\\\text{h}$。\"}','潮高 $h(t)=2\\cos(\\dfrac{\\pi t}{6})+4$。振幅为 $|2|=2$，平衡位置（竖直平移）为 $4$，故最高潮高为 $4+2=6$（米），最低为 $2$。角频率 $\\omega=\\pi/6$，周期 $T=\\dfrac{2\\pi}{\\omega}=\\dfrac{2\\pi}{\\pi/6}=12$（小时）。当 $\\cos=1$ 时取最高；例如 $t=0$ 时 $h=6$ 可作代入检验。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,61,116,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.692','2026-10-26 16:43:23.362','2026-10-26 17:17:22.000'),(212,'CAND-G1B-061','formal','single','$h=2\\sin(3t)+5$ 的最大值为','{\"options\": [{\"id\": \"A\", \"text\": \"$2$\"}, {\"id\": \"B\", \"text\": \"$3$\"}, {\"id\": \"C\", \"text\": \"$5$\"}, {\"id\": \"D\", \"text\": \"$7$\"}]}','{\"kind\": \"single\", \"optionId\": \"D\"}','函数 $h=2\\sin(3t)+5$ 中，$\\sin(3t)\\in[-1,1]$，从而 $2\\sin(3t)\\in[-2,2]$，再加上常数 $5$，得值域 $h\\in[3,7]$。因此最大值为 $7$，选 D。注意最大值不是振幅 $2$，也不是平衡位置 $5$；角频率 $3$ 只影响周期，不影响最值。当 $\\sin(3t)=1$ 时取到 $7$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,61,115,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.812','2026-10-26 16:43:23.367','2026-10-26 17:17:22.000'),(213,'CAND-G1B-062','formal','judge','$y=\\tan x$ 在 $(-\\pi/2,\\pi/2)$ 递增。',NULL,'{\"kind\": \"judge\", \"value\": true}','正切函数 $y=\\tan x$ 的定义域是去掉奇异点的开区间并，在每一个 $(-\\dfrac{\\pi}{2}+k\\pi,\\dfrac{\\pi}{2}+k\\pi)$ 内导数为正、严格递增。特别地，在 $(-\\pi/2,\\pi/2)$ 上单调递增。命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,58,107,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:22.908','2026-10-26 16:43:23.372','2026-10-26 17:17:22.000'),(214,'CAND-G1B-063','formal','single','$\\cos(\\pi-\\alpha)=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\cos\\\\alpha$\"}, {\"id\": \"B\", \"text\": \"$-\\\\cos\\\\alpha$\"}, {\"id\": \"C\", \"text\": \"$\\\\sin\\\\alpha$\"}, {\"id\": \"D\", \"text\": \"$-\\\\sin\\\\alpha$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','诱导公式：$\\cos(\\pi-\\alpha)=-\\cos\\alpha$，故选 B。几何理解：$\\pi-\\alpha$ 与 $\\alpha$ 互补（或看作第二象限相关角），余弦在第二象限为负，因而带负号。常见混淆：误记成 $\\cos\\alpha$（偶次不变却忘看符号），或与 $\\sin(\\pi-\\alpha)=\\sin\\alpha$ 搞混。可用 $\\alpha=0$：$\\cos\\pi=-1=-\\cos0$ 快速核对。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,57,103,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.022','2026-10-26 16:43:23.376','2026-10-26 17:17:23.000'),(215,'CAND-G1B-064','formal','application','塔高测量：距塔底 $40\\text{m}$ 处测得塔顶的仰角为 $30^\\circ$，求塔高（精确值）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"model\", \"title\": \"模型\", \"criteria\": \"$\\\\tan30^\\\\circ$\", \"maxScore\": 4}, {\"key\": \"calc\", \"title\": \"计算\", \"criteria\": \"$40\\\\sqrt3/3$\", \"maxScore\": 4}, {\"key\": \"u\", \"title\": \"单位\", \"criteria\": \"m\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"$h=\\\\dfrac{40\\\\sqrt3}{3}\\\\text{m}$。\"}','直角三角形中，仰角 $30^\\circ$，邻边（水平距离）为 $40$，对边为塔高 $h$。故 $h=40\\tan30^\\circ=40\\cdot\\dfrac{\\sqrt3}{3}=\\dfrac{40\\sqrt3}{3}\\text{m}$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,61,117,'approved',1,'v1',3,2,2,2,'2026-10-26 21:01:11.114','2026-10-26 16:43:23.379','2026-10-26 21:01:11.000'),(216,'CAND-G1B-065','formal','numeric','$\\sqrt3\\sin x+\\cos x$ 的最大值为',NULL,'{\"kind\": \"numeric\", \"value\": \"2\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','辅助角法：把 $\\sqrt3\\sin x+\\cos x$ 写成 $R\\sin(x+\\varphi)$。取 $R=\\sqrt{(\\sqrt3)^2+1^2}=2$，则 $\\dfrac{\\sqrt3}{2}\\sin x+\\dfrac12\\cos x=\\sin(x+\\dfrac{\\pi}{6})$，故原式 $=2\\sin(x+\\dfrac{\\pi}{6})$。正弦最大值为 $1$，因此原式最大值为 $2$。当 $x+\\pi/6=\\pi/2$ 即 $x=\\pi/3$ 时取到。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,59,110,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.240','2026-10-26 16:43:23.383','2026-10-26 17:17:23.000'),(217,'CAND-G1B-066','formal','judge','零向量与任何向量平行。',NULL,'{\"kind\": \"judge\", \"value\": true}','向量平行（共线）的教材约定：零向量与任意向量都平行。这是定义性规定，目的是使“共线向量”“基底”等后续命题表述简洁统一。故“零向量与任何向量平行”正确。注意零向量没有确定方向，但仍规定与任意向量平行。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,62,127,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.339','2026-10-26 16:43:23.388','2026-10-26 17:17:23.000'),(218,'CAND-G1B-067','formal','numeric','设 $\\vec a=(3,4)$，则 $|\\vec a|=$',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','平面向量模长公式：$|\\vec a|=\\sqrt{x^2+y^2}$。代入 $\\vec a=(3,4)$ 得 $\\sqrt{9+16}=\\sqrt{25}=5$。此即勾股数 $3$-$4$-$5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,62,128,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.462','2026-10-26 16:43:23.391','2026-10-26 17:17:23.000'),(219,'CAND-G1B-068','formal','application','物体受两力 $\\vec F_1=(3,4)$，$\\vec F_2=(-1,2)$（N），求合力大小。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"add\", \"title\": \"求和\", \"criteria\": \"(2,6)\", \"maxScore\": 4}, {\"key\": \"m\", \"title\": \"模长\", \"criteria\": \"$2\\\\sqrt{10}$\", \"maxScore\": 4}], \"maxScore\": 8, \"standardAnswer\": \"$|\\\\vec F|=\\\\sqrt{2^2+6^2}=\\\\sqrt{40}=2\\\\sqrt{10}$ N。\"}','合力按向量加法： $\\vec F=\\vec F_1+\\vec F_2=(3,4)+(-1,2)=(3-1,4+2)=(2,6)$（单位 N）。大小为模长 $|\\vec F|=\\sqrt{2^2+6^2}=\\sqrt{4+36}=\\sqrt{40}=2\\sqrt{10}$（N）。可用勾股验算：$2^2+6^2=40$。注意不要把分量各自取绝对值后再相加当合力大小。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,65,140,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.565','2026-10-26 16:43:23.395','2026-10-26 17:17:23.000'),(220,'CAND-G1B-069','formal','single','$\\vec a+\\vec b=\\vec b+\\vec a$ 体现','{\"options\": [{\"id\": \"A\", \"text\": \"交换律\"}, {\"id\": \"B\", \"text\": \"结合律\"}, {\"id\": \"C\", \"text\": \"分配律\"}, {\"id\": \"D\", \"text\": \"数乘律\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','等式 $\\vec a+\\vec b=\\vec b+\\vec a$ 左右只是加项顺序互换而结果相同，这正是向量加法的交换律。选 A。对照：结合律形如 $(\\vec a+\\vec b)+\\vec c=\\vec a+(\\vec b+\\vec c)$；分配律涉及数乘。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,63,131,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.664','2026-10-26 16:43:23.398','2026-10-26 17:17:23.000'),(221,'CAND-G1B-070','formal','numeric','$\\vec a=(1,2)$，$\\vec b=(3,-1)$，则 $\\vec a\\cdot\\vec b=$',NULL,'{\"kind\": \"numeric\", \"value\": \"1\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','用坐标求数量积：$\\vec a\\cdot\\vec b=x_1x_2+y_1y_2$。代入 $\\vec a=(1,2)$、$\\vec b=(3,-1)$，得 $1\\cdot3+2\\cdot(-1)=3-2=1$。也可用模与夹角公式，但坐标法更直接。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,63,132,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.781','2026-10-26 16:43:23.405','2026-10-26 17:17:23.000'),(222,'CAND-G1B-071','formal','single','$\\vec a=(1,0)$，$\\vec b=(0,1)$ 夹角为','{\"options\": [{\"id\": \"A\", \"text\": \"$0^\\\\circ$\"}, {\"id\": \"B\", \"text\": \"$45^\\\\circ$\"}, {\"id\": \"C\", \"text\": \"$90^\\\\circ$\"}, {\"id\": \"D\", \"text\": \"$180^\\\\circ$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','$\\vec a=(1,0)$、$\\vec b=(0,1)$ 为坐标轴单位向量，数量积 $1\\cdot0+0\\cdot1=0$，故夹角为 $90^\\circ$。选 C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,63,133,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.882','2026-10-26 16:43:23.409','2026-10-26 17:17:23.000'),(223,'CAND-G1B-072','formal','application','船速 $\\vec v_1=(4,0)$ km/h，水流 $\\vec v_2=(0,1)$，求实际速度大小。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"v\", \"title\": \"合速度\", \"criteria\": \"(4,1)\", \"maxScore\": 3}, {\"key\": \"m\", \"title\": \"模\", \"criteria\": \"$\\\\sqrt{17}$\", \"maxScore\": 3}], \"maxScore\": 6, \"standardAnswer\": \"$\\\\sqrt{17}$ km/h。\"}','船对水速度与水流速度按向量合成： $\\vec v=\\vec v_1+\\vec v_2=(4,0)+(0,1)=(4,1)$。实际航行速率为模长 $|\\vec v|=\\sqrt{4^2+1^2}=\\sqrt{16+1}=\\sqrt{17}$（km/h）。方向由 $\\tan\\theta=1/4$ 确定，但本题只求大小。核对：$16+1=17$ 不可再开成有理数，保留根式即可。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,65,141,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:23.990','2026-10-26 16:43:23.412','2026-10-26 17:17:23.000'),(224,'CAND-G1B-073','formal','judge','任意两个非零向量都可作基底。',NULL,'{\"kind\": \"judge\", \"value\": false}','平面向量基本定理要求：作为基底的两个向量必须不共线（线性无关）。若两个非零向量共线，则存在实数 $\\lambda$ 使 $\\vec b=\\lambda\\vec a$，它们只能张成一条直线，不能张成整个平面，因此不能任意取作基底。命题“任意两个非零向量都可作基底”错误。反例：$(1,0)$ 与 $(2,0)$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,21,64,136,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:24.111','2026-10-26 16:43:23.416','2026-10-26 17:17:24.000'),(225,'CAND-G1B-074','formal','multi','下列关于平面向量运算的说法，正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\lambda(\\\\vec a+\\\\vec b)=\\\\lambda\\\\vec a+\\\\lambda\\\\vec b$\"}, {\"id\": \"B\", \"text\": \"$(\\\\vec a+\\\\vec b)+\\\\vec c=\\\\vec a+(\\\\vec b+\\\\vec c)$\"}, {\"id\": \"C\", \"text\": \"$\\\\vec a\\\\cdot\\\\vec b=\\\\vec b\\\\cdot\\\\vec a$\"}, {\"id\": \"D\", \"text\": \"$\\\\vec a\\\\times\\\\vec b=\\\\vec b\\\\times\\\\vec a$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A、B 分别是数乘分配律与向量加法结合律；C 是数量积交换律，均正确。D 写成叉积交换：高中平面向量一般不引入叉积，且空间叉积满足反交换 $\\vec a\\times\\vec b=-\\vec b\\times\\vec a$，故 D 错。选 A、B、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,64,137,'approved',1,'v1',2,2,2,2,'2026-10-26 17:17:24.222','2026-10-26 16:43:23.421','2026-10-26 17:17:24.000'),(226,'CAND-G1B-075','formal','numeric','$|\\vec a|=5$，$|\\vec b|=2$，夹角 $60^\\circ$，则 $\\vec a$ 在 $\\vec b$ 上投影数量为',NULL,'{\"kind\": \"numeric\", \"value\": \"2.5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','向量 $\\vec a$ 在 $\\vec b$ 方向上的投影（数量）公式为 $|\\vec a|\\cos\\theta$，其中 $\\theta$ 为夹角。代入 $|\\vec a|=5$、$\\theta=60^\\circ$，得 $5\\cdot\\cos60^\\circ=5\\cdot\\dfrac12=2.5$。注意：投影数量与 $|\\vec b|$ 无关（方向由 $\\vec b$ 给出即可）；若问投影向量则还需单位化 $\\vec b$。答案 $2.5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,21,63,134,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:24.316','2026-10-26 16:43:23.425','2026-10-26 17:17:24.000'),(227,'CAND-G1B-076','formal','application','力 $\\vec F=(6,8)$ N 沿位移 $\\vec s=(3,0)$ m 做功，求功 $W=\\vec F\\cdot\\vec s$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"dot\", \"title\": \"数量积\", \"criteria\": \"18\", \"maxScore\": 4}, {\"key\": \"u\", \"title\": \"单位\", \"criteria\": \"J\", \"maxScore\": 2}], \"maxScore\": 6, \"standardAnswer\": \"$W=18$ J。\"}','功的定义用数量积：$W=\\vec F\\cdot\\vec s$。坐标计算：$\\vec F=(6,8)$，$\\vec s=(3,0)$，故 $W=6\\cdot3+8\\cdot0=18+0=18$（J）。物理含义：位移只有水平分量，力的竖直分量 $8$ 对功无贡献。也可用 $W=|\\vec F||\\vec s|\\cos\\theta$，但坐标法更直接。答案 $18$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,21,65,142,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:24.458','2026-10-26 16:43:23.428','2026-10-26 17:17:24.000'),(228,'CAND-G1B-077','formal','single','相等向量必','{\"options\": [{\"id\": \"A\", \"text\": \"模相等且方向相同\"}, {\"id\": \"B\", \"text\": \"起点相同\"}, {\"id\": \"C\", \"text\": \"共线\"}, {\"id\": \"D\", \"text\": \"坐标相同\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','相等向量的定义是：模长相等且方向相同（可通过平移完全重合）。起点是否相同、是否共线、坐标是否碰巧相同，都不是“相等”的充要条件。故选 A。平移后的同一有向线段仍表示相等向量，不必共起点。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,62,129,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:24.558','2026-10-26 16:43:23.431','2026-10-26 17:17:24.000'),(229,'CAND-G1B-078','formal','single','$\\vec a=(2,4)$，$\\vec b=(1,k)$ 共线则 $k=$','{\"options\": [{\"id\": \"A\", \"text\": \"$1$\"}, {\"id\": \"B\", \"text\": \"$2$\"}, {\"id\": \"C\", \"text\": \"$3$\"}, {\"id\": \"D\", \"text\": \"$4$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','平面向量共线（平行）充要条件：存在实数 $\\lambda$ 使 $\\vec b=\\lambda\\vec a$，或非零时坐标成比例。由 $\\dfrac{2}{1}=\\dfrac{4}{k}$ 得 $2k=4$，解得 $k=2$，选 B。代入核验：$(1,2)=\\dfrac12(2,4)$，确为共线。若 $k\\ne2$ 则不存在这样的 $\\lambda$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,64,138,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:24.656','2026-10-26 16:43:23.436','2026-10-26 17:17:24.000'),(230,'CAND-G1B-079','formal','numeric','$3(1,-2)-2(2,1)=$ 的横坐标',NULL,'{\"kind\": \"numeric\", \"value\": \"-1\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','按运算顺序先数乘再加减：$3(1,-2)=(3,-6)$，$2(2,1)=(4,2)$；再作向量减法得 $(3,-6)-(4,2)=(3-4,-6-2)=(-1,-8)$。题目只要横坐标，故答案为 $-1$。也可一次写：$3(1,-2)-2(2,1)=(3-4,-6-2)=(-1,-8)$。纵坐标为 $-8$，勿误答成纵坐标。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,63,135,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:24.746','2026-10-26 16:43:23.440','2026-10-26 17:17:24.000'),(231,'CAND-G1B-080','formal','application','用向量证明：平行四边形对角线互相平分（设 $\\vec{AB}=\\vec a$，$\\vec{AD}=\\vec b$）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"diag\", \"title\": \"对角线\", \"criteria\": \"$\\\\vec a+\\\\vec b$\", \"maxScore\": 4}, {\"key\": \"mid\", \"title\": \"中点\", \"criteria\": \"平分\", \"maxScore\": 4}, {\"key\": \"cl\", \"title\": \"表述\", \"criteria\": \"清晰\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"对角线交点对应向量为 $\\\\frac{\\\\vec a+\\\\vec b}{2}$，即中点。\"}','设 $\\vec{AB}=\\vec a$，$\\vec{AD}=\\vec b$。对角线 $\\vec{AC}=\\vec a+\\vec b$，中点满足 $\\vec{AM}=\\dfrac12(\\vec a+\\vec b)$；另一对角线中点同样为 $\\dfrac{\\vec a+\\vec b}{2}$。交点重合，故互相平分。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,21,65,143,'approved',1,'v1',2,2,2,2,'2026-10-26 21:01:10.898','2026-10-26 16:43:23.500','2026-10-26 21:01:10.000'),(232,'CAND-G1B-081','formal','single','$i^2=$','{\"options\": [{\"id\": \"A\", \"text\": \"$1$\"}, {\"id\": \"B\", \"text\": \"$-1$\"}, {\"id\": \"C\", \"text\": \"$i$\"}, {\"id\": \"D\", \"text\": \"$0$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','虚数单位 $i$ 由关系 $i^2=-1$ 引入（并取 $i\\ne\\pm1$）。因此 $i^2$ 的值就是 $-1$，选 B。常用：$i^3=-i$，$i^4=1$，周期为 $4$，本题直接用定义即可。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,22,69,158,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:24.979','2026-10-26 16:43:23.506','2026-10-26 17:17:24.000'),(233,'CAND-G1B-082','formal','application','计算 $(3+2i)(1-i)$ 并写为 $a+bi$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"exp\", \"title\": \"展开\", \"criteria\": \"四项\", \"maxScore\": 3}, {\"key\": \"r\", \"title\": \"结果\", \"criteria\": \"$5-i$\", \"maxScore\": 3}], \"maxScore\": 6, \"standardAnswer\": \"$5-i$。\"}','展开复数乘法：$(3+2i)(1-i)=3\\cdot1+3(-i)+2i\\cdot1+2i(-i)=3-3i+2i-2i^2$。把 $i^2=-1$ 代入，$-2i^2=+2$，合并实部虚部得 $3+2+(-3i+2i)=5-i$。故 $a=5$、$b=-1$，标准式为 $5-i$。可用模粗检：$|3+2i|=\\sqrt{13}$，$|1-i|=\\sqrt{2}$，乘积模 $\\sqrt{26}$，而 $|5-i|=\\sqrt{26}$，一致。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,22,70,161,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.089','2026-10-26 16:43:23.510','2026-10-26 17:17:25.000'),(234,'CAND-G1B-083','formal','numeric','$|3-4i|=$',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','复数 $z=a+bi$ 的模 $|z|=\\sqrt{a^2+b^2}$。对 $z=3-4i$，取 $a=3$、$b=-4$，得 $|3-4i|=\\sqrt{9+16}=\\sqrt{25}=5$。这与勾股数 $3$-$4$-$5$ 一致。注意虚部取 $-4$ 或写成 $3+(-4)i$，平方后同为 $16$，模不变。答案 $5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,22,71,163,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.181','2026-10-26 16:43:23.513','2026-10-26 17:17:25.000'),(235,'CAND-G1B-084','formal','judge','正方体是特殊的棱柱。',NULL,'{\"kind\": \"judge\", \"value\": true}','正方体有两个互相平行且全等的正方形底面，侧棱垂直于底面且长度相等，因此它是直四棱柱，属于棱柱的特殊情形。命题“正方体是特殊的棱柱”正确；进一步也可看作特殊的长方体或直四棱柱，判断无误。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,23,72,165,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.311','2026-10-26 16:43:23.517','2026-10-26 17:17:25.000'),(236,'CAND-G1B-085','formal','numeric','底面积 $6$，高 $5$ 的圆柱体积为',NULL,'{\"kind\": \"numeric\", \"value\": \"30\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','柱体体积结构公式为 $V=$ 底面积 $\\times$ 高。已知底面积 $6$、高 $5$，直接得 $V=6\\times5=30$。该公式对圆柱、棱柱均适用；本题未额外给出半径，不必再换成 $\\pi r^2 h$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,23,74,169,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.413','2026-10-26 16:43:23.523','2026-10-26 17:17:25.000'),(237,'CAND-G1B-086','formal','application','正四棱锥底面边长 $6$，高 $4$，求体积。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"S\", \"title\": \"底面积\", \"criteria\": \"36\", \"maxScore\": 3}, {\"key\": \"V\", \"title\": \"体积\", \"criteria\": \"48\", \"maxScore\": 5}], \"maxScore\": 8, \"standardAnswer\": \"$V=48$。\"}','正四棱锥底面为正方形，边长 $6$，底面积 $S=6^2=36$。锥体体积公式 $V=\\dfrac13 Sh$，代入高 $h=4$，得 $V=\\dfrac13\\cdot36\\cdot4=48$。常见错误是漏掉系数 $\\dfrac13$ 而算成 $144$，或把底面积误成周长。答案 $V=48$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,74,170,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.514','2026-10-26 16:43:23.526','2026-10-26 17:17:25.000'),(238,'CAND-G1B-087','formal','single','过直线外一点与已知直线平行的直线有','{\"options\": [{\"id\": \"A\", \"text\": \"0条\"}, {\"id\": \"B\", \"text\": \"1条\"}, {\"id\": \"C\", \"text\": \"2条\"}, {\"id\": \"D\", \"text\": \"无数条\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','空间中平行的基本事实：过直线外一点，有且只有一条直线与已知直线平行。因此条数为 $1$，选 B。平面内同样成立。注意：“过一点与已知直线垂直的直线”可以有无数条（在垂直平面内），不要与平行情形混淆。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,23,75,173,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.611','2026-10-26 16:43:23.529','2026-10-26 17:17:25.000'),(239,'CAND-G1B-088','formal','judge','平面外一条直线与平面内一条直线平行，则该直线与平面平行。',NULL,'{\"kind\": \"judge\", \"value\": true}','线面平行判定定理：若直线 $l$ 不在平面 $\\alpha$ 内（即平面外直线），且 $l$ 平行于 $\\alpha$ 内的某一条直线，则可判定 $l\\parallel\\alpha$。题干“平面外一条直线与平面内一条直线平行，则该直线与平面平行”正是该判定的叙述，故命题正确。注意前提“平面外”不可少，否则直线可能就在平面内。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,76,175,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.709','2026-10-26 16:43:23.533','2026-10-26 17:17:25.000'),(240,'CAND-G1B-089','formal','single','若 $l\\perp\\alpha$，则 $l$ 与 $\\alpha$ 内任意直线','{\"options\": [{\"id\": \"A\", \"text\": \"平行\"}, {\"id\": \"B\", \"text\": \"垂直\"}, {\"id\": \"C\", \"text\": \"相交\"}, {\"id\": \"D\", \"text\": \"不确定\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','线面垂直的性质定理：若直线 $l\\perp$ 平面 $\\alpha$，则 $l$ 垂直于 $\\alpha$ 内的任意一条直线。这是线面垂直定义（垂直于平面内两条相交直线）的直接推论，也是证明线线垂直、求线面角等的常用依据。故选 B（垂直）。不一定平行或相交：平面内直线可与 $l$ 异面（在空间意义下仍保持垂直关系按定义讨论）。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,77,177,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.833','2026-10-26 16:43:23.539','2026-10-26 17:17:25.000'),(241,'CAND-G1B-090','formal','application','圆柱（$r=2,h=5$）上放同底圆柱（$r=2,h=3$），求总体积。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"s\", \"title\": \"底面积\", \"criteria\": \"$4\\\\pi$\", \"maxScore\": 2}, {\"key\": \"v\", \"title\": \"体积\", \"criteria\": \"$32\\\\pi$\", \"maxScore\": 6}], \"maxScore\": 8, \"standardAnswer\": \"$V=32\\\\pi$。\"}','两圆柱底面半径同为 $r=2$，高分别为 $h_1=5$、$h_2=3$。叠放后总体积等于两段体积之和，也等于同底圆柱以总高 $8$ 计算：$V=\\pi r^2(h_1+h_2)=\\pi\\cdot4\\cdot8=32\\pi$。分开算：$20\\pi+12\\pi=32\\pi$，一致。注意不要把半径当成直径。答案 $32\\pi$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,23,74,171,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:25.941','2026-10-26 16:43:23.542','2026-10-26 17:17:25.000'),(242,'CAND-G1B-091','formal','single','斜二测画法画水平放置的平面图形时，下列说法正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"原坐标系中 $\\\\angle xOy=90^\\\\circ$；直观图中 $\\\\angle x\'O\'y\'$ 通常取 $45^\\\\circ$ 或 $135^\\\\circ$\"}, {\"id\": \"B\", \"text\": \"原坐标系中 $\\\\angle xOy=45^\\\\circ$；直观图中 $\\\\angle x\'O\'y\'=90^\\\\circ$\"}, {\"id\": \"C\", \"text\": \"原坐标系与直观图中两轴夹角均为 $45^\\\\circ$\"}, {\"id\": \"D\", \"text\": \"原坐标系与直观图中两轴夹角均为 $90^\\\\circ$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','斜二测须区分两套角：①原水平面坐标系中 $\\angle xOy=90^\\circ$（直角）；②画成直观图后，教材约定 $\\angle x\'O\'y\'$ 通常取 $45^\\circ$ 或 $135^\\circ$（两种摆放同属合法约定，不可与原直角混谈）。另：$O\'z\'$ 轴竖直；平行于 $x$、$z$ 轴的线段长度不变，平行于 $y$ 轴的线段取原来的 $\\dfrac12$。故只有 A 同时正确表述原角与直观图角。B 把两角对调；C、D 把两套角说成相同，均错。选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,23,73,167,'approved',1,'v1',2,2,2,2,'2026-10-26 21:01:11.832','2026-10-26 16:43:23.545','2026-10-26 21:01:11.000'),(243,'CAND-G1B-092','formal','multi','面面平行判定可用（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"一面内两相交直线分别平行于另一面\"}, {\"id\": \"B\", \"text\": \"两平面分别平行于同一直线\"}, {\"id\": \"C\", \"text\": \"两平面平行于同一平面\"}, {\"id\": \"D\", \"text\": \"一面内两直线都平行于另一面\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\"]}','面面平行常用判定：若一个平面内的两条相交直线分别平行于另一个平面，则可判定两平面平行（A）；若两平面都平行于同一平面，则由传递性也平行（C）。B 仅“分别平行于同一直线”不够；D 若两直线平行（不相交），即使都平行于另一面，也不能推出面面平行（可能相交或重合情形需另论）。故选 A、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,76,176,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:26.158','2026-10-26 16:43:23.549','2026-10-26 17:17:26.000'),(244,'CAND-G1B-093','formal','application','正方体 $ABCD-A_1B_1C_1D_1$ 中，证明 $BD_1\\perp$ 平面 $A_1C_1D$（写出关键步骤）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"l1\", \"title\": \"证一条\", \"criteria\": \"$BD_1\\\\perp A_1C_1$\", \"maxScore\": 4}, {\"key\": \"l2\", \"title\": \"证另一条\", \"criteria\": \"$BD_1\\\\perp A_1D$\", \"maxScore\": 4}, {\"key\": \"c\", \"title\": \"结论\", \"criteria\": \"线面垂直\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"$BD_1\\\\perp A_1C_1$ 且 $BD_1\\\\perp A_1D$，故 $BD_1\\\\perp$ 平面 $A_1C_1D$。\"}','建立坐标系：取 $A=(0,0,0)$，$B=(1,0,0)$，$C=(1,1,0)$，$D=(0,1,0)$，$A_1=(0,0,1)$，$C_1=(1,1,1)$，$D_1=(0,1,1)$（棱长取 $1$，由相似性不影响垂直关系）。\n\n则 $\\overrightarrow{BD_1}=D_1-B=(-1,1,1)$，$\\overrightarrow{A_1C_1}=(1,1,0)$，$\\overrightarrow{A_1D}=(0,1,-1)$。\n\n计算数量积：\n$\\overrightarrow{BD_1}\\cdot\\overrightarrow{A_1C_1}=-1+1+0=0$，故 $BD_1\\perp A_1C_1$；\n$\\overrightarrow{BD_1}\\cdot\\overrightarrow{A_1D}=0+1-1=0$，故 $BD_1\\perp A_1D$。\n\n又 $A_1C_1$ 与 $A_1D$ 交于 $A_1$，且均在平面 $A_1C_1D$ 内，由线面垂直判定定理得 $BD_1\\perp$ 平面 $A_1C_1D$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,23,77,178,'approved',1,'v1',3,2,2,2,'2026-10-26 21:49:35.671','2026-10-26 16:43:23.555','2026-10-26 21:49:35.000'),(245,'CAND-G1B-094','formal','single','简单随机抽样每个个体被抽中概率','{\"options\": [{\"id\": \"A\", \"text\": \"不相等\"}, {\"id\": \"B\", \"text\": \"相等\"}, {\"id\": \"C\", \"text\": \"递增\"}, {\"id\": \"D\", \"text\": \"递减\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','简单随机抽样的核心要求是：总体中每一个个体被抽中的概率都相等（等可能性）。这是它与分层抽样、系统抽样等相区别的基本特征，故选 B。若各个体抽中概率不相等，则不属于简单随机抽样范畴。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,24,79,180,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:26.375','2026-10-26 16:43:23.559','2026-10-26 17:17:26.000'),(246,'CAND-G1B-095','formal','application','抛硬币 $200$ 次出现正面 $96$ 次，估计正面概率。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"f\", \"title\": \"频率\", \"criteria\": \"0.48\", \"maxScore\": 3}, {\"key\": \"i\", \"title\": \"解释\", \"criteria\": \"估计概率\", \"maxScore\": 3}], \"maxScore\": 6, \"standardAnswer\": \"$\\\\hat p=0.48$。\"}','用频率估计概率：在 $n=200$ 次独立抛掷中，正面出现 $96$ 次，频率为 $f=\\dfrac{96}{200}=0.48$。因此取估计值 $\\hat p=0.48$。由频率稳定性（大数定律思想），试验次数较大时频率通常接近真实概率，该估计较为可信；但估计值本身仍可能有随机偏差，不必等于理论 $0.5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,24,80,182,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:26.475','2026-10-26 16:43:23.562','2026-10-26 17:17:26.000'),(247,'CAND-G1B-096','formal','judge','样本相关系数 $r$ 越接近 $1$，线性相关程度一定越强。',NULL,'{\"kind\": \"judge\", \"value\": false}','样本相关系数 $r\\in[-1,1]$。线性相关强弱应看 $|r|$ 是否接近 $1$：$r\\to1$ 表示强正相关，$r\\to-1$ 表示强负相关（同样“很强”）。命题只说“越接近 $1$ 一定越强”，忽略了接近 $-1$ 的情形，表述不准确；此外相关也不等于因果。故命题错误（false）。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,24,81,185,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:26.609','2026-10-26 16:43:23.565','2026-10-26 17:17:26.000'),(248,'CAND-G1B-097','formal','single','掷一枚骰子，样本空间元素个数为','{\"options\": [{\"id\": \"A\", \"text\": \"$4$\"}, {\"id\": \"B\", \"text\": \"$5$\"}, {\"id\": \"C\", \"text\": \"$6$\"}, {\"id\": \"D\", \"text\": \"$7$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','掷一枚公平骰子，可能结果为点数 $1,2,3,4,5,6$，样本空间 $\\Omega=\\{1,2,3,4,5,6\\}$，含 $6$ 个基本事件。选 C。若不考虑点数而谈朝向等，题意通常仍按六点古典概型处理。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,25,82,187,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:26.698','2026-10-26 16:43:23.571','2026-10-26 17:17:26.000'),(249,'CAND-G1B-098','formal','application','袋中 $3$ 红 $2$ 白，随机取 $2$ 球，求恰有一红的概率。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"n\", \"title\": \"总数\", \"criteria\": \"10\", \"maxScore\": 3}, {\"key\": \"m\", \"title\": \"有利\", \"criteria\": \"6\", \"maxScore\": 3}, {\"key\": \"p\", \"title\": \"概率\", \"criteria\": \"3/5\", \"maxScore\": 2}], \"maxScore\": 8, \"standardAnswer\": \"$P=\\\\dfrac35$。\"}','古典概型：袋中共 $5$ 球，任取 $2$ 球，基本事件总数为 $C_5^2=10$。事件“恰有一红”（即一红一白）的取法：$C_3^1\\cdot C_2^1=3\\times2=6$。故概率 $P=\\dfrac{6}{10}=\\dfrac{3}{5}$。也可列：两红 $C_3^2=3$，两白 $C_2^2=1$，一红一白 $6$，总和 $10$，一致。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,25,82,188,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:26.810','2026-10-26 16:43:23.575','2026-10-26 17:17:26.000'),(250,'CAND-G1B-099','formal','numeric','独立事件 $A,B$，$P(A)=0.4$，$P(B)=0.5$，则 $P(AB)=$',NULL,'{\"kind\": \"numeric\", \"value\": \"0.2\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','若事件 $A$、$B$ 相互独立，则积事件概率等于各自概率之积：$P(AB)=P(A)P(B)$。代入 $P(A)=0.4$、$P(B)=0.5$ 得 $0.4\\times0.5=0.2$。注意独立与互斥不同：互斥时一般有 $P(AB)=0$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,25,83,190,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:26.912','2026-10-26 16:43:23.578','2026-10-26 17:17:26.000'),(251,'CAND-G1B-100','formal','application','说明：为何试验次数增大时，正面频率往往更接近 $0.5$？（简述）',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"p\", \"title\": \"概率\", \"criteria\": \"0.5\", \"maxScore\": 2}, {\"key\": \"s\", \"title\": \"稳定\", \"criteria\": \"次数增大\", \"maxScore\": 2}, {\"key\": \"l\", \"title\": \"定律思想\", \"criteria\": \"大数定律\", \"maxScore\": 2}], \"maxScore\": 6, \"standardAnswer\": \"试验次数增大，随机波动相对减小，频率稳定于概率 $0.5$ 附近（大数定律思想）。\"}','大数定律（频率稳定性）表明：在独立重复试验中，当试验次数 $n$ 充分大时，某事件发生的频率会依概率收敛到它的理论概率。抛硬币正面的理论概率为 $0.5$，因此 $n$ 增大时正面频率通常更接近 $0.5$，相对随机波动减小。这并不保证每一次实验都精确等于 $0.5$，而是“稳定于概率附近”的直观含义。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,25,84,192,'approved',1,'v1',1,2,2,2,'2026-10-26 17:17:27.025','2026-10-26 16:43:23.666','2026-10-26 17:17:27.000'),(275,'CAND-G2A-001','formal','single','集合 $A=\\{x\\in\\mathbb{Z}\\mid x^2\\le4\\}$ 用列举法表示正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{-2,-1,0,1,2\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{-2,-1,1,2\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{-2,0,2\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{0,\\\\pm1,\\\\pm2,\\\\pm3\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','由 $x\\in\\mathbb{Z}$ 且 $x^2\\le4$，得 $|x|\\le2$，故 $x=-2,-1,0,1,2$。列举为 $\\{-2,-1,0,1,2\\}$，选 A。B 漏 $0$；C 漏 $\\pm1$；D 含 $\\pm3$（$9>4$），不满足。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,16,31,2,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:34.349','2026-10-27 08:43:05.367','2026-10-27 08:45:34.000'),(276,'CAND-G2A-002','formal','multi','下列能使 $A=B$ 的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$A=\\\\{1,2\\\\}$，$B=\\\\{x\\\\mid x^2-3x+2=0\\\\}$\"}, {\"id\": \"B\", \"text\": \"$A=\\\\{0\\\\}$，$B=\\\\{x\\\\mid x^2=0\\\\}$\"}, {\"id\": \"C\", \"text\": \"$A=\\\\varnothing$，$B=\\\\{0\\\\}$\"}, {\"id\": \"D\", \"text\": \"$A=\\\\{a,b\\\\}$，$B=\\\\{b,a\\\\}$（$a\\\\ne b$）\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','A：方程 $x^2-3x+2=0$ 根为 $1,2$，故 $B=\\{1,2\\}=A$。B：$x^2=0\\Rightarrow x=0$，故 $B=\\{0\\}=A$。C：空集与 $\\{0\\}$ 不等。D：集合与元素次序无关，$\\{a,b\\}=\\{b,a\\}$。故 A、B、D。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,16,32,5,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:34.530','2026-10-27 08:43:05.374','2026-10-27 08:45:34.000'),(277,'CAND-G2A-003','formal','numeric','$A=\\{x\\in\\mathbb{N}^*\\mid x\\le6\\}$，$B=\\{x\\mid x\\text{为质数}\\}$，则 $|A\\cap B|=$',NULL,'{\"kind\": \"numeric\", \"value\": \"3\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$A=\\{1,2,3,4,5,6\\}$。$A$ 中质数为 $2,3,5$，故 $A\\cap B=\\{2,3,5\\}$，$|A\\cap B|=3$。注意 $1$ 不是质数。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,16,33,7,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:34.714','2026-10-27 08:43:05.379','2026-10-27 08:45:34.000'),(278,'CAND-G2A-004','formal','numeric','全集 $U=\\{1,2,3,4,5\\}$，$A=\\{1,3,5\\}$，则 $|\\complement_U A|=$',NULL,'{\"kind\": \"numeric\", \"value\": \"2\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$\\complement_U A=U\\setminus A=\\{2,4\\}$，故基数为 $2$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,16,33,8,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:35.338','2026-10-27 08:43:05.384','2026-10-27 08:45:35.000'),(279,'CAND-G2A-005','formal','judge','判断：“$x>2$”是“$x>1$”的充分不必要条件。',NULL,'{\"kind\": \"judge\", \"value\": true}','若 $x>2$，则必有 $x>1$，故充分。反之 $x=1.5$ 满足 $x>1$ 但不满足 $x>2$，故不必要。因此是充分不必要条件，判断正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,16,34,10,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:35.562','2026-10-27 08:43:05.388','2026-10-27 08:45:35.000'),(280,'CAND-G2A-006','formal','application','某班 $40$ 人，会游泳 $A$ 有 $22$ 人，会骑车 $B$ 有 $25$ 人，两项都会的有 $12$ 人。\n（1）求只会其中一项技能的人数；\n（2）求两项都不会的人数。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"union\", \"title\": \"并集人数\", \"criteria\": \"$|A\\\\cup B|=35$\", \"maxScore\": 3}, {\"key\": \"only1\", \"title\": \"只会一项\", \"criteria\": \"$23$ 人\", \"maxScore\": 3}, {\"key\": \"none\", \"title\": \"都不会\", \"criteria\": \"$5$ 人\", \"maxScore\": 2}], \"maxScore\": 8, \"standardAnswer\": \"（1）$23$；（2）$5$。\"}','由容斥：$|A\\cup B|=|A|+|B|-|A\\cap B|=22+25-12=35$。只会一项：$|A\\cup B|-|A\\cap B|=35-12=23$（或 $(22-12)+(25-12)=10+13=23$）。两项都不会：$40-35=5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,16,33,9,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:35.757','2026-10-27 08:43:05.392','2026-10-27 08:45:35.000'),(281,'CAND-G2A-007','formal','single','若 $a=b$，则下列不一定成立的是','{\"options\": [{\"id\": \"A\", \"text\": \"$a+c=b+c$\"}, {\"id\": \"B\", \"text\": \"$ac=bc$\"}, {\"id\": \"C\", \"text\": \"$a^2=b^2$\"}, {\"id\": \"D\", \"text\": \"$\\\\dfrac{1}{a}=\\\\dfrac{1}{b}$（未限定 $a,b\\\\ne0$）\"}]}','{\"kind\": \"single\", \"optionId\": \"D\"}','等式两边同加任意实数、同乘任意实数、两边平方在实数范围内均保持相等，故 A、B、C 成立。D 在 $a=b=0$ 时无意义，题干未排除零，故不一定成立，选 D。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,17,38,46,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:36.048','2026-10-27 08:43:05.397','2026-10-27 08:45:36.000'),(282,'CAND-G2A-008','formal','numeric','比较大小：设 $a=\\dfrac{3}{5}$，$b=\\dfrac{4}{7}$。若 $a>b$ 填 $1$，$a=b$ 填 $0$，$a<b$ 填 $-1$，则应填',NULL,'{\"kind\": \"numeric\", \"value\": \"1\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','作差：$a-b=\\dfrac{3}{5}-\\dfrac{4}{7}=\\dfrac{21-20}{35}=\\dfrac{1}{35}>0$，故 $a>b$，填 $1$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,17,38,44,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:36.221','2026-10-27 08:43:05.401','2026-10-27 08:45:36.000'),(283,'CAND-G2A-009','formal','judge','判断：对任意实数 $a,b$，都有 $\\dfrac{a+b}{2}\\ge\\sqrt{ab}$。',NULL,'{\"kind\": \"judge\", \"value\": false}','基本不等式要求 $a,b\\ge0$（且通常讨论算术—几何平均时取非负）。若 $a=-1,b=-4$，则左边 $\\dfrac{-5}{2}=-2.5$，右边 $\\sqrt{4}=2$，$-2.5\\ge2$ 不成立；即使同号为负，几何平均在实数中也可能无意义。故命题对“任意实数”不成立。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,17,39,47,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:36.405','2026-10-27 08:43:05.405','2026-10-27 08:45:36.000'),(284,'CAND-G2A-010','formal','single','已知 $x>0$，则 $x+\\dfrac{4}{x}$ 的最小值为','{\"options\": [{\"id\": \"A\", \"text\": \"$2$\"}, {\"id\": \"B\", \"text\": \"$4$\"}, {\"id\": \"C\", \"text\": \"$8$\"}, {\"id\": \"D\", \"text\": \"$1$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','$x>0$ 时，$x+\\dfrac{4}{x}\\ge2\\sqrt{x\\cdot\\dfrac{4}{x}}=2\\sqrt{4}=4$，等号当 $x=\\dfrac{4}{x}$ 即 $x=2$ 时成立。故最小值为 $4$，选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,17,39,48,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:36.604','2026-10-27 08:43:05.409','2026-10-27 08:45:36.000'),(285,'CAND-G2A-011','formal','multi','关于不等式 $(x-1)(x-4)<0$ 的解集，下列说法正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"解集为 $(1,4)$\"}, {\"id\": \"B\", \"text\": \"解集可写成 $\\\\{x\\\\mid 1<x<4\\\\}$\"}, {\"id\": \"C\", \"text\": \"$x=2$ 是解\"}, {\"id\": \"D\", \"text\": \"$x=1$ 是解\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','开口向上型乘积小于 $0$，根为 $1,4$，解集为开区间 $(1,4)$，故 A、B 对。$x=2\\in(1,4)$ 是解；$x=1$ 使式子为 $0$，不满足严格不等，D 错。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,17,40,52,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:36.863','2026-10-27 08:43:05.413','2026-10-27 08:45:36.000'),(286,'CAND-G2A-012','formal','application','已知方程 $x^2-5x+m=0$ 有两个相等实根。\n（1）求 $m$；\n（2）求该重根。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"m\", \"title\": \"参数\", \"criteria\": \"$m=25/4$\", \"maxScore\": 3}, {\"key\": \"root\", \"title\": \"重根\", \"criteria\": \"$x=5/2$\", \"maxScore\": 3}], \"maxScore\": 6, \"standardAnswer\": \"（1）$m=\\\\dfrac{25}{4}$；（2）$x=\\\\dfrac{5}{2}$。\"}','等根 $\\Leftrightarrow\\Delta=25-4m=0\\Rightarrow m=\\dfrac{25}{4}$。重根 $x=\\dfrac{5}{2}$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,17,40,51,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:37.067','2026-10-27 08:43:05.417','2026-10-27 08:45:37.000'),(287,'CAND-G2A-013','formal','application','某商品进价 $40$ 元/件，售价 $60$ 元/件。店铺日固定开支 $200$ 元。设日销量为 $x$ 件（$x\\in\\mathbb{N}^*$）。\n（1）写出日利润 $P(x)$；\n（2）日利润不少于 $300$ 元时，销量至少多少件？',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"model\", \"title\": \"利润函数\", \"criteria\": \"$P(x)=20x-200$\", \"maxScore\": 3}, {\"key\": \"ineq\", \"title\": \"不等式\", \"criteria\": \"$x\\\\ge25$\", \"maxScore\": 3}, {\"key\": \"conc\", \"title\": \"结论\", \"criteria\": \"至少25件\", \"maxScore\": 2}], \"maxScore\": 8, \"standardAnswer\": \"（1）$P(x)=20x-200$；（2）$25$ 件。\"}','单件毛利 $20$ 元，故 $P(x)=20x-200$。要求 $20x-200\\ge300\\Rightarrow20x\\ge500\\Rightarrow x\\ge25$。销量取正整数，至少 $25$ 件。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,17,38,45,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:37.259','2026-10-27 08:43:05.422','2026-10-27 08:45:37.000'),(288,'CAND-G2A-014','formal','single','$f(x)=x^2-4x+1$ 在区间 $[0,3]$ 上的最小值是','{\"options\": [{\"id\": \"A\", \"text\": \"$1$\"}, {\"id\": \"B\", \"text\": \"$-3$\"}, {\"id\": \"C\", \"text\": \"$-2$\"}, {\"id\": \"D\", \"text\": \"$0$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','配方 $f(x)=(x-2)^2-3$，开口向上，对称轴 $x=2\\in[0,3]$，故区间最小值为顶点值 $-3$。端点：$f(0)=1$，$f(3)=9-12+1=-2$，均大于 $-3$。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,17,40,54,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:37.459','2026-10-27 08:43:05.425','2026-10-27 08:45:37.000'),(289,'CAND-G2A-015','formal','application','用篱笆围一块矩形菜地，一面靠墙（该边不围篱笆）。现有篱笆长 $24\\,\\mathrm{m}$。设垂直于墙的边长为 $x\\,\\mathrm{m}$（$0<x<12$）。\n（1）表示面积 $S(x)$；\n（2）求面积最大值及相应 $x$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"expr\", \"title\": \"面积表达式\", \"criteria\": \"$S=24x-2x^2$\", \"maxScore\": 3}, {\"key\": \"xmax\", \"title\": \"最优边长\", \"criteria\": \"$x=6$\", \"maxScore\": 3}, {\"key\": \"smax\", \"title\": \"最大面积\", \"criteria\": \"$72$\", \"maxScore\": 4}], \"maxScore\": 10, \"standardAnswer\": \"（1）$S(x)=x(24-2x)=24x-2x^2$；（2）最大面积 $72\\\\,\\\\mathrm{m}^2$，此时 $x=6$。\"}','平行于墙的边长为 $24-2x$，故 $S=x(24-2x)=24x-2x^2$。配方或基本不等式思想：开口向下抛物线，顶点 $x=-\\dfrac{b}{2a}=\\dfrac{24}{4}=6$，且 $6\\in(0,12)$，故 $S_{\\max}=24\\cdot6-2\\cdot36=144-72=72$。也可用 $S=2\\cdot x\\cdot(12-x)\\le2\\left(\\dfrac{x+(12-x)}{2}\\right)^2=72$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,17,39,50,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:37.668','2026-10-27 08:43:05.430','2026-10-27 08:45:37.000'),(290,'CAND-G2A-016','formal','single','若方程 $x^2-2kx+k+2=0$ 有两个大于 $0$ 的实根，则 $k$ 的取值范围是','{\"options\": [{\"id\": \"A\", \"text\": \"$k>2$\"}, {\"id\": \"B\", \"text\": \"$k\\\\ge2$\"}, {\"id\": \"C\", \"text\": \"$k>1$\"}, {\"id\": \"D\", \"text\": \"$k\\\\ge -1$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','设 $f(x)=x^2-2kx+k+2$。两正根条件：$\\Delta\\ge0$，和 $2k>0$，积 $k+2>0$。计算 $\\Delta=4k^2-4(k+2)=4(k^2-k-2)=4(k-2)(k+1)\\ge0\\Rightarrow k\\le-1$ 或 $k\\ge2$；又 $k>0$，$k>-2$。综合得 $k\\ge2$。当 $k=2$ 时 $\\Delta=0$，重根 $x=2>0$，成立。故选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,17,40,55,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:37.959','2026-10-27 08:43:05.434','2026-10-27 08:45:37.000'),(291,'CAND-G2A-017','formal','single','函数 $f(x)=\\dfrac{\\sqrt{x-1}}{x-3}$ 的定义域是','{\"options\": [{\"id\": \"A\", \"text\": \"$[1,+\\\\infty)$\"}, {\"id\": \"B\", \"text\": \"$[1,3)\\\\cup(3,+\\\\infty)$\"}, {\"id\": \"C\", \"text\": \"$(1,3)\\\\cup(3,+\\\\infty)$\"}, {\"id\": \"D\", \"text\": \"$[1,3]$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','需 $x-1\\ge0$ 且 $x-3\\ne0$，即 $x\\ge1$ 且 $x\\ne3$，故定义域 $[1,3)\\cup(3,+\\infty)$，选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,41,17,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:38.142','2026-10-27 08:43:05.439','2026-10-27 08:45:38.000'),(292,'CAND-G2A-018','formal','numeric','设 $f(x)=2x-5$，则 $f(f(3))=$',NULL,'{\"kind\": \"numeric\", \"value\": \"-3\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$f(3)=6-5=1$，$f(f(3))=f(1)=2-5=-3$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,41,25,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:38.326','2026-10-27 08:43:05.442','2026-10-27 08:45:38.000'),(293,'CAND-G2A-019','formal','judge','判断：函数 $f(x)=x$ 与 $g(x)=\\dfrac{x^2}{x}$ 是同一个函数。',NULL,'{\"kind\": \"judge\", \"value\": false}','$g(x)=\\dfrac{x^2}{x}$ 要求 $x\\ne0$，定义域为 $\\{x\\mid x\\ne0\\}$，而 $f(x)=x$ 定义域为 $\\mathbb{R}$。定义域不同，不是同一函数。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,41,20,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:38.492','2026-10-27 08:43:05.446','2026-10-27 08:45:38.000'),(294,'CAND-G2A-020','formal','multi','下列函数在 $(0,+\\infty)$ 上单调递增的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$y=x^2$\"}, {\"id\": \"B\", \"text\": \"$y=\\\\sqrt{x}$\"}, {\"id\": \"C\", \"text\": \"$y=\\\\dfrac{1}{x}$\"}, {\"id\": \"D\", \"text\": \"$y=2x+1$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','在 $(0,+\\infty)$：$x^2$ 导数 $2x>0$ 或作差可证递增；$\\sqrt{x}$ 递增；$\\dfrac{1}{x}$ 递减；$2x+1$ 递增。故 A、B、D。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,42,29,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:38.676','2026-10-27 08:43:05.449','2026-10-27 08:45:38.000'),(295,'CAND-G2A-021','formal','single','已知 $f(x)=x^3$ 在 $\\mathbb{R}$ 上单调递增。若 $f(a)>f(2)$，则','{\"options\": [{\"id\": \"A\", \"text\": \"$a>2$\"}, {\"id\": \"B\", \"text\": \"$a<2$\"}, {\"id\": \"C\", \"text\": \"$a>8$\"}, {\"id\": \"D\", \"text\": \"$a=2$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','严格增函数保持不等号方向：$f(a)>f(2)\\Leftrightarrow a>2$，选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,42,26,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:38.926','2026-10-27 08:43:05.453','2026-10-27 08:45:38.000'),(296,'CAND-G2A-022','formal','numeric','函数 $f(x)=-x^2+2x+3$ 的最大值为',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$f(x)=-(x-1)^2+4$，开口向下，最大值 $4$（在 $x=1$ 处）。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,42,31,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:39.109','2026-10-27 08:43:05.458','2026-10-27 08:45:39.000'),(297,'CAND-G2A-023','formal','application','设 $f(x)=\\begin{cases} 2x+1, & x<1,\\\\ x^2-2, & x\\ge1. \\end{cases}$\n（1）求 $f(0)+f(3)$；\n（2）若 $f(t)=7$，求 $t$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"v\", \"title\": \"求值\", \"criteria\": \"$f(0)+f(3)=8$\", \"maxScore\": 3}, {\"key\": \"case\", \"title\": \"分类\", \"criteria\": \"按 $t<1$ 与 $t\\\\ge1$ 讨论\", \"maxScore\": 2}, {\"key\": \"t\", \"title\": \"求 t\", \"criteria\": \"$t=3$\", \"maxScore\": 3}], \"maxScore\": 8, \"standardAnswer\": \"（1）$8$；（2）$t=3$。\"}','（1）$f(0)=1$，$f(3)=9-2=7$，和为 $8$。（2）若 $t<1$，则 $2t+1=7\\Rightarrow t=3$，与 $t<1$ 矛盾；若 $t\\ge1$，则 $t^2-2=7\\Rightarrow t^2=9\\Rightarrow t=3$（$t=-3$ 舍）。故 $t=3$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,41,24,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:39.292','2026-10-27 08:43:05.463','2026-10-27 08:45:39.000'),(298,'CAND-G2A-024','formal','single','函数 $f(x)=x^3\\cos x$ 是','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶\"}, {\"id\": \"D\", \"text\": \"非奇非偶\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','定义域 $\\mathbb{R}$ 关于原点对称。$f(-x)=(-x)^3\\cos(-x)=-x^3\\cos x=-f(x)$，故为奇函数，选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,42,35,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:39.493','2026-10-27 08:43:05.467','2026-10-27 08:45:39.000'),(299,'CAND-G2A-025','formal','multi','下列函数在所给定义域上是奇函数的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$f(x)=x+\\\\dfrac{1}{x}$（定义域 $\\\\{x\\\\mid x\\\\ne0\\\\}$）\"}, {\"id\": \"B\", \"text\": \"$f(x)=\\\\sqrt{x}$，定义域 $[0,+\\\\infty)$\"}, {\"id\": \"C\", \"text\": \"$f(x)=x|x|$，定义域 $\\\\mathbb{R}$\"}, {\"id\": \"D\", \"text\": \"$f(x)=\\\\ln\\\\dfrac{1-x}{1+x}$（定义域 $(-1,1)$）\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','奇函数要求定义域关于原点对称，且 $f(-x)=-f(x)$。B 的定义域 $[0,+\\infty)$ 不关于原点对称，故不是奇函数。A：$f(-x)=-x-\\dfrac{1}{x}=-f(x)$，是奇函数。C：$f(-x)=(-x)|-x|=-x|x|=-f(x)$，是奇函数。D：定义域 $(-1,1)$ 对称，且 $f(-x)=\\ln\\dfrac{1+x}{1-x}=-\\ln\\dfrac{1-x}{1+x}=-f(x)$，是奇函数。故选 A、C、D。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,18,42,34,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:39.684','2026-10-27 08:43:05.471','2026-10-27 08:45:39.000'),(300,'CAND-G2A-026','formal','single','下列函数中是幂函数的是','{\"options\": [{\"id\": \"A\", \"text\": \"$y=2x^{1/2}$\"}, {\"id\": \"B\", \"text\": \"$y=x^2+1$\"}, {\"id\": \"C\", \"text\": \"$y=x^{-1}$\"}, {\"id\": \"D\", \"text\": \"$y=(x+1)^2$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','幂函数形如 $y=x^{\\alpha}$（系数为 $1$）。A 多了系数 $2$；B、D 不是纯幂形式。C：$y=x^{-1}$ 是幂函数，选 C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,18,43,38,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:39.878','2026-10-27 08:43:05.476','2026-10-27 08:45:39.000'),(301,'CAND-G2A-027','formal','application','某商店促销：购买 $x$ 件商品（$x\\in\\mathbb{N}^*$）时，单价（元/件）为\n$p(x)=\\begin{cases} 50, & 1\\le x\\le 10,\\\\ 45, & x\\ge 11. \\end{cases}$\n总费用 $T(x)=x\\,p(x)$。\n（1）求 $T(8)$ 与 $T(12)$；\n（2）若预算不超过 $500$ 元，最多可买多少件？',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"vals\", \"title\": \"分段求值\", \"criteria\": \"$T(8)=400$，$T(12)=540$\", \"maxScore\": 3}, {\"key\": \"ineq\", \"title\": \"分段约束\", \"criteria\": \"分别讨论 $1\\\\le x\\\\le10$ 与 $x>10$ 得可行上界\", \"maxScore\": 4}, {\"key\": \"max\", \"title\": \"最多件数\", \"criteria\": \"最多 $11$ 件\", \"maxScore\": 3}], \"maxScore\": 10, \"standardAnswer\": \"（1）$T(8)=400$，$T(12)=540$；（2）最多 $11$ 件。\"}','（1）$8\\le10$，故 $T(8)=8\\times50=400$；$12\\ge11$，故 $T(12)=12\\times45=540$。（2）当 $1\\le x\\le10$ 时，$50x\\le500\\Rightarrow x\\le10$，该段最多 $10$ 件；当 $x\\ge11$ 时，$45x\\le500\\Rightarrow x\\le\\dfrac{500}{45}=11\\dfrac{1}{9}$，正整数取 $x\\le11$，且 $T(11)=495\\le500$，$T(12)=540>500$。综合两段，最多可买 $11$ 件。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,18,44,61,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:40.068','2026-10-27 08:43:05.480','2026-10-27 08:45:40.000'),(302,'CAND-G2A-028','formal','numeric','已知幂函数 $y=x^{1/3}$ 在 $\\mathbb{R}$ 上单调递增。比较 $a=(-8)^{1/3}$ 与 $b=(-1)^{1/3}$：若 $a>b$ 填 $1$，$a=b$ 填 $0$，$a<b$ 填 $-1$，则应填',NULL,'{\"kind\": \"numeric\", \"value\": \"-1\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','因 $y=x^{1/3}$ 在 $\\mathbb{R}$ 递增，且 $-8<-1$，故 $(-8)^{1/3}<(-1)^{1/3}$，即 $a<b$，填 $-1$。直接计算：$a=-2$，$b=-1$，确实 $-2<-1$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,18,43,41,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:40.295','2026-10-27 08:43:05.484','2026-10-27 08:45:40.000'),(303,'CAND-G2A-029','formal','single','$\\sqrt[3]{-8}$ 的值是','{\"options\": [{\"id\": \"A\", \"text\": \"$-2$\"}, {\"id\": \"B\", \"text\": \"$2$\"}, {\"id\": \"C\", \"text\": \"$\\\\pm2$\"}, {\"id\": \"D\", \"text\": \"无意义\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','立方根在实数中唯一：$(-2)^3=-8$，故 $\\sqrt[3]{-8}=-2$，选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,48,65,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:40.512','2026-10-27 08:43:05.489','2026-10-27 08:45:40.000'),(304,'CAND-G2A-030','formal','numeric','$16^{3/4}=$',NULL,'{\"kind\": \"numeric\", \"value\": \"8\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$16^{3/4}=(16^{1/4})^3=2^3=8$，或 $(16^3)^{1/4}$。亦可 $16^{3/4}=(2^4)^{3/4}=2^3=8$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,48,66,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:40.728','2026-10-27 08:43:05.492','2026-10-27 08:45:40.000'),(305,'CAND-G2A-031','formal','multi','下列指数运算正确的有（多选；涉及除法时默认底数 $a\\ne0$）','{\"options\": [{\"id\": \"A\", \"text\": \"$a^3\\\\cdot a^2=a^5$\"}, {\"id\": \"B\", \"text\": \"$(a^2)^3=a^6$\"}, {\"id\": \"C\", \"text\": \"$\\\\dfrac{a^5}{a^2}=a^3$\"}, {\"id\": \"D\", \"text\": \"$(ab)^2=a^2+b^2$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A：同底数幂相乘，指数相加，正确。B：幂的乘方，指数相乘，正确。C：同底数幂相除，指数相减（题干已声明 $a\\ne0$），正确。D：$(ab)^2=a^2b^2$，不是 $a^2+b^2$，错误。故 A、B、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,48,67,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:40.954','2026-10-27 08:43:05.496','2026-10-27 08:45:40.000'),(306,'CAND-G2A-032','formal','judge','判断：$y=2^x$ 的定义域是 $\\mathbb{R}$，值域是 $(0,+\\infty)$。',NULL,'{\"kind\": \"judge\", \"value\": true}','指数函数 $y=a^x$（$a>0,a\\ne1$）定义域为实数集，值域为正实数集。$a=2$ 符合，命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,49,69,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:41.134','2026-10-27 08:43:05.499','2026-10-27 08:45:41.000'),(307,'CAND-G2A-033','formal','single','若 $0.5^{m}>0.5^{n}$，则','{\"options\": [{\"id\": \"A\", \"text\": \"$m>n$\"}, {\"id\": \"B\", \"text\": \"$m<n$\"}, {\"id\": \"C\", \"text\": \"$m=n$\"}, {\"id\": \"D\", \"text\": \"$m,n$ 符号相反\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','底数 $0.5\\in(0,1)$，指数函数递减，故 $0.5^{m}>0.5^{n}\\Leftrightarrow m<n$，选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,49,70,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:41.371','2026-10-27 08:43:05.503','2026-10-27 08:45:41.000'),(308,'CAND-G2A-034','formal','numeric','已知 $\\log_4(x-1)+\\log_2(x-1)=3$，且 $x>1$。求 $x$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','令 $t=\\log_2(x-1)$（因 $x>1$，有 $x-1>0$，对数有意义）。由换底公式 $\\log_4(x-1)=\\dfrac{\\log_2(x-1)}{\\log_2 4}=\\dfrac{t}{2}$。原方程化为 $\\dfrac{t}{2}+t=3$，即 $\\dfrac{3t}{2}=3$，故 $t=2$。于是 $\\log_2(x-1)=2$，得 $x-1=2^2=4$，所以 $x=5$。检验：代入后 $\\log_4 4+\\log_2 4=1+2=3$，成立。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,19,50,75,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:41.587','2026-10-27 08:43:05.506','2026-10-27 08:45:41.000'),(309,'CAND-G2A-035','formal','single','$\\log_3 18-\\log_3 2$ 等于','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\log_3 16$\"}, {\"id\": \"B\", \"text\": \"$\\\\log_3 36$\"}, {\"id\": \"C\", \"text\": \"$2$\"}, {\"id\": \"D\", \"text\": \"$\\\\log_3 20$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','$\\log_3 18-\\log_3 2=\\log_3\\dfrac{18}{2}=\\log_3 9=2$，选 C。A、B、D 均不等于 $2$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,50,74,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:41.803','2026-10-27 08:43:05.511','2026-10-27 08:45:41.000'),(310,'CAND-G2A-036','formal','multi','下列等式正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\log_2 5=\\\\dfrac{\\\\ln5}{\\\\ln2}$\"}, {\"id\": \"B\", \"text\": \"$\\\\log_2 5=\\\\dfrac{\\\\lg5}{\\\\lg2}$\"}, {\"id\": \"C\", \"text\": \"$\\\\log_2 5=\\\\dfrac{1}{\\\\log_5 2}$\"}, {\"id\": \"D\", \"text\": \"$\\\\log_2 5=\\\\log_5 2$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','换底公式与倒数为倒数：$\\log_b a=\\dfrac{\\log_k a}{\\log_k b}=\\dfrac{1}{\\log_a b}$。A、B、C 对；D 把倒数量相等，错。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,50,75,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:41.984','2026-10-27 08:43:05.514','2026-10-27 08:45:41.000'),(311,'CAND-G2A-037','formal','single','函数 $y=\\log_{1/2}x$ 的定义域是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\mathbb{R}$\"}, {\"id\": \"B\", \"text\": \"$(0,+\\\\infty)$\"}, {\"id\": \"C\", \"text\": \"$[0,+\\\\infty)$\"}, {\"id\": \"D\", \"text\": \"$(1,+\\\\infty)$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','对数真数须大于 $0$，与底无关（底已合法），故定义域 $(0,+\\infty)$，选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,19,51,77,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:42.301','2026-10-27 08:43:05.518','2026-10-27 08:45:42.000'),(312,'CAND-G2A-038','formal','numeric','若 $\\log_{1/3}m>\\log_{1/3}n$，且 $m,n>0$，比较 $m$ 与 $n$：若 $m>n$ 填 $1$，$m=n$ 填 $0$，$m<n$ 填 $-1$，则应填',NULL,'{\"kind\": \"numeric\", \"value\": \"-1\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','底 $\\dfrac{1}{3}\\in(0,1)$，对数函数递减，故 $\\log_{1/3}m>\\log_{1/3}n\\Leftrightarrow m<n$，填 $-1$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,51,78,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:42.484','2026-10-27 08:43:05.522','2026-10-27 08:45:42.000'),(313,'CAND-G2A-039','formal','application','某菌群初始数量 $N_0=100$，每小时变为原来的 $1.5$ 倍。设 $t$ 小时后数量为 $N(t)$。\n（1）写出 $N(t)$；\n（2）求使 $N(t)=100\\times 1.5^{4}$ 的 $t$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"model\", \"title\": \"写出增长模型\", \"criteria\": \"得 $N(t)=100\\\\cdot 1.5^{t}$（或等价写法）\", \"maxScore\": 3}, {\"key\": \"eq\", \"title\": \"建立方程\", \"criteria\": \"由 $N(t)=100\\\\cdot 1.5^{4}$ 得到 $1.5^{t}=1.5^{4}$（或等价方程）\", \"maxScore\": 3}, {\"key\": \"solve\", \"title\": \"求解 t\", \"criteria\": \"利用单调性/换底得出 $t=4$（须有推理，不得仅写“读指数”）\", \"maxScore\": 2}], \"maxScore\": 8, \"standardAnswer\": \"（1）$N(t)=100\\\\cdot1.5^{t}$；（2）$4$ 小时。\"}','（1）指数增长：$N(t)=N_0\\cdot 1.5^{t}=100\\cdot 1.5^{t}$。\n（2）由 $100\\cdot 1.5^{t}=100\\cdot 1.5^{4}$，两边同除以 $100$ 得 $1.5^{t}=1.5^{4}$。指数函数 $y=1.5^{t}$ 在 $\\mathbb{R}$ 上单调，故 $t=4$。亦可用换底：$t=\\log_{1.5}(1.5^{4})=4$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,19,52,80,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:42.668','2026-10-27 08:43:05.525','2026-10-27 08:45:42.000'),(314,'CAND-G2A-040','formal','application','声音强度级 $L=10\\lg\\dfrac{I}{I_0}$（单位 dB）。若某声音强度 $I=10^5 I_0$，求 $L$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"sub\", \"title\": \"代入\", \"criteria\": \"$L=10\\\\lg10^5$\", \"maxScore\": 2}, {\"key\": \"calc\", \"title\": \"计算\", \"criteria\": \"$50$\", \"maxScore\": 4}], \"maxScore\": 6, \"standardAnswer\": \"$L=50$（dB）。\"}','$L=10\\lg(10^5)=10\\cdot5=50$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,52,81,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:42.876','2026-10-27 08:43:05.529','2026-10-27 08:45:42.000'),(315,'CAND-G2A-041','formal','single','方程 $4^x-5\\cdot2^x+4=0$ 的解的个数是','{\"options\": [{\"id\": \"A\", \"text\": \"$0$\"}, {\"id\": \"B\", \"text\": \"$1$\"}, {\"id\": \"C\", \"text\": \"$2$\"}, {\"id\": \"D\", \"text\": \"$3$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','令 $t=2^x>0$，则 $t^2-5t+4=0\\Rightarrow(t-1)(t-4)=0$，$t=1$ 或 $t=4$。即 $2^x=1\\Rightarrow x=0$；$2^x=4\\Rightarrow x=2$。两解，选 C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,19,49,71,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:43.043','2026-10-27 08:43:05.532','2026-10-27 08:45:43.000'),(316,'CAND-G2A-042','formal','judge','判断：$y=\\log_2 x$ 与 $y=2^x$ 的图象关于直线 $y=x$ 对称。',NULL,'{\"kind\": \"judge\", \"value\": true}','互为反函数的图象关于 $y=x$ 对称。$y=\\log_2 x$ 与 $y=2^x$ 互为反函数，故命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,19,51,79,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:43.226','2026-10-27 08:43:05.537','2026-10-27 08:45:43.000'),(317,'CAND-G2A-043','formal','single','$150^\\circ$ 化为弧度是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\dfrac{5\\\\pi}{6}$\"}, {\"id\": \"B\", \"text\": \"$\\\\dfrac{2\\\\pi}{3}$\"}, {\"id\": \"C\", \"text\": \"$\\\\dfrac{5\\\\pi}{3}$\"}, {\"id\": \"D\", \"text\": \"$\\\\dfrac{3\\\\pi}{4}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$150^\\circ=150\\cdot\\dfrac{\\pi}{180}=\\dfrac{5\\pi}{6}$，选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,55,97,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:43.417','2026-10-27 08:43:05.541','2026-10-27 08:45:43.000'),(318,'CAND-G2A-044','formal','numeric','与角 $-\\dfrac{3\\pi}{4}$ 终边相同且位于 $[0,2\\pi)$ 的角是 $\\dfrac{k\\pi}{4}$，则正整数 $k=$',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$-\\dfrac{3\\pi}{4}+2\\pi=\\dfrac{5\\pi}{4}$，故 $k=5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,55,96,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:43.592','2026-10-27 08:43:05.544','2026-10-27 08:45:43.000'),(319,'CAND-G2A-045','formal','application','半径为 $6$ 的圆中，圆心角为 $\\dfrac{2\\pi}{3}$ 的扇形。\n（1）求弧长 $l$；\n（2）求扇形面积 $S$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"arc\", \"title\": \"弧长\", \"criteria\": \"$4\\\\pi$\", \"maxScore\": 4}, {\"key\": \"area\", \"title\": \"面积\", \"criteria\": \"$12\\\\pi$\", \"maxScore\": 4}], \"maxScore\": 8, \"standardAnswer\": \"（1）$l=4\\\\pi$；（2）$S=12\\\\pi$。\"}','弧长 $l=r\\theta=6\\cdot\\dfrac{2\\pi}{3}=4\\pi$。扇形面积 $S=\\dfrac{1}{2}r^2\\theta=\\dfrac{1}{2}\\cdot36\\cdot\\dfrac{2\\pi}{3}=12\\pi$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,55,98,'approved',1,'v1',2,2,2,2,'2026-10-27 08:45:43.776','2026-10-27 08:43:05.548','2026-10-27 08:45:43.000'),(320,'CAND-G2A-046','formal','single','角 $\\alpha$ 终边上一点 $P(3,-4)$，则 $\\sin\\alpha=$','{\"options\": [{\"id\": \"A\", \"text\": \"$-\\\\dfrac{4}{5}$\"}, {\"id\": \"B\", \"text\": \"$\\\\dfrac{4}{5}$\"}, {\"id\": \"C\", \"text\": \"$-\\\\dfrac{3}{5}$\"}, {\"id\": \"D\", \"text\": \"$\\\\dfrac{3}{5}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$r=\\sqrt{3^2+(-4)^2}=5$，$\\sin\\alpha=\\dfrac{y}{r}=\\dfrac{-4}{5}$，选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,56,99,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:43.952','2026-10-27 08:43:05.633','2026-10-27 08:45:43.000'),(321,'CAND-G2A-047','formal','multi','若 $\\sin\\theta=-\\dfrac{3}{5}$ 且 $\\theta$ 在第三象限，则正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\cos\\\\theta=-\\\\dfrac{4}{5}$\"}, {\"id\": \"B\", \"text\": \"$\\\\tan\\\\theta=\\\\dfrac{3}{4}$\"}, {\"id\": \"C\", \"text\": \"$\\\\cos\\\\theta=\\\\dfrac{4}{5}$\"}, {\"id\": \"D\", \"text\": \"$\\\\tan\\\\theta=-\\\\dfrac{3}{4}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\"]}','第三象限余弦为负：$\\cos\\theta=-\\sqrt{1-\\sin^2\\theta}=-\\dfrac{4}{5}$。$\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}=\\dfrac{-3/5}{-4/5}=\\dfrac{3}{4}$。故 A、B 对；C、D 错。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,56,100,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:44.169','2026-10-27 08:43:05.636','2026-10-27 08:45:44.000'),(322,'CAND-G2A-048','formal','numeric','$\\sin\\left(\\pi+\\dfrac{\\pi}{6}\\right)=$（填小数）',NULL,'{\"kind\": \"numeric\", \"value\": \"-0.5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','由诱导公式 $\\sin(\\pi+\\alpha)=-\\sin\\alpha$，得 $-\\sin\\dfrac{\\pi}{6}=-\\dfrac12=-0.5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,57,102,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:44.384','2026-10-27 08:43:05.640','2026-10-27 08:45:44.000'),(323,'CAND-G2A-049','formal','single','函数 $y=\\sin x$ 的最小正周期是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\pi$\"}, {\"id\": \"B\", \"text\": \"$2\\\\pi$\"}, {\"id\": \"C\", \"text\": \"$\\\\dfrac{\\\\pi}{2}$\"}, {\"id\": \"D\", \"text\": \"$4\\\\pi$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','正弦函数最小正周期为 $2\\pi$，选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,58,105,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:44.600','2026-10-27 08:43:05.644','2026-10-27 08:45:44.000'),(324,'CAND-G2A-050','formal','judge','判断：$y=\\cos x$ 是偶函数。',NULL,'{\"kind\": \"judge\", \"value\": true}','$\\cos(-x)=\\cos x$，定义域 $\\mathbb{R}$ 对称，故为偶函数。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,20,58,106,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:44.817','2026-10-27 08:43:05.647','2026-10-27 08:45:44.000'),(325,'CAND-G2A-051','formal','application','已知 $\\cos\\alpha=\\dfrac{3}{5}$，且 $\\alpha$ 为锐角。\n（1）求 $\\sin\\alpha$；\n（2）求 $\\cos 2\\alpha$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"sin\", \"title\": \"正弦\", \"criteria\": \"$4/5$\", \"maxScore\": 3}, {\"key\": \"double\", \"title\": \"二倍角余弦\", \"criteria\": \"$-7/25$\", \"maxScore\": 5}], \"maxScore\": 8, \"standardAnswer\": \"（1）$\\\\sin\\\\alpha=\\\\dfrac{4}{5}$；（2）$\\\\cos 2\\\\alpha=-\\\\dfrac{7}{25}$。\"}','锐角正弦为正：$\\sin\\alpha=\\sqrt{1-\\left(\\dfrac{3}{5}\\right)^2}=\\dfrac{4}{5}$。$\\cos2\\alpha=2\\cos^2\\alpha-1=2\\cdot\\dfrac{9}{25}-1=-\\dfrac{7}{25}$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,59,109,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:45.034','2026-10-27 08:43:05.652','2026-10-27 08:45:45.000'),(326,'CAND-G2A-052','formal','multi','下列恒等式正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\sin(A+B)=\\\\sin A\\\\cos B+\\\\cos A\\\\sin B$\"}, {\"id\": \"B\", \"text\": \"$\\\\cos(A-B)=\\\\cos A\\\\cos B+\\\\sin A\\\\sin B$\"}, {\"id\": \"C\", \"text\": \"$\\\\sin(A-B)=\\\\sin A\\\\cos B-\\\\cos A\\\\sin B$\"}, {\"id\": \"D\", \"text\": \"$\\\\cos(A+B)=\\\\cos A\\\\cos B+\\\\sin A\\\\sin B$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A、B、C 为标准和差公式。D 中 $\\cos(A+B)$ 应为 $\\cos A\\cos B-\\sin A\\sin B$，符号错误。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,59,108,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:45.252','2026-10-27 08:43:05.656','2026-10-27 08:45:45.000'),(327,'CAND-G2A-053','formal','application','已知 $y=3\\sin\\left(2x-\\dfrac{\\pi}{3}\\right)$。\n（1）求振幅与最小正周期；\n（2）求当 $x=0$ 时的函数值。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"amp\", \"title\": \"振幅\", \"criteria\": \"$3$\", \"maxScore\": 2}, {\"key\": \"T\", \"title\": \"周期\", \"criteria\": \"$\\\\pi$\", \"maxScore\": 4}, {\"key\": \"val\", \"title\": \"x=0 值\", \"criteria\": \"$-\\\\dfrac{3\\\\sqrt{3}}{2}$\", \"maxScore\": 4}], \"maxScore\": 10, \"standardAnswer\": \"（1）振幅 $3$，周期 $\\\\pi$；（2）$-\\\\dfrac{3\\\\sqrt{3}}{2}$。\"}','振幅 $A=3$，$\\omega=2$，周期 $T=\\dfrac{2\\pi}{|\\omega|}=\\pi$。$x=0$ 时，$y=3\\sin\\left(-\\dfrac{\\pi}{3}\\right)=3\\left(-\\dfrac{\\sqrt{3}}{2}\\right)=-\\dfrac{3\\sqrt{3}}{2}$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,60,112,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:45.476','2026-10-27 08:43:05.660','2026-10-27 08:45:45.000'),(328,'CAND-G2A-054','formal','multi','要把 $y=\\sin x$ 的图象变成 $y=\\sin\\left(x-\\dfrac{\\pi}{4}\\right)$，正确叙述有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"向右平移 $\\\\dfrac{\\\\pi}{4}$ 个单位\"}, {\"id\": \"B\", \"text\": \"向左平移 $\\\\dfrac{\\\\pi}{4}$ 个单位\"}, {\"id\": \"C\", \"text\": \"平移后形状与周期不变\"}, {\"id\": \"D\", \"text\": \"需要先纵向伸长再平移\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\"]}','$y=\\sin(x-\\varphi)$（$\\varphi=\\pi/4>0$）由 $y=\\sin x$ 向右平移 $\\varphi$。振幅、周期不变，无需纵向伸缩。故 A、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,20,60,113,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:45.595','2026-10-27 08:43:05.663','2026-10-27 08:45:45.000'),(329,'CAND-G2A-055','formal','application','在水平地面上，测得某建筑物顶端的仰角为 $45^\\circ$，再向建筑物走近 $20\\,\\mathrm{m}$ 后，仰角变为 $60^\\circ$。设建筑物高度为 $h\\,\\mathrm{m}$。\n（1）建立关于 $h$ 的方程；\n（2）求 $h$（精确值）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"model\", \"title\": \"建模\", \"criteria\": \"两次仰角距离差为20\", \"maxScore\": 4}, {\"key\": \"eq\", \"title\": \"方程\", \"criteria\": \"$h-h/\\\\sqrt{3}=20$\", \"maxScore\": 4}, {\"key\": \"h\", \"title\": \"高度\", \"criteria\": \"$10(3+\\\\sqrt{3})$\", \"maxScore\": 4}], \"maxScore\": 12, \"standardAnswer\": \"（1）$h-\\\\dfrac{h}{\\\\sqrt{3}}=20$；（2）$h=10(3+\\\\sqrt{3})$。\"}','设第一次水平距离为 $d$。由仰角 $45^\\circ$ 得 $d=h/\\tan45^\\circ=h$；走近 $20\\,\\mathrm{m}$ 后仰角 $60^\\circ$，得 $d-20=h/\\tan60^\\circ=h/\\sqrt{3}$。故 $h-h/\\sqrt{3}=20$，即 $h\\dfrac{\\sqrt{3}-1}{\\sqrt{3}}=20$，所以 $h=\\dfrac{20\\sqrt{3}}{\\sqrt{3}-1}=\\dfrac{20\\sqrt{3}(\\sqrt{3}+1)}{2}=10\\sqrt{3}(\\sqrt{3}+1)=10(3+\\sqrt{3})$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,61,117,'approved',1,'v1',2,2,2,2,'2026-10-27 08:45:45.745','2026-10-27 08:43:05.667','2026-10-27 08:45:45.000'),(330,'CAND-G2A-056','formal','numeric','函数 $y=3\\sin x+4\\cos x$ 的最大值为',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$R=\\sqrt{3^2+4^2}=5$，故 $y=5\\left(\\dfrac{3}{5}\\sin x+\\dfrac{4}{5}\\cos x\\right)=5\\sin(x+\\varphi)$，最大值为 $5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,59,110,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:45.895','2026-10-27 08:43:05.672','2026-10-27 08:45:45.000'),(331,'CAND-G2A-057','formal','single','函数 $y=\\tan x$ 在 $\\left(-\\dfrac{\\pi}{2},\\dfrac{\\pi}{2}\\right)$ 上','{\"options\": [{\"id\": \"A\", \"text\": \"单调递增\"}, {\"id\": \"B\", \"text\": \"单调递减\"}, {\"id\": \"C\", \"text\": \"先增后减\"}, {\"id\": \"D\", \"text\": \"有最大值 $1$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','正切在每个连续开区间 $\\left(k\\pi-\\dfrac{\\pi}{2},k\\pi+\\dfrac{\\pi}{2}\\right)$ 内严格递增，主值区间亦然，选 A。无最大值。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,58,107,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:46.037','2026-10-27 08:43:05.676','2026-10-27 08:45:46.000'),(332,'CAND-G2A-058','formal','application','简谐振动位移 $s=A\\sin(\\omega t)$（$t$ 以秒计，$s$ 以厘米计）。已知振幅 $A=5$，周期 $T=4$。\n（1）求 $\\omega$ 并写出 $s(t)$；\n（2）求 $t=1$ 时的位移。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"omega\", \"title\": \"角频率\", \"criteria\": \"$\\\\omega=\\\\pi/2$\", \"maxScore\": 3}, {\"key\": \"expr\", \"title\": \"解析式\", \"criteria\": \"$s=5\\\\sin(\\\\pi t/2)$\", \"maxScore\": 3}, {\"key\": \"val\", \"title\": \"t=1 位移\", \"criteria\": \"$5$\", \"maxScore\": 4}], \"maxScore\": 10, \"standardAnswer\": \"（1）$\\\\omega=\\\\dfrac{\\\\pi}{2}$，$s=5\\\\sin\\\\dfrac{\\\\pi t}{2}$；（2）$s(1)=5$。\"}','$\\omega=\\dfrac{2\\pi}{T}=\\dfrac{2\\pi}{4}=\\dfrac{\\pi}{2}$，故 $s=5\\sin\\dfrac{\\pi t}{2}$。$t=1$ 时 $s=5\\sin\\dfrac{\\pi}{2}=5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,20,61,115,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:46.170','2026-10-27 08:43:05.680','2026-10-27 08:45:46.000'),(333,'CAND-G2A-059','formal','single','下列物理量中，属于向量的是','{\"options\": [{\"id\": \"A\", \"text\": \"位移\"}, {\"id\": \"B\", \"text\": \"温度\"}, {\"id\": \"C\", \"text\": \"质量\"}, {\"id\": \"D\", \"text\": \"时间\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','向量是既有大小又有方向的量。位移有大小（路程长度）与方向，属于向量；温度、质量、时间只有大小没有方向，是标量。故选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,62,127,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:46.328','2026-10-27 08:43:05.684','2026-10-27 08:45:46.000'),(334,'CAND-G2A-060','formal','judge','两个向量相等的充要条件是它们的方向相同且模相等。',NULL,'{\"kind\": \"judge\", \"value\": true}','教材定义：方向相同且模长相等的向量叫做相等向量。作为自由向量，起点可平移，故该充要条件正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,62,129,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:46.470','2026-10-27 08:43:05.687','2026-10-27 08:45:46.000'),(335,'CAND-G2A-061','formal','numeric','设 $\\vec a=(-5,12)$，则 $|\\vec a|=$',NULL,'{\"kind\": \"numeric\", \"value\": \"13\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$|\\vec a|=\\sqrt{(-5)^2+12^2}=\\sqrt{25+144}=\\sqrt{169}=13$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,62,128,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:46.611','2026-10-27 08:43:05.691','2026-10-27 08:45:46.000'),(336,'CAND-G2A-062','formal','single','用平行四边形法则作 $\\vec a+\\vec b$ 时，对角线表示','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\vec a+\\\\vec b$\"}, {\"id\": \"B\", \"text\": \"$\\\\vec a-\\\\vec b$\"}, {\"id\": \"C\", \"text\": \"$\\\\vec a\\\\cdot\\\\vec b$\"}, {\"id\": \"D\", \"text\": \"$|\\\\vec a|+|\\\\vec b|$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','以 $\\vec a,\\vec b$ 为邻边作平行四边形，从公共起点出发的对角线即为和向量 $\\vec a+\\vec b$。故选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,63,131,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:46.761','2026-10-27 08:43:06.319','2026-10-27 08:45:46.000'),(337,'CAND-G2A-063','formal','multi','关于平面向量数量积，正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\vec a\\\\cdot\\\\vec a=|\\\\vec a|^2$\"}, {\"id\": \"B\", \"text\": \"若 $\\\\vec a\\\\perp\\\\vec b$，则 $\\\\vec a\\\\cdot\\\\vec b=0$\"}, {\"id\": \"C\", \"text\": \"$|\\\\vec a\\\\cdot\\\\vec b|\\\\le|\\\\vec a||\\\\vec b|$\"}, {\"id\": \"D\", \"text\": \"$\\\\vec a\\\\cdot\\\\vec b=|\\\\vec a|+|\\\\vec b|$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A 由定义 $\\vec a\\cdot\\vec a=|\\vec a||\\vec a|\\cos0=|\\vec a|^2$。B 为垂直⇔数量积为 $0$（含零向量约定）。C 由 $|\\cos\\theta|\\le1$ 得柯西型不等式。D 把数量积误写成模长相加，错误。故选 A、B、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,63,132,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:46.903','2026-10-27 08:43:06.323','2026-10-27 08:45:46.000'),(338,'CAND-G2A-064','formal','numeric','设 $\\vec a=(2,3)$，$\\vec b=(-1,4)$，则 $\\vec a\\cdot\\vec b=$',NULL,'{\"kind\": \"numeric\", \"value\": \"10\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$\\vec a\\cdot\\vec b=2\\cdot(-1)+3\\cdot4=-2+12=10$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,63,132,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:47.028','2026-10-27 08:43:06.327','2026-10-27 08:45:47.000'),(339,'CAND-G2A-065','formal','single','设 $\\vec a=(1,0)$，$\\vec b=(1,1)$，则 $\\vec a$ 与 $\\vec b$ 的夹角为','{\"options\": [{\"id\": \"A\", \"text\": \"$30^\\\\circ$\"}, {\"id\": \"B\", \"text\": \"$45^\\\\circ$\"}, {\"id\": \"C\", \"text\": \"$60^\\\\circ$\"}, {\"id\": \"D\", \"text\": \"$90^\\\\circ$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','$\\cos\\theta=\\dfrac{\\vec a\\cdot\\vec b}{|\\vec a||\\vec b|}=\\dfrac{1}{1\\cdot\\sqrt{2}}=\\dfrac{\\sqrt{2}}{2}$，故 $\\theta=45^\\circ$。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,63,133,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:47.153','2026-10-27 08:43:06.331','2026-10-27 08:45:47.000'),(340,'CAND-G2A-066','formal','application','已知 $\\vec a=(3,4)$，$\\vec b=(1,0)$。求 $\\vec a$ 在 $\\vec b$ 方向上的投影（数量投影）及投影向量。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"scalar\", \"title\": \"数量投影\", \"criteria\": \"得数量投影 $3$\", \"maxScore\": 4}, {\"key\": \"vec\", \"title\": \"投影向量\", \"criteria\": \"得投影向量 $(3,0)$\", \"maxScore\": 4}], \"maxScore\": 8, \"standardAnswer\": \"数量投影为 $3$；投影向量为 $(3,0)$。\"}','$\\vec b$ 方向单位向量 $\\vec e=\\dfrac{\\vec b}{|\\vec b|}=(1,0)$。数量投影 $\\vec a\\cdot\\vec e=3$。投影向量 $(\\vec a\\cdot\\vec e)\\vec e=(3,0)$。亦可由 $\\mathrm{proj}_{\\vec b}\\vec a=\\dfrac{\\vec a\\cdot\\vec b}{|\\vec b|^2}\\vec b=\\dfrac{3}{1}(1,0)=(3,0)$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,63,134,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:47.303','2026-10-27 08:43:06.334','2026-10-27 08:45:47.000'),(341,'CAND-G2A-067','formal','single','平面向量基本定理中，作为基底的两个向量必须','{\"options\": [{\"id\": \"A\", \"text\": \"互相垂直\"}, {\"id\": \"B\", \"text\": \"模长相等\"}, {\"id\": \"C\", \"text\": \"不共线\"}, {\"id\": \"D\", \"text\": \"单位向量\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','平面内任意向量可由两个不共线向量唯一线性表出。基底只需不共线，不必垂直、等长或单位化。故选 C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,64,136,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:47.445','2026-10-27 08:43:06.338','2026-10-27 08:45:47.000'),(342,'CAND-G2A-068','formal','numeric','点 $A(1,2)$，$B(4,6)$，则 $|\\overrightarrow{AB}|=$',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$\\overrightarrow{AB}=(4-1,6-2)=(3,4)$，$|\\overrightarrow{AB}|=\\sqrt{9+16}=5$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,21,64,137,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:47.569','2026-10-27 08:43:06.342','2026-10-27 08:45:47.000'),(343,'CAND-G2A-069','formal','multi','设 $\\vec a=(x_1,y_1)$，$\\vec b=(x_2,y_2)$ 且 $\\vec b\\ne\\vec 0$。下列与“$\\vec a$ 与 $\\vec b$ 共线”等价的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"存在实数 $\\\\lambda$ 使 $\\\\vec a=\\\\lambda\\\\vec b$\"}, {\"id\": \"B\", \"text\": \"$x_1y_2-x_2y_1=0$\"}, {\"id\": \"C\", \"text\": \"$\\\\vec a\\\\cdot\\\\vec b=0$\"}, {\"id\": \"D\", \"text\": \"$\\\\dfrac{x_1}{x_2}=\\\\dfrac{y_1}{y_2}$（当 $x_2y_2\\\\ne0$）\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','共线⇔存在 $\\lambda$ 使 $\\vec a=\\lambda\\vec b$（A）；坐标上⇔行列式 $x_1y_2-x_2y_1=0$（B）；分量比相等（分母非零时）即 D。C 是垂直条件，与共线无关。故选 A、B、D。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,64,138,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:47.694','2026-10-27 08:43:06.829','2026-10-27 08:45:47.000'),(344,'CAND-G2A-070','formal','application','小船先向东航行 $6\\,\\mathrm{km}$，再向北航行 $8\\,\\mathrm{km}$。求合位移的大小与方向（相对正东的偏角）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"mag\", \"title\": \"大小\", \"criteria\": \"得 $|\\\\vec s|=10$\", \"maxScore\": 4}, {\"key\": \"dir\", \"title\": \"方向\", \"criteria\": \"正确给出偏角（东偏北 $\\\\arctan4/3$ 或等价表述）\", \"maxScore\": 4}], \"maxScore\": 8, \"standardAnswer\": \"合位移大小 $10\\\\,\\\\mathrm{km}$，方向为北偏东 $\\\\arctan\\\\dfrac{3}{4}$（或东偏北 $\\\\arctan\\\\dfrac{4}{3}$）。\"}','取东、北为正：$\\vec s_1=(6,0)$，$\\vec s_2=(0,8)$，合位移 $\\vec s=(6,8)$，$|\\vec s|=\\sqrt{36+64}=10$。设相对正东偏角为 $\\theta$，则 $\\tan\\theta=\\dfrac{8}{6}=\\dfrac{4}{3}$，即东偏北 $\\arctan\\dfrac{4}{3}$（等价北偏东 $\\arctan\\dfrac{3}{4}$）。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,21,65,141,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:47.844','2026-10-27 08:43:06.833','2026-10-27 08:45:47.000'),(345,'CAND-G2A-071','formal','application','在 $\\triangle ABC$ 中，$D$、$E$ 分别是边 $AB$、$AC$ 的中点。用向量方法证明：$DE\\parallel BC$ 且 $DE=\\dfrac12 BC$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"setup\", \"title\": \"设向量\", \"criteria\": \"合理设基向量并表示中点\", \"maxScore\": 3}, {\"key\": \"de\", \"title\": \"求DE\", \"criteria\": \"推出 $\\\\overrightarrow{DE}=\\\\dfrac12\\\\overrightarrow{BC}$\", \"maxScore\": 4}, {\"key\": \"conc\", \"title\": \"结论\", \"criteria\": \"由此得平行且比为1/2\", \"maxScore\": 3}], \"maxScore\": 10, \"standardAnswer\": \"$\\\\overrightarrow{DE}=\\\\dfrac12\\\\overrightarrow{BC}$，故 $DE\\\\parallel BC$ 且 $DE=\\\\dfrac12 BC$。\"}','设 $\\overrightarrow{AB}=\\vec b$，$\\overrightarrow{AC}=\\vec c$。则 $D$、$E$ 为中点：$\\overrightarrow{AD}=\\dfrac12\\vec b$，$\\overrightarrow{AE}=\\dfrac12\\vec c$。于是 $\\overrightarrow{DE}=\\overrightarrow{AE}-\\overrightarrow{AD}=\\dfrac12(\\vec c-\\vec b)=\\dfrac12\\overrightarrow{BC}$。故 $\\overrightarrow{DE}$ 与 $\\overrightarrow{BC}$ 共线同向且模长比为 $\\dfrac12$，即 $DE\\parallel BC$ 且 $DE=\\dfrac12 BC$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,21,65,143,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:47.978','2026-10-27 08:43:06.836','2026-10-27 08:45:47.000'),(346,'CAND-G2A-072','formal','numeric','已知力 $\\vec F=(3,4)$（单位 N）。质点从点 $A(1,2)$ 移动到点 $B(7,10)$（单位 m）。另有恒力 $\\vec G$ 与位移 $\\overrightarrow{AB}$ 方向相同，且 $|\\vec G|=5$（单位 N）。求合力 $\\vec F+\\vec G$ 对这段位移所做的总功 $W$（单位 J）。',NULL,'{\"kind\": \"numeric\", \"value\": \"100\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','位移 $\\overrightarrow{AB}=(7-1,10-2)=(6,8)$，其模 $|\\overrightarrow{AB}|=\\sqrt{6^2+8^2}=10$。\n$\\vec F$ 做功：$W_F=\\vec F\\cdot\\overrightarrow{AB}=3\\cdot6+4\\cdot8=18+32=50$。\n$\\vec G$ 与 $\\overrightarrow{AB}$ 同向且模为 $5$，故 $\\vec G=5\\cdot\\dfrac{\\overrightarrow{AB}}{|\\overrightarrow{AB}|}=5\\cdot\\left(\\dfrac{6}{10},\\dfrac{8}{10}\\right)=(3,4)$。\n$W_G=\\vec G\\cdot\\overrightarrow{AB}=5\\cdot10=50$（同向时功等于 $|\\vec G||\\overrightarrow{AB}|$）。\n总功 $W=W_F+W_G=100$。亦可用 $(\\vec F+\\vec G)\\cdot\\overrightarrow{AB}=(6,8)\\cdot(6,8)=36+64=100$ 复核。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,21,65,142,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:48.112','2026-10-27 08:43:06.840','2026-10-27 08:45:48.000'),(347,'CAND-G2A-073','formal','single','若复数 $a+bi=3-2i$（$a,b\\in\\mathbb{R}$），则 $a+b=$','{\"options\": [{\"id\": \"A\", \"text\": \"$1$\"}, {\"id\": \"B\", \"text\": \"$5$\"}, {\"id\": \"C\", \"text\": \"$-5$\"}, {\"id\": \"D\", \"text\": \"$0$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','复数相等⇔实部、虚部分别相等，故 $a=3$，$b=-2$，$a+b=1$。选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,22,69,159,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:48.236','2026-10-27 08:43:06.844','2026-10-27 08:45:48.000'),(348,'CAND-G2A-074','formal','application','计算 $\\dfrac{2-i}{1+i}$，并写成 $a+bi$（$a,b\\in\\mathbb{R}$）的形式。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"conj\", \"title\": \"乘共轭\", \"criteria\": \"分母有理化步骤正确\", \"maxScore\": 3}, {\"key\": \"exp\", \"title\": \"展开\", \"criteria\": \"分子展开得 $1-3i$（或等价）\", \"maxScore\": 3}, {\"key\": \"final\", \"title\": \"结果\", \"criteria\": \"得 $\\\\dfrac12-\\\\dfrac32 i$\", \"maxScore\": 2}], \"maxScore\": 8, \"standardAnswer\": \"$\\\\dfrac12-\\\\dfrac32 i$\"}','分子分母同乘 $1-i$：$\\dfrac{(2-i)(1-i)}{(1+i)(1-i)}=\\dfrac{2-2i-i+i^2}{1+1}=\\dfrac{2-3i-1}{2}=\\dfrac{1-3i}{2}=\\dfrac12-\\dfrac32 i$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,22,70,161,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:48.386','2026-10-27 08:43:06.847','2026-10-27 08:45:48.000'),(349,'CAND-G2A-075','formal','numeric','设 $z=5-12i$，则 $|z\\cdot\\overline{z}|=$',NULL,'{\"kind\": \"numeric\", \"value\": \"169\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$z\\overline{z}=|z|^2=5^2+(-12)^2=25+144=169$，故 $|z\\overline{z}|=|169|=169$（实数非负）。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,22,70,162,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:48.511','2026-10-27 08:43:06.851','2026-10-27 08:45:48.000'),(350,'CAND-G2A-076','formal','single','复数 $z=1+i$ 的三角形式为','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\sqrt{2}\\\\left(\\\\cos\\\\dfrac{\\\\pi}{4}+i\\\\sin\\\\dfrac{\\\\pi}{4}\\\\right)$\"}, {\"id\": \"B\", \"text\": \"$\\\\sqrt{2}\\\\left(\\\\cos\\\\dfrac{\\\\pi}{6}+i\\\\sin\\\\dfrac{\\\\pi}{6}\\\\right)$\"}, {\"id\": \"C\", \"text\": \"$2\\\\left(\\\\cos\\\\dfrac{\\\\pi}{4}+i\\\\sin\\\\dfrac{\\\\pi}{4}\\\\right)$\"}, {\"id\": \"D\", \"text\": \"$\\\\sqrt{2}\\\\left(\\\\cos\\\\dfrac{\\\\pi}{3}+i\\\\sin\\\\dfrac{\\\\pi}{3}\\\\right)$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$r=|z|=\\sqrt{1+1}=\\sqrt{2}$，$\\arg z=\\dfrac{\\pi}{4}$（第一象限）。故 $z=\\sqrt{2}\\left(\\cos\\dfrac{\\pi}{4}+i\\sin\\dfrac{\\pi}{4}\\right)$。选 A。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,22,71,164,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:48.670','2026-10-27 08:43:06.855','2026-10-27 08:45:48.000'),(351,'CAND-G2A-077','formal','judge','直棱柱的侧棱垂直于底面。',NULL,'{\"kind\": \"judge\", \"value\": true}','直棱柱定义：侧棱垂直于底面的棱柱。命题正确。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,23,72,165,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:48.811','2026-10-27 08:43:06.860','2026-10-27 08:45:48.000'),(352,'CAND-G2A-078','formal','multi','下列可作为简单组合体结构描述的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"圆柱上叠加一个同底圆锥\"}, {\"id\": \"B\", \"text\": \"长方体挖去一个内接圆柱孔\"}, {\"id\": \"C\", \"text\": \"两个全等的三棱锥底面重合粘成\"}, {\"id\": \"D\", \"text\": \"平面上的三角形与圆\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A、B、C 均为由柱、锥等基本立体经拼接或挖补得到的组合体。D 是平面图形，不是立体组合体。故选 A、B、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,23,72,166,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:48.953','2026-10-27 08:43:06.863','2026-10-27 08:45:48.000'),(353,'CAND-G2A-079','formal','single','用斜二测画法画水平放置的平面图形时，平行于 $y$ 轴的线段在直观图中的长度通常取为原来的','{\"options\": [{\"id\": \"A\", \"text\": \"不变\"}, {\"id\": \"B\", \"text\": \"$\\\\dfrac12$\"}, {\"id\": \"C\", \"text\": \"$2$ 倍\"}, {\"id\": \"D\", \"text\": \"$\\\\dfrac{\\\\sqrt{2}}{2}$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','斜二测约定：平行于 $x$、$z$ 轴的线段长度不变；平行于 $y$ 轴的线段取原来的 $\\dfrac12$。故选 B。本题考长度伸缩，不涉及直观图中夹角取值。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,73,167,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:49.086','2026-10-27 08:43:06.867','2026-10-27 08:45:49.000'),(354,'CAND-G2A-080','formal','numeric','棱长为 $3$ 的正方体体积为',NULL,'{\"kind\": \"numeric\", \"value\": \"27\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','正方体体积 $V=a^3=3^3=27$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,23,74,169,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:49.211','2026-10-27 08:43:06.870','2026-10-27 08:45:49.000'),(355,'CAND-G2A-081','formal','application','如图，正三棱锥 $P-ABC$ 的底面是边长为 $6$ 的正三角形，高 $PO=4$（$O$ 为底面中心）。求该三棱锥的体积。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"base\", \"title\": \"底面积\", \"criteria\": \"得 $S=9\\\\sqrt{3}$\", \"maxScore\": 4}, {\"key\": \"vol\", \"title\": \"体积\", \"criteria\": \"得 $V=12\\\\sqrt{3}$\", \"maxScore\": 4}], \"maxScore\": 8, \"standardAnswer\": \"$V=12\\\\sqrt{3}$\"}','底面积 $S=\\dfrac{\\sqrt{3}}{4}\\times6^2=9\\sqrt{3}$。体积 $V=\\dfrac13 Sh=\\dfrac13\\times9\\sqrt{3}\\times4=12\\sqrt{3}$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,74,170,'approved',1,'v1',2,2,2,2,'2026-10-27 08:45:49.353','2026-10-27 08:43:06.874','2026-10-27 08:45:49.000'),(356,'CAND-G2A-082','formal','application','圆柱底面半径 $r=3$，高 $h=8$。在其内部挖去一个与圆柱同轴、半径为 $3$ 的球（球完全位于圆柱内）。求剩余部分的体积。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"cyl\", \"title\": \"圆柱体积\", \"criteria\": \"得 $72\\\\pi$\", \"maxScore\": 3}, {\"key\": \"sph\", \"title\": \"球体积\", \"criteria\": \"得 $36\\\\pi$\", \"maxScore\": 3}, {\"key\": \"rem\", \"title\": \"剩余\", \"criteria\": \"得 $36\\\\pi$\", \"maxScore\": 2}], \"maxScore\": 8, \"standardAnswer\": \"$36\\\\pi$\"}','圆柱体积 $V_1=\\pi\\cdot 3^2\\cdot 8=72\\pi$。球体积 $V_2=\\dfrac{4}{3}\\pi\\cdot 3^3=36\\pi$。剩余 $V=V_1-V_2=36\\pi$。球直径 $6$ 小于柱高 $8$，可完全放入。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,23,74,171,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:49.494','2026-10-27 08:43:06.877','2026-10-27 08:45:49.000'),(357,'CAND-G2A-083','formal','single','若两条直线都与第三条直线平行，则这两条直线','{\"options\": [{\"id\": \"A\", \"text\": \"一定相交\"}, {\"id\": \"B\", \"text\": \"一定异面\"}, {\"id\": \"C\", \"text\": \"一定平行\"}, {\"id\": \"D\", \"text\": \"可能垂直\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','平行公理的推论：平行于同一条直线的两条直线互相平行。故选 C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,23,75,173,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:49.628','2026-10-27 08:43:06.881','2026-10-27 08:45:49.000'),(358,'CAND-G2A-084','formal','multi','如图，在正方体 $ABCD-A_1B_1C_1D_1$ 中，下列说法正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$AB$ 与 $A_1B_1$ 平行\"}, {\"id\": \"B\", \"text\": \"$AC$ 与 $A_1B$ 是异面直线\"}, {\"id\": \"C\", \"text\": \"$AA_1$ 与平面 $ABCD$ 相交\"}, {\"id\": \"D\", \"text\": \"$AC$ 与 $B_1D_1$ 相交\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A：上下对应棱平行。B：$AC$ 在底面，$A_1B$ 连上下底顶点，不共面且不相交，为异面。C：侧棱 $AA_1$ 交底面于 $A$。D：$AC$ 与 $B_1D_1$ 分别在平行的上下底面内，方向不平行且无交点，实为异面，并非相交。故选 A、B、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,75,174,'approved',1,'v1',2,2,2,2,'2026-10-27 08:45:49.745','2026-10-27 08:43:06.885','2026-10-27 08:45:49.000'),(359,'CAND-G2A-085','formal','judge','若直线与平面平行，则该直线与平面内任意一条直线都平行。',NULL,'{\"kind\": \"judge\", \"value\": false}','直线与平面平行时，它与平面内的直线只能平行或异面，不可能相交；但绝非“都平行”。例如与底面平行的一条空间直线，底面内方向不同的直线与它异面而不平行。故命题错误。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,76,175,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:49.895','2026-10-27 08:43:06.888','2026-10-27 08:45:49.000'),(360,'CAND-G2A-086','formal','application','如图，在长方体 $ABCD-A_1B_1C_1D_1$ 中，$E$、$F$ 分别为棱 $AA_1$、$CC_1$ 的中点。证明：$EF\\parallel$ 平面 $ABCD$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"vec\", \"title\": \"共线方向\", \"criteria\": \"证得 $EF\\\\parallel AC$（或坐标得方向相同）\", \"maxScore\": 4}, {\"key\": \"out\", \"title\": \"线在面外\", \"criteria\": \"说明 $E$、$F$ 不在底面\", \"maxScore\": 3}, {\"key\": \"conc\", \"title\": \"判定结论\", \"criteria\": \"得出 $EF\\\\parallel$ 平面 $ABCD$\", \"maxScore\": 3}], \"maxScore\": 10, \"standardAnswer\": \"$\\\\overrightarrow{EF}=\\\\overrightarrow{AC}$，故 $EF\\\\parallel AC$，又 $EF$ 不在平面 $ABCD$ 内，从而 $EF\\\\parallel$ 平面 $ABCD$。\"}','建立坐标：$A(0,0,0)$，$C(a,b,0)$，$A_1(0,0,c)$，$C_1(a,b,c)$，则 $E(0,0,c/2)$，$F(a,b,c/2)$，$\\overrightarrow{EF}=(a,b,0)=\\overrightarrow{AC}$。故 $EF\\parallel AC$，且 $AC\\subset$ 平面 $ABCD$。又 $E$ 的竖坐标 $c/2\\ne0$（$c>0$），$EF$ 不在底面内。由线面平行判定定理得 $EF\\parallel$ 平面 $ABCD$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,23,76,175,'approved',1,'v1',2,2,2,2,'2026-10-27 08:45:50.011','2026-10-27 08:43:06.892','2026-10-27 08:45:50.000'),(361,'CAND-G2A-087','formal','single','若直线 $l$ 垂直于平面 $\\alpha$，则 $l$ 与 $\\alpha$ 内任意一条直线的位置关系是','{\"options\": [{\"id\": \"A\", \"text\": \"平行\"}, {\"id\": \"B\", \"text\": \"相交垂直\"}, {\"id\": \"C\", \"text\": \"垂直（相交或异面垂直）\"}, {\"id\": \"D\", \"text\": \"异面\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','线面垂直定义：直线垂直于平面内所有直线。这种垂直包含相交垂直与异面垂直。故选 C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,77,177,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:50.136','2026-10-27 08:43:06.895','2026-10-27 08:45:50.000'),(362,'CAND-G2A-088','formal','application','如图，在直三棱柱 $ABC-A_1B_1C_1$ 中，$AB\\perp BC$，且 $AB=BC=AA_1=2$。证明：$AB_1\\perp$ 平面 $A_1BC$。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"l1\", \"title\": \"证⊥A1B\", \"criteria\": \"证得 $AB_1\\\\perp A_1B$\", \"maxScore\": 4}, {\"key\": \"l2\", \"title\": \"证⊥BC\", \"criteria\": \"证得 $AB_1\\\\perp BC$\", \"maxScore\": 4}, {\"key\": \"c\", \"title\": \"结论\", \"criteria\": \"得出线面垂直\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"$AB_1\\\\perp A_1B$ 且 $AB_1\\\\perp BC$，又 $A_1B$ 与 $BC$ 交于 $B$ 且都在平面 $A_1BC$ 内，故 $AB_1\\\\perp$ 平面 $A_1BC$。\"}','建系：$B(0,0,0)$，$C(2,0,0)$，$A(0,2,0)$，$A_1(0,2,2)$，$B_1(0,0,2)$。则 $\\overrightarrow{AB_1}=(0,-2,2)$，$\\overrightarrow{A_1B}=(0,-2,-2)$，$\\overrightarrow{BC}=(2,0,0)$。$\\overrightarrow{AB_1}\\cdot\\overrightarrow{A_1B}=0+4-4=0$，$\\overrightarrow{AB_1}\\cdot\\overrightarrow{BC}=0$。故 $AB_1\\perp A_1B$，$AB_1\\perp BC$。两相交直线 $A_1B$、$BC$ 确定平面 $A_1BC$，由线面垂直判定得证。本题用直三棱柱，避免正方体 $BD_1\\perp$ 平面 $A_1C_1D$ 旧题。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,23,77,178,'approved',1,'v1',2,2,2,2,'2026-10-27 08:45:50.362','2026-10-27 08:43:06.899','2026-10-27 08:45:50.000'),(363,'CAND-G2A-089','formal','multi','如图，正方体 $ABCD-A_1B_1C_1D_1$ 中，下列正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"平面 $ABB_1A_1\\\\perp$ 平面 $ABCD$\"}, {\"id\": \"B\", \"text\": \"平面 $ACC_1A_1\\\\perp$ 平面 $BDD_1B_1$\"}, {\"id\": \"C\", \"text\": \"平面 $ABC_1\\\\perp$ 平面 $ABB_1A_1$\"}, {\"id\": \"D\", \"text\": \"平面 $AA_1B_1B\\\\perp$ 平面 $ADD_1A_1$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','A：侧棱 $AA_1\\perp$ 底面且在侧面内，故侧面⊥底面。B：两对角截面法向量点积为 $0$，互相垂直。D：相邻侧面交线为侧棱，侧棱垂直于两底交线，故邻侧面互相垂直。C：平面 $ABB_1A_1$ 可取法向量 $(0,1,0)$；平面 $ABC_1$ 法向量可取 $(0,-1,1)$，点积 $-1\\ne0$，不垂直。故选 A、B、D。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,23,77,179,'approved',1,'v1',2,2,2,2,'2026-10-27 08:45:50.495','2026-10-27 08:43:06.962','2026-10-27 08:45:50.000'),(364,'CAND-G2A-090','formal','numeric','底面半径为 $3$，高为 $4$ 的圆锥体积为 $V$。求 $\\dfrac{V}{\\pi}$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"12\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$V=\\dfrac13\\pi r^2 h=\\dfrac13\\pi\\cdot9\\cdot4=12\\pi$，故 $\\dfrac{V}{\\pi}=12$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,23,74,170,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:50.620','2026-10-27 08:43:06.966','2026-10-27 08:45:50.000'),(365,'CAND-G2A-091','formal','single','简单随机抽样的特点是总体中每个个体被抽到的概率','{\"options\": [{\"id\": \"A\", \"text\": \"互不相同\"}, {\"id\": \"B\", \"text\": \"都相等\"}, {\"id\": \"C\", \"text\": \"与编号有关\"}, {\"id\": \"D\", \"text\": \"为零\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','简单随机抽样要求每个个体被抽中的概率相等。故选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,24,79,180,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:50.769','2026-10-27 08:43:06.970','2026-10-27 08:45:50.000'),(366,'CAND-G2A-092','formal','multi','关于分层抽样，正确的有（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"先按层划分总体再在各层抽样\"}, {\"id\": \"B\", \"text\": \"各层抽样比通常取相同\"}, {\"id\": \"C\", \"text\": \"适用于总体由差异明显的几部分组成\"}, {\"id\": \"D\", \"text\": \"系统抽样就是分层抽样\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A、B、C 均为分层抽样要点。D 混淆系统抽样与分层抽样，错误。故选 A、B、C。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,24,79,181,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:50.886','2026-10-27 08:43:06.973','2026-10-27 08:45:50.000'),(367,'CAND-G2A-093','formal','application','某校抽测 $5$ 名学生数学成绩（分）：$86,90,78,92,84$。求样本平均数与样本方差（用定义 $s^2=\\dfrac1n\\sum(x_i-\\bar x)^2$）。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"mean\", \"title\": \"平均数\", \"criteria\": \"得 $\\\\bar x=86$\", \"maxScore\": 3}, {\"key\": \"var\", \"title\": \"方差\", \"criteria\": \"得 $s^2=24$（按总体型除以 n）\", \"maxScore\": 5}], \"maxScore\": 8, \"standardAnswer\": \"$\\\\bar x=86$，$s^2=24$\"}','$\\bar x=\\dfrac{86+90+78+92+84}{5}=\\dfrac{430}{5}=86$。偏差：$0,4,-8,6,-2$，平方和 $0+16+64+36+4=120$，$s^2=\\dfrac{120}{5}=24$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,24,80,183,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:50.994','2026-10-27 08:43:06.977','2026-10-27 08:45:50.000'),(368,'CAND-G2A-094','formal','judge','线性回归方程一定经过样本点的每一个点。',NULL,'{\"kind\": \"judge\", \"value\": false}','最小二乘回归直线一般只保证残差平方和最小，通常不经过全部样本点（仅当点共线时才会全部落在直线上）。故命题错误。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,24,81,185,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:51.103','2026-10-27 08:43:06.980','2026-10-27 08:45:51.000'),(369,'CAND-G2A-095','formal','single','抛一枚质地均匀的硬币一次，样本空间的基本事件个数为','{\"options\": [{\"id\": \"A\", \"text\": \"1\"}, {\"id\": \"B\", \"text\": \"2\"}, {\"id\": \"C\", \"text\": \"3\"}, {\"id\": \"D\", \"text\": \"4\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','结果为正面或反面，共 $2$ 个基本事件。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,25,82,187,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:51.236','2026-10-27 08:43:06.983','2026-10-27 08:45:51.000'),(370,'CAND-G2A-096','formal','application','袋中有 $4$ 个红球、$3$ 个白球，从中随机取出 $2$ 个球。求两球颜色不同的概率。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"tot\", \"title\": \"总数\", \"criteria\": \"得 $\\\\mathrm{C}_7^2=21$\", \"maxScore\": 3}, {\"key\": \"fav\", \"title\": \"有利\", \"criteria\": \"得异色 $12$ 种\", \"maxScore\": 3}, {\"key\": \"p\", \"title\": \"概率\", \"criteria\": \"得 $\\\\dfrac{4}{7}$\", \"maxScore\": 2}], \"maxScore\": 8, \"standardAnswer\": \"$\\\\dfrac{4}{7}$\"}','基本事件总数 $\\mathrm{C}_7^2=21$。一红一白： $\\mathrm{C}_4^1\\mathrm{C}_3^1=12$。概率 $P=\\dfrac{12}{21}=\\dfrac{4}{7}$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,25,82,188,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:51.352','2026-10-27 08:43:06.987','2026-10-27 08:45:51.000'),(371,'CAND-G2A-097','formal','numeric','独立事件 $A,B$ 满足 $P(A)=0.3$，$P(B)=0.6$，则 $P(A\\cup B)=$',NULL,'{\"kind\": \"numeric\", \"value\": \"0.72\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','独立 ⇒ $P(AB)=P(A)P(B)=0.18$。$P(A\\cup B)=P(A)+P(B)-P(AB)=0.3+0.6-0.18=0.72$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,25,83,190,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:51.499','2026-10-27 08:43:06.991','2026-10-27 08:45:51.000'),(372,'CAND-G2A-098','formal','application','某射手每次射击命中率为 $0.8$，各次独立。求射击 $2$ 次恰命中 $1$ 次的概率。',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"cases\", \"title\": \"情形\", \"criteria\": \"列出两种顺序或用组合数\", \"maxScore\": 3}, {\"key\": \"comp\", \"title\": \"计算\", \"criteria\": \"得概率 $0.32$\", \"maxScore\": 5}], \"maxScore\": 8, \"standardAnswer\": \"$0.32$\"}','恰命中一次：第一次中第二次不中，或反之。$P=0.8\\times0.2+0.2\\times0.8=0.32$。亦可 $\\mathrm{C}_2^1(0.8)^1(0.2)^1=0.32$。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',3,25,83,191,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:51.627','2026-10-27 08:43:06.995','2026-10-27 08:45:51.000'),(373,'CAND-G2A-099','formal','single','用频率估计概率时，下列说法较合理的是','{\"options\": [{\"id\": \"A\", \"text\": \"试验一次的频率必等于概率\"}, {\"id\": \"B\", \"text\": \"试验次数充分大时，频率稳定于概率附近\"}, {\"id\": \"C\", \"text\": \"频率与概率毫无关系\"}, {\"id\": \"D\", \"text\": \"频率总比概率大\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','大数定律思想：大量重复试验下频率稳定在概率附近，可用频率估计概率。A、C、D 错误。选 B。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',2,25,84,193,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:51.744','2026-10-27 08:43:06.999','2026-10-27 08:45:51.000'),(374,'CAND-G2A-100','formal','application','简述：为什么在相同条件下大量重复抛掷一枚均匀硬币时，正面出现的频率往往会接近 $0.5$？',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"prob\", \"title\": \"概率\", \"criteria\": \"指出正面概率为 $0.5$\", \"maxScore\": 2}, {\"key\": \"lln\", \"title\": \"大数思想\", \"criteria\": \"说明次数大时频率稳定于概率\", \"maxScore\": 4}], \"maxScore\": 6, \"standardAnswer\": \"由大数定律思想，试验次数足够大时，随机事件频率稳定于其概率；均匀硬币正面概率为 $0.5$，故频率接近 $0.5$。\"}','均匀硬币正面概率为 $0.5$。大数定律思想指出：独立重复试验次数增大时，频率依概率收敛于概率，因而正面频率常接近 $0.5$。这不是“每一次都接近”，而是大量试验下的稳定性。','original',NULL,NULL,NULL,'本批原创；非高考真题',NULL,'unverified','unknown',1,25,84,192,'approved',1,'v1',1,2,2,2,'2026-10-27 08:45:51.894','2026-10-27 08:43:07.002','2026-10-27 08:45:51.000');
